(window.GAMES = window.GAMES || {})[1997] = [{"t":"20th Century Trivia Challenge","p":["Windows"],"d":"Telstar Electronic Studios","u":"Sir-Tech","g":"Trivia game","r":"August 15, 1997","l":"https://en.wikipedia.org/wiki/20th_Century_Trivia_Challenge"},{"t":"64 de Hakken!! Tamagotchi: Minna de Tamagotchi World","p":["Nintendo 64"],"d":"Hudson Soft","u":"Bandai","g":"Board game","r":"December 19, 1997","l":"https://en.wikipedia.org/wiki/64_de_Hakken!!_Tamagotchi:_Minna_de_Tamagotchi_World"},{"t":"64 Ōzumō","p":["Nintendo 64"],"d":"Bottom Up","u":"Bottom Up","g":"Sports, Fighting","r":"November 28, 1997","l":"https://en.wikipedia.org/wiki/64_%C5%8Czum%C5%8D"},{"t":"7 Wonders","p":["Windows"],"r":"Unknown","l":"https://en.wikipedia.org/wiki/7_Wonders_(video_game)"},{"t":"7th Legion","p":["Windows"],"d":"Epic MegaGames, Vision Software","u":"MicroProse","g":"Real-time strategy","r":"September 24, 1997","l":"https://en.wikipedia.org/wiki/7th_Legion_(video_game)"},{"t":"A Fork in the Tale","p":["Windows"],"d":"AnyRiver Entertainment","u":"Electronic Arts","g":"Adventure","r":"February 26, 1997","l":"https://en.wikipedia.org/wiki/A_Fork_in_the_Tale"},{"t":"ABC Sports Indy Racing","p":["Windows"],"d":"Shot Sports Software","u":"ABC Interactive","g":"Racing","l":"https://en.wikipedia.org/wiki/ABC_Sports_Indy_Racing"},{"t":"Ace Combat 2","p":["PlayStation"],"d":"Namco","u":"Namco, Namco Hometek, Sony Computer Entertainment","g":"Air combat simulation","r":"May 30, 1997","l":"https://en.wikipedia.org/wiki/Ace_Combat_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2pdj.jpg","s":"Ace Combat 2 serves as the follow-up to Namco's Air Combat, a combat flight simulator for the PlayStation. In this sequel, the player steps into the shoes of a mercenary pilot, determined to thwart a global terrorist conspiracy. With 30 challenging missions ahead, your triumphs will enable you to acquire weapon upgrades, parts, and various enhancements, mirroring the mechanics of the original game.\n\nEnhanced with crisper visuals and more immersive audio, Ace Combat 2 also boasts an expanded array of planes and customisable options. Additionally, it introduces dual shock support, along with the inclusion of analogue joystick support, enriching the overall gaming experience."},{"t":"Achaea, Dreams of Divine Lands","p":[],"d":"Iron Realms Entertainment","u":"Iron Realms Entertainment","g":"Fantasy MUD","l":"https://en.wikipedia.org/wiki/Achaea,_Dreams_of_Divine_Lands"},{"t":"Achtung Spitfire!","p":["Windows","macOS"],"d":"Big Time Software","u":"Avalon Hill","g":"Computer wargame","r":"September 3, 1997","l":"https://en.wikipedia.org/wiki/Achtung_Spitfire!"},{"t":"Actua Golf 2","p":["PlayStation"],"d":"Gremlin Interactive","u":"Gremlin Interactive, Fox Interactive","g":"Sports","r":"September 1997","l":"https://en.wikipedia.org/wiki/Actua_Golf_2"},{"t":"Actua Soccer 2","p":["PlayStation"],"d":"Gremlin Interactive","u":"Gremlin Interactive, Fox Interactive","g":"Sports","r":"November 1997","l":"https://en.wikipedia.org/wiki/Actua_Soccer_2"},{"t":"Adidas Power Soccer International 97","p":["PlayStation"],"d":"Psygnosis","u":"Psygnosis","g":"Sports","r":"April 11, 1997","l":"https://en.wikipedia.org/wiki/Adidas_Power_Soccer_International_97"},{"t":"Advanced NetWars","p":[],"l":"https://en.wikipedia.org/wiki/Advanced_NetWars"},{"t":"Adventures with Barbie: Ocean Discovery","p":["Windows"],"d":"Gorilla Systems Corporation, Realtime Associates","u":"Mattel Media","g":"Adventure","l":"https://en.wikipedia.org/wiki/Adventures_with_Barbie:_Ocean_Discovery"},{"t":"Aero Fighters Assault","p":["Nintendo 64"],"d":"Paradigm Entertainment","u":"Vic Tokai, Video System","g":"Combat flight simulation","r":"November 21, 1997","l":"https://en.wikipedia.org/wiki/Aero_Fighters_Assault"},{"t":"AeroGauge","p":["Nintendo 64"],"d":"Locomotive Co. Ltd.","u":"ASCII Entertainment","g":"Racing","r":"December 19, 1997","l":"https://en.wikipedia.org/wiki/AeroGauge","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co39yc.jpg","s":"In the tradition of F-Zero and Wipeout, AeroGauge is a sci-fi racer that pits you and a friend in a fast paced race to the finish through futuristic tracks and among detailed craft, acting more like planes than racers as they skim many metres above the ground. Play solo through the grand prix and compete against the AI enemy, or beat down your best time in the time trial mode.\n\nEach track features a number of twists and turns, whether it be racing upside down or vertically, with a number of obstacles in your path. There's no weapons, though, it's just you and the open road ahead."},{"t":"Age of Empires","p":["Windows","MS-DOS"],"g":"Strategy","r":"October 15","l":"https://en.wikipedia.org/wiki/Age_of_Empires_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1zsh.jpg","s":"Age of Empires (AoE) is a history-based real-time strategy video game developed by Ensemble Studios and published by Microsoft. The game uses the Genie, a 2D sprite-based game engine. The game allows the user to act as the leader of an ancient civilization by advancing it through four ages (the Stone, Tool, Bronze, and Iron Ages), gaining access to new and improved units with each advance."},{"t":"Agent Armstrong","p":["PlayStation"],"d":"King of the Jungle","u":"Virgin Interactive","g":"Platform","r":"September 18, 1997","l":"https://en.wikipedia.org/wiki/Agent_Armstrong"},{"t":"Air Warrior II","p":["Windows"],"d":"Kesmai","u":"Interactive Magic","g":"Combat flight simulator","r":"February 11, 1997","l":"https://en.wikipedia.org/wiki/Air_Warrior_II"},{"t":"Air Warrior III","p":["Windows"],"d":"Kesmai","u":"Interactive Magic, Midas Interactive Entertainment","g":"Combat flight simulator","r":"December 15, 1997","l":"https://en.wikipedia.org/wiki/Air_Warrior_III"},{"t":"AirCars","p":["Atari Jaguar"],"d":"MidNite Entertainment Group","u":"ICD","g":"Shooter","r":"June 18, 1997","l":"https://en.wikipedia.org/wiki/AirCars"},{"t":"All-Star Baseball '97 featuring Frank Thomas","p":["PlayStation","Sega Saturn"],"d":"Iguana Entertainment","u":"Acclaim Entertainment","g":"Sports","r":"May 14, 1997","l":"https://en.wikipedia.org/wiki/All-Star_Baseball_'97_featuring_Frank_Thomas"},{"t":"Alundra","p":["PlayStation"],"d":"Matrix Software","u":"Sony Computer Entertainment, Working Designs, Psygnosis","g":"Action-adventure","r":"April 11, 1997","l":"https://en.wikipedia.org/wiki/Alundra","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3tlr.jpg","s":"Between the worlds of light and dark lies the world of dreams. A world where the rule of reason loosens its grip. A place where an insidious evil is stealing minds and blackening the hearts of those from the world of light. Grab a weapon and become the dreamwalker Alundra as he struggles to purge the evil Id of an ancient world before it falls to ash.\n\nExplore dungeons, find weapons, solve challenging puzzles, and kick some serious monster butt as you weave between tense reality and nightmarish dreams to save the hapless masses. With a wide cast of characters and scores of challenging puzzles created by the people responsible for Landstalker on the Genesis. Alundra will rob you of precious sleep until you finish!"},{"t":"Amulets & Armor","p":["MS-DOS"],"d":"United Software Artists","u":"United Software Artists","g":"Action, role-playing","l":"https://en.wikipedia.org/wiki/Amulets_&_Armor"},{"t":"An Elder Scrolls Legend: Battlespire","p":["MS-DOS"],"d":"Bethesda Softworks","u":"Bethesda Softworks","g":"Action role-playing","r":"December 4, 1997","l":"https://en.wikipedia.org/wiki/An_Elder_Scrolls_Legend:_Battlespire","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co53qh.jpg","s":"An Elder Scrolls Legend: Battlespire is an action role-playing open world video game developed and published by Bethesda Softworks, set in the world of The Elder Scrolls."},{"t":"Anastasia: Adventures with Pooka and Bartok","p":["macOS","Windows"],"d":"Motion Works","u":"Fox Interactive","g":"Puzzle","r":"November 25, 1997","l":"https://en.wikipedia.org/wiki/Anastasia:_Adventures_with_Pooka_and_Bartok"},{"t":"Animaniacs Game Pack","p":["Windows","macOS"],"d":"Funnybone Interactive","u":"Funnybone Interactive","g":"Arcade","l":"https://en.wikipedia.org/wiki/Animaniacs_Game_Pack"},{"t":"Arcade's Greatest Hits: The Midway Collection 2","p":["PlayStation","Windows"],"d":"Digital Eclipse","u":"Midway Games","g":"Various","r":"November 1997","l":"https://en.wikipedia.org/wiki/Arcade's_Greatest_Hits:_The_Midway_Collection_2"},{"t":"Area D","p":["Windows"],"d":"Dosch Design","u":"ARI Data CD GmbH","g":"First-person adventure, FMV","l":"https://en.wikipedia.org/wiki/Area_D_(video_game)"},{"t":"Ark of Time","p":["MS-DOS"],"d":"Trecision","u":"Koei","g":"Adventure","r":"March 21, 1997","l":"https://en.wikipedia.org/wiki/Ark_of_Time"},{"t":"Arkanoid Returns","p":["Arcade","PlayStation"],"d":"Taito","u":"Taito","g":"Block breaker","r":"February 1997","l":"https://en.wikipedia.org/wiki/Arkanoid_Returns","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3w82.jpg","s":"Arkanoid Returns is an arcade game released by Taito in 1997 as part of the Arkanoid series. It was the fourth overall, and third to be released in arcades. The game was since ported to the PlayStation, with an updated home release being released afterwards titled Arkanoid R 2000. All versions were released exclusively in Japan, currently making it the only game in the series to never receive an international release. The enemy known as 'DOH' still did not get the message and after many years of silence decides to attack once again.\n\nThe 'Vaus' space vessel better be ready to face new, yet familiar challenges, in order to stop 'DOH' once again. The gameplay remains similar to Arkanoid: Doh it Again, the previous game in the series released for the Super Nintendo, in that it features the same powerups , some re-used level designs, and the same board size. The initial arcade game contains only 50 levels, the environment changing every 9 levels."},{"t":"Arkanoid: Doh It Again","p":["Super Nintendo Entertainment System"],"d":"Taito","u":"Taito, Nintendo","g":"Block breaker","r":"January 15, 1997","l":"https://en.wikipedia.org/wiki/Arkanoid:_Doh_It_Again","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2dgv.jpg","s":"Much like the game Breakout, the player controls the \"Vaus\", a space vessel that acts as the game's \"paddle\" which prevents a ball from falling from the playing field, attempting to bounce it against a number of bricks. The ball striking a brick causes the brick to disappear. When all the bricks are gone, the player goes to the next level, where another pattern of bricks appear. There are a number of variations (bricks that have to be hit multiple times, flying enemy ships, etc.) and power-up capsules to enhance the Vaus (expand the Vaus, multiply the number of balls, equip a laser cannon, break directly to the next level, etc.), but the gameplay remains the same."},{"t":"Armadillo Racing","p":["Arcade"],"d":"Namco","u":"Namco","g":"Racing","r":"April 1997","l":"https://en.wikipedia.org/wiki/Armadillo_Racing"},{"t":"Armed & Delirious","p":["Windows"],"d":"Makh-Shevet","u":"Sir-Tech","g":"Adventure","r":"October 24, 1997","l":"https://en.wikipedia.org/wiki/Armed_&_Delirious"},{"t":"Armored Core","p":["PlayStation"],"d":"FromSoftware","u":"Sony Computer Entertainment, FromSoftware","g":"Third-person shooter","r":"July 10, 1997","l":"https://en.wikipedia.org/wiki/Armored_Core_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co9qr0.jpg","s":"Armored Core is a mecha video game released in 1997, the first in the Armored Core series. It is an action game played from third-person perspective."},{"t":"Armored Core: Project Phantasma","p":["PlayStation"],"d":"FromSoftware","u":"FromSoftware, ASCII Entertainment","g":"Third-person shooter","r":"December 4, 1997","l":"https://en.wikipedia.org/wiki/Armored_Core:_Project_Phantasma","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2ich.jpg","s":"Armored Core: Project Phantasma is a standalone expansion to the original Armored Core, released for the PlayStation in 1997. It focuses on arena-based combat, introducing ranked one-on-one battles against rival pilots Players customise a humanoid mech using interchangeable parts that affect mobility, firepower, and energy use. The game places less emphasis on mission variety and more on mechanical optimisation and combat skill. Its structure and mechanics helped define competitive elements that became central to later entries in the series."},{"t":"Armored Fist 2","p":["MS-DOS"],"d":"NovaLogic","u":"NovaLogic","g":"Tank simulator","r":"October 6, 1997","l":"https://en.wikipedia.org/wiki/Armored_Fist_2"},{"t":"Asmodeus: Tajemný kraj Ruthaniolu","p":["MS-DOS"],"d":"NoSense","u":"Vochozka Trading","g":"Action-adventure, role-playing","l":"https://en.wikipedia.org/wiki/Asmodeus:_Tajemn%C3%BD_kraj_Ruthaniolu"},{"t":"Assault Suit Leynos 2","p":["Sega Saturn"],"d":"NCS, City Connection","u":"Masaya Games, City Connection","g":"Run and gun","r":"February 21, 1997","l":"https://en.wikipedia.org/wiki/Assault_Suit_Leynos_2"},{"t":"Astro Algebra","p":["Windows","macOS"],"d":"Edmark","u":"Edmark","g":"Educational","l":"https://en.wikipedia.org/wiki/Astro_Algebra"},{"t":"Atelier Marie: The Alchemist of Salburg","p":["PlayStation","Sega Saturn"],"d":"Gust","u":"Gust, Koei Tecmo","g":"Role-playing","r":"May 23, 1997","l":"https://en.wikipedia.org/wiki/Atelier_Marie:_The_Alchemist_of_Salburg"},{"t":"Atlantis: The Lost Tales","p":["Windows","MS-DOS"],"d":"Cryo Interactive","u":"Cryo Interactive, Interplay, DreamCatcher, Sega","g":"Adventure","r":"March 25, 1997","l":"https://en.wikipedia.org/wiki/Atlantis:_The_Lost_Tales","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coa44y.jpg","s":"Atlantis: The Lost Tales is a fantasy adventure computer game developed by Cryo Interactive and published by DreamCatcher Interactive, and released on September 30, 1997. The game is named after its initial and most important setting, Atlantis. It is the first in a Myst-like series, and is followed by Atlantis II (Beyond Atlantis outside Europe), Atlantis III: The New World (Beyond Atlantis II), Atlantis Evolution and The Secrets of Atlantis: The Sacred Legacy."},{"t":"Atomic Bomberman","p":["Windows"],"d":"Interplay Productions","u":"Interplay Productions","g":"Arcade, maze","r":"July 21, 1997","l":"https://en.wikipedia.org/wiki/Atomic_Bomberman","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co9859.jpg","s":"Think you're smarter than the collective intelligence of 9 other bombers throwing bombs faster than your mind can comprehend? Try your hand at this fast paced classic from the 90's with up to 10 players filled with mayhem and blown up body parts. Bombs Away!"},{"t":"Au Pays de Vocabulon","p":["macOS","Windows"],"d":"index+","u":"France Telecom Multimedia","g":"Educational","l":"https://en.wikipedia.org/wiki/Au_Pays_de_Vocabulon"},{"t":"Auto Destruct","p":["PlayStation"],"r":"December 23","l":"https://en.wikipedia.org/wiki/Auto_Destruct"},{"t":"Automobili Lamborghini","p":["Nintendo 64"],"d":"Titus France","u":"Titus France","g":"Racing","r":"November 22, 1997","l":"https://en.wikipedia.org/wiki/Automobili_Lamborghini_(video_game)"},{"t":"Ayakashi Ninden Kunoichiban","p":["Windows"],"d":"Zero System","u":"Shōeisha","g":"Dating sim","r":"March 14, 1997","l":"https://en.wikipedia.org/wiki/Ayakashi_Ninden_Kunoichiban"},{"t":"AYSO Soccer '97","p":["Windows"],"d":"Rage Games","u":"GameTek","g":"Sports","l":"https://en.wikipedia.org/wiki/AYSO_Soccer_'97"},{"t":"Azure Dreams","p":["PlayStation","Game Boy Color"],"d":"KCET","u":"Konami","g":"Role-playing","r":"November 13, 1997","l":"https://en.wikipedia.org/wiki/Azure_Dreams","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3bsc.jpg","s":"The game offers a lot of choice in respect to how individual players wish to play. The main focus of the game is entering the tower and destroying its denizens, collecting treasure and monster eggs to hatch into familiars. Each monster has hidden spells, unique traits, and abilities. Koh can also improve the town, along with decorating his home."},{"t":"Backyard Baseball","p":["Windows","macOS"],"d":"Humongous Entertainment","u":"Humongous Entertainment","g":"Sports video game","r":"October 10, 1997","l":"https://en.wikipedia.org/wiki/Backyard_Baseball_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co8ywl.jpg","s":"Backyard Baseball was the first game created for the PC by Humongous Entertainment in 1997. It is a one player game. The game consists of 55 neighbourhood kids to pick from to join your baseball team. Each kid has different stats so pick wisely."},{"t":"Ballblazer Champions","p":["PlayStation"],"d":"Factor 5","u":"LucasArts, CTO SpA","g":"Action, sports","r":"April 2, 1997","l":"https://en.wikipedia.org/wiki/Ballblazer_Champions"},{"t":"Balls of Steel","p":["Windows","macOS"],"d":"Wildfire Studios","u":"3D Realms","g":"Pinball","r":"December 12, 1997","l":"https://en.wikipedia.org/wiki/Balls_of_Steel_(video_game)"},{"t":"Barbie Magic Hair Styler","p":["Windows"],"d":"EAI Interactive","u":"Mattel Media","r":"October 1, 1997","l":"https://en.wikipedia.org/wiki/Barbie_Magic_Hair_Styler"},{"t":"Barbie Storymaker","p":["Windows"],"u":"Mattel Media","g":"Educational","l":"https://en.wikipedia.org/wiki/Barbie_Storymaker"},{"t":"Baseball Mogul","p":["Windows"],"d":"Sports Mogul","u":"Sports Mogul","g":"Sports management","l":"https://en.wikipedia.org/wiki/Baseball_Mogul"},{"t":"Battle Circuit","p":["Arcade"],"d":"Capcom","u":"Capcom","g":"Beat 'em up","r":"March 19, 1997","l":"https://en.wikipedia.org/wiki/Battle_Circuit","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coblwk.jpg","s":"Battle Circuit is a 2D side scrolling beat'em up drawn in a comic (manga) style in a futuristic science fiction setting. A group of bounty hunters must capture the mad scientist Dr. Saturn with a giant head.\n\nThe roster of heroes has 5 characters for the player to choose from: Cyber Blue, a human bounty hunter with cybernetic attachments to his body; Captain Silver, a humanoid shape-shifting hunter who has ability to project ice particles from his body; Pink Ostrich, a large, sentient, pink ostrich, who is always accompanied by its owner, a young girl named Pola Abdul; Yellow Iris, a part-time fashion model with claws and Alien Green, a space creature looking like a giant, moving plant.\n\nGameplay is quite typical for the genre, like in Final Fight, Streets of Rage, or Cadillacs and Dinosaurs - players go right, beat the enemies (player has access to various attacks), collect bonuses and money, and fight against bosses, for example Dr. Saturn and his robots. Players' abilities can be expanded by purchasing special \"upgrade discs\" after the completion of levels using coins obtained from dead enemies."},{"t":"Battle Stations","p":["PlayStation","Sega Saturn"],"d":"Realtime Associates","u":"Electronic Arts","g":"Strategy","r":"May 21, 1997","l":"https://en.wikipedia.org/wiki/Battle_Stations_(1997_video_game)"},{"t":"Battle-Girl","p":["macOS"],"d":"Ultra/United Games","u":"Power Media","g":"Multidirectional shooter","r":"September 24, 1997","l":"https://en.wikipedia.org/wiki/Battle-Girl"},{"t":"Battleground 6: Napoleon in Russia","p":["Windows"],"d":"TalonSoft","u":"TalonSoft","g":"Computer wargame","r":"May 15, 1997","l":"https://en.wikipedia.org/wiki/Battleground_6:_Napoleon_in_Russia"},{"t":"Battleground 7: Bull Run","p":["Windows"],"d":"TalonSoft","u":"TalonSoft","g":"Computer wargame","r":"May 15, 1997","l":"https://en.wikipedia.org/wiki/Battleground_7:_Bull_Run"},{"t":"Battleground 8: Prelude to Waterloo","p":["Windows"],"d":"TalonSoft","u":"TalonSoft","g":"Computer wargame","r":"September 1997","l":"https://en.wikipedia.org/wiki/Battleground_8:_Prelude_to_Waterloo"},{"t":"Beast Wars: Transformers","p":["PlayStation"],"d":"Sony Computer Entertainment Europe","u":"Hasbro Interactive","g":"Third-person shooter","r":"December 2, 1997","l":"https://en.wikipedia.org/wiki/Beast_Wars:_Transformers_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2zxp.jpg","s":"In BEAST WARS you travel along the planet's surface and explore many areas, looking to destroy any enemies that cross your path. The innovative auto-targeting system locks on to any enemies in your area and makes for some straightforward killing. However, don't think it's going to be easy, as you will have to dodge enemy gunfire at the same time.\n\nEventually, your character will use up his Energon supply and you will have to refuel by transforming into Beast mode. While in Beast mode you cannot attack, and your sole purpose is to find power-ups to restore your Energon. BEAST WARS offers 10 different transformers to choose from, each with their own traits.\n\nYou'll also have the chance to battle in four different environments, each having its own set of enemies. With 24 missions to play and eight bonus missions, you'll have plenty to keep you occupied."},{"t":"Beasts and Bumpkins","p":["Windows"],"d":"Worldweaver Ltd","u":"Electronic Arts","g":"Real-time strategy Simulation","l":"https://en.wikipedia.org/wiki/Beasts_and_Bumpkins"},{"t":"Beat the House 2","p":["Windows"],"d":"Cetasoft","u":"Interplay Productions","g":"Gambling","r":"October 1997","l":"https://en.wikipedia.org/wiki/Beat_the_House_2"},{"t":"Beatmania","p":[],"d":"Konami G.M.D.","u":"Konami","g":"Music video game","l":"https://en.wikipedia.org/wiki/Beatmania"},{"t":"Betrayal in Antara","p":["Windows"],"d":"Sierra On-Line","u":"Sierra On-Line","g":"Role-playing","r":"June 30, 1997","l":"https://en.wikipedia.org/wiki/Betrayal_in_Antara"},{"t":"Beyond Time","p":[],"d":"Jones and Jones Multimedia","u":"DreamCatcher Interactive","g":"Adventure","r":"November 1997","l":"https://en.wikipedia.org/wiki/Beyond_Time"},{"t":"Birthright: The Gorgon's Alliance","p":["MS-DOS","Windows"],"d":"Synergistic Software","u":"Sierra On-Line","g":"Turn-based strategy, turn-based tactics","r":"July 31, 1997","l":"https://en.wikipedia.org/wiki/Birthright:_The_Gorgon's_Alliance"},{"t":"Blade Runner","p":["Windows","MS-DOS"],"g":"Point-and-click, Adventure","r":"November 14","l":"https://en.wikipedia.org/wiki/Blade_Runner_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1zz1.jpg","s":"Blade Runner is an adventure game with an emphasis on detective work rather than on puzzles. There are very few \"real\" puzzles in the game, and the gameplay mainly consists of questioning suspects, gathering evidence, etc. There are also some action sequences, and throughout the game the protagonist has the ability to use his gun. The player's decisions can (and will) influence the outcome of the story, bringing the game to one of the six possible endings."},{"t":"Blades of Exile","p":["macOS"],"d":"Spiderweb Software","u":"Diversions Entertainment","g":"Role-playing","r":"December 1997","l":"https://en.wikipedia.org/wiki/Blades_of_Exile"},{"t":"Blast Corps","p":["Nintendo 64"],"u":"Nintendo","g":"Puzzle, Tactical","r":"March 21, 1997","l":"https://en.wikipedia.org/wiki/Blast_Corps","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2896.jpg","s":"Blast Corps is a 1997 video game for the Nintendo 64 developed by Rare and published by Nintendo. Destroy a series of buildings or objects using a variety of unique demolition vehicles, in order to mainly clear a path for trucks carrying defective nuclear missiles."},{"t":"Blast Wind","p":["Sega Saturn"],"d":"Technosoft","u":"Technosoft","g":"Vertically scrolling shooter","r":"January 17, 1997","l":"https://en.wikipedia.org/wiki/Blast_Wind"},{"t":"Blood","p":["Windows","MS-DOS"],"g":"Shooter","r":"May 21","l":"https://en.wikipedia.org/wiki/Blood_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2pkw.jpg","s":"You carved your soul to shreds in servitude to a dark god, but false promises and betrayal were your only reward. Now you have a score to settle and it will be measured in blood! Experience the madness in one carnage-soaked package! All the gore, all the unholy war! Zombies, gargoyles, hellhounds and blood-crazed hordes of horrors await! Crush loathsome evil of the mighty Tchernobog! Or condemn yourself to eternal damnation in this leviathan of unhallowed gaming action!\n\nVisit a dark near-future world populated by hundreds of bloodthirsty enemies. You'll engage in a nightmarish battle against the minions of an ancient god bent on wiping humanity from the face of the earth. With cultists, gargoyles, zombies, hellhounds, and an unholy host of other terrors, Blood immerses you in a world of horror unlike any you've experienced before."},{"t":"Bloody Roar","p":["Arcade","PlayStation"],"d":"Raizing, Hudson Soft","u":"Hudson Soft, Sony Computer Entertainment, Virgin Interactive","g":"Fighting","r":"July 1997","l":"https://en.wikipedia.org/wiki/Bloody_Roar_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co9q6v.jpg","s":"Bloody Roar, known as Bloody Roar: Hyper Beast Duel in Europe and Japan, is a fighting video game originally developed by Raizing (now Eighting) as an arcade game. It was later adapted for the PlayStation by Hudson Soft and published by Sony Computer Entertainment for the PlayStation. The arcade version was released on July 7, 1997 and was titled Beastorizer in North America. The PlayStation version was released in Japan on November 6, 1997, in North America (under the title Bloody Roar) on October 31, 1997 and in Europe on March 1998.\n\nBloody Roar is the first game in the Bloody Roar video game series and was followed by four sequels on multiple platforms. The game's story centers on a group of warriors known as \"zoanthropes\", who have the power to transform into half-human half-animal \"Beasts\", and the Tylon Corporation, and underground organization that seeks to use zoanthropes as mind-controlled weapons. The game received generally positive reviews from critics for its originality and graphics, while the audio received mixed opinions. The game's success resulted in its re-release for The Best range on October 14, 1999. The game was re-released on the PlayStation Network in North America on August 20, 2009."},{"t":"Blue Heat: The Case of the Cover Girl Murders","p":["Windows"],"d":"Quarium Inc.","u":"Orion Interactive","g":"Adventure","r":"September 12, 1997","l":"https://en.wikipedia.org/wiki/Blue_Heat:_The_Case_of_the_Cover_Girl_Murders"},{"t":"Boggle","p":["Windows"],"d":"PCA, Inc., Third-i Productions","u":"Hasbro Interactive","g":"Puzzle","r":"October 1997","l":"https://en.wikipedia.org/wiki/Boggle_(video_game)"},{"t":"Bomberman 64","p":["Nintendo 64"],"g":"Platform, Puzzle, Adventure","r":"September 26","l":"https://en.wikipedia.org/wiki/Bomberman_64_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co54xq.jpg","s":"The evil Altair is using the Omni Cube to drain the energy from Planet Bomber. With the aid of a mysterious helper, you must defeat Altair, and restore peace to Planet Bomber. In the Adventure mode, guide Bomberman through 24 areas of perilous conflict. Battle Altair's sinister allies, destroy their bases and put an end to the insane attack. The multi-player Battle mode offers endless hours of explosive action. Use the standard Bomberman character or create a custom one and save it to an N64 Controller Pak."},{"t":"Bravo Air Race","p":["PlayStation"],"d":"Xing Entertainment","u":"THQ","g":"Racing","r":"July 31, 1997","l":"https://en.wikipedia.org/wiki/Bravo_Air_Race"},{"t":"Breath of Fire III","p":["PlayStation"],"g":"Role-playing (RPG)","r":"September 11","l":"https://en.wikipedia.org/wiki/Breath_of_Fire_III","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co9jxg.jpg","s":"A MYSTERIOUS POWER...AN UNLIKELY HERO...A CLASSIC ADVENTURE...\n\nThe lone survivor of a legendary dragon clan, a rebellious youth embarks on a great journey. One of discovery... and danger. The classic role-playing game now returns to continue the epic tales of Ryu and the dragon people. An inner power of uncertain origin matures Ryu into a warrior who ponders his purpose as he embarks on a mystical journey. What lies ahead is shrouded in mystery... yet strangely familiar.\n\nDRAGON GENE SPLICING\nLEGENDARY ROLEPLAYING\nAN EPIC 3-D ENVIRONMENT\nLEARN OR STEAL ADVANCE SKILLS AND TECHNIQUES\nPOWERFUL MAGIC\n\nNOW YOU POSSESS THE POWER TO CONTROL RYU'S DESTINY."},{"t":"British Open Championship Golf","p":["Windows"],"d":"LookingGlass Technologies","u":"LookingGlass Technologies","g":"Golf sports game","r":"April 21, 1997","l":"https://en.wikipedia.org/wiki/British_Open_Championship_Golf"},{"t":"Broken Helix","p":["PlayStation"],"d":"Konami Computer Entertainment Chicago","u":"Konami","g":"Third-person shooter","r":"May 30, 1997","l":"https://en.wikipedia.org/wiki/Broken_Helix"},{"t":"Broken Sword II: The Smoking Mirror","p":["Windows","PlayStation"],"d":"Revolution Software","u":"Virgin Interactive, Sony Computer Entertainment, Crave Entertainment, &","g":"Point-and-click adventure","r":"October 14, 1997","l":"https://en.wikipedia.org/wiki/Broken_Sword_II:_The_Smoking_Mirror"},{"t":"Broken Sword: The Smoking Mirror","p":["PlayStation","Windows"],"d":"Revolution Software","u":"Crave Entertainment, Virgin Interactive Entertainment, Sony Computer Entertainment","g":"Point-and-click, Puzzle, Adventure","r":"October 17, 1997","l":"https://www.igdb.com/games/broken-sword-the-smoking-mirror","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cocwnb.jpg","s":"Broken Sword: The Smoking Mirror is a 2D adventure game played from a third-person perspective. Via a point-and-click interface, the player guides protagonist George Stobbart through the game's world and interacts with the environment by selecting from multiple commands, while Nicole Collard is also a playable character in selected portions of the game.\n\nThe player controls George's movements and can engage in dialogue with other characters through conversation trees to gain hints of what needs to be done to solve the puzzles or to progress the plot. He also have to collect objects that can be used with either other collectible objects, parts of the scenery or with other people in order to solve puzzles and progress in the game. By right-clicking on an object, the player gets a description and clues. The player character's death is possible if he makes a wrong decision."},{"t":"Brunswick World: Tournament of Champions","p":["Super Nintendo Entertainment System"],"d":"Tiertex Design Studios","u":"Black Pearl","g":"Sports","r":"August 12, 1997","l":"https://en.wikipedia.org/wiki/Brunswick_World:_Tournament_of_Champions"},{"t":"Buccaneer","p":["Windows"],"d":"Divide by Zero Software","u":"Strategic Simulations","g":"Action game, Strategy game","l":"https://en.wikipedia.org/wiki/Buccaneer_(video_game)"},{"t":"Bug Riders","p":["PlayStation","Windows"],"d":"n-Space","u":"GT Interactive","g":"Racing","r":"December 1, 1997","l":"https://en.wikipedia.org/wiki/Bug_Riders"},{"t":"Bugs Bunny: Crazy Castle 3","p":["Game Boy"],"d":"Kemco","u":"Kemco, Nintendo","g":"Platform","r":"July 18, 1997","l":"https://en.wikipedia.org/wiki/Bugs_Bunny:_Crazy_Castle_3"},{"t":"Bulk Slash","p":["Sega Saturn"],"d":"CAProduction","u":"Hudson Soft","g":"Action, mech simulator, third-person shooter","r":"July 11, 1997","l":"https://en.wikipedia.org/wiki/Bulk_Slash"},{"t":"Bumbler Bee-Luxe","p":["macOS"],"d":"Dadgum Games","u":"Dadgum Games, StarPlay Productions","g":"Multidirectional shooter","r":"August 25, 1997","l":"https://en.wikipedia.org/wiki/Bumbler_Bee-Luxe"},{"t":"Bushido Blade","p":["PlayStation"],"d":"Lightweight","u":"Square, Sony Computer Entertainment","g":"Fighting","r":"March 14, 1997","l":"https://en.wikipedia.org/wiki/Bushido_Blade_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1y80.jpg","s":"\"Bushido\" is the soul of Japan - an ancient honor code deeply followed by samurai warriors for centuries. Plunge into real world battles across vast 3D environments that you can run, slice and tear through. Sword matches become unbelievably real where one critical blow is the mean difference between death and victory."},{"t":"Bust-a-Move '99","p":["PlayStation"],"d":"Taito","u":"Acclaim, Taito, Square Enix","g":"Puzzle, Strategy, Arcade","r":"November 6, 1997","l":"https://www.igdb.com/games/bust-a-move-99","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coabmn.jpg","s":"In the tradition of the Bust-A-Move series, Taito's Bust-A-Move '99 is a traditional puzzle game. The main objective is to destroy or get rid of (by dropping) all the bubbles located within the stage. Once you do this, you'll graduate to the next level.\n\nWhile the premise may sound simple, the logic and execution is not. Using a \"bubble shooter\", you must aim and shoot your bubbles to the top of the screen so that you can bring three bubbles of the same color together. When you do this, the bubbles will pop. One way to earn points is to have the popping bubbles as well as the bubble that was shot fall off the screen (in multi-player, it puts these bubbles on your opponent's side). This also gives you a lot less bubbles to take care of.\n\nBubbles are constantly falling down. Popping them all in a short amount of time is necessary because the longer it takes you to pop them all, the faster they will drop. If you fail to clear out all the bubbles and they reach the bottom of the screen, the game is over.\n\nBust-A-Move '99 contains some new options never seen in the Bust-A-Move series. There are now special bubbles (star, metal and rainbow to name a few), obstructive bubbles and blocks and new backgrounds. You are also given the opportunity to create your very own stages with the create-a-level editor."},{"t":"Buster Bros. Collection","p":["PlayStation"],"d":"Mitchell Corporation","u":"Capcom","g":"Action","r":"March 14, 1997","l":"https://en.wikipedia.org/wiki/Buster_Bros._Collection"},{"t":"Byzantine","p":["Windows"],"d":"Discovery Channel Multimedia, Stormfront Studios","u":"Discovery Communications","g":"Adventure, education","r":"September 1997","l":"https://en.wikipedia.org/wiki/Byzantine_(video_game)"},{"t":"C-Dogs","p":["MS-DOS"],"g":"Shoot 'em up","l":"https://en.wikipedia.org/wiki/C-Dogs"},{"t":"Callahan's Crosstime Saloon","p":["MS-DOS"],"d":"Legend Entertainment","u":"Take-Two Interactive","g":"Graphic adventure","r":"April 16, 1997","l":"https://en.wikipedia.org/wiki/Callahan's_Crosstime_Saloon_(video_game)"},{"t":"Carmageddon","p":["Windows","MS-DOS"],"u":"Sales Curve Interactive","g":"Action, Indie, Racing","r":"June 13, 1997","l":"https://en.wikipedia.org/wiki/Carmageddon","i":"images/steam-282010.jpg","s":"Carmageddon is the original freeform driving sensation, where pedestrians (and cows!) equal points, and your opponents are a bunch of crazies in a twisted mix of automotive killing machines. The game features anarchic drive-wherever-you-like gameplay and over-the-top surreal comedy violence. It’s the racing game where racing is for wimps."},{"t":"Carmen Sandiego Word Detective","p":["macOS","Windows"],"d":"Broderbund","u":"Broderbund","g":"Educational","l":"https://en.wikipedia.org/wiki/Carmen_Sandiego_Word_Detective"},{"t":"Carmen Sandiego's Great Chase Through Time","p":["Windows","macOS"],"d":"Broderbund","u":"Broderbund Software, The Learning Company","g":"Educational, adventure","r":"August 13, 1997","l":"https://en.wikipedia.org/wiki/Carmen_Sandiego's_Great_Chase_Through_Time"},{"t":"CART Precision Racing","p":["Windows"],"d":"Terminal Reality","u":"Microsoft Studios","g":"Racing","r":"December 3, 1997","l":"https://en.wikipedia.org/wiki/CART_Precision_Racing"},{"t":"CART World Series","p":["PlayStation"],"d":"Sony Interactive Studios America","u":"Sony Computer Entertainment","g":"Arcade racing","r":"October 1997","l":"https://en.wikipedia.org/wiki/CART_World_Series"},{"t":"Castlevania Legends","p":["Game Boy"],"d":"Konami Computer Entertainment Nagoya","u":"Konami","g":"Action, platform","r":"November 27, 1997","l":"https://en.wikipedia.org/wiki/Castlevania_Legends","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co20d8.jpg","s":"Every legend has a beginning. Now discover the beginning of the Castlevania Legend in Castlevania Legends for Game Boy. In this single-player adventure, you play as Sonia Belmont, the very first in the line of vampire hunting Belmonts. Use your whip to fend off the forces of darkness, as you work your way through six stages of non-linear gameplay. Explore the legendary areas of Castlevania, including the surrounding forest and the infamous clock tower. Don't forget to collect hearts from the torches that litter the stages to gain extra lives. Adjustable difficulty settings allow you to choose the skill level at which you want to play. At the end of it all, Count Dracula himself awaits. Can you defeat him and put the evil to rest for another 100 years?"},{"t":"Castlevania: Symphony of the Night","p":["PlayStation"],"u":"Konami","g":"Platform, Role-playing (RPG), Adventure","r":"March 20, 1997","l":"https://www.igdb.com/games/castlevania-symphony-of-the-night","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co53m8.jpg","s":"Having been awoken from his eternal slumber by the reappearance of Castlevania, Alucard must once again face the evil minions of darkness. Use your vampiric powers, along with weapons, potions, and other magical relics to change the tide of battle.\n\nA mixture of platform and role-playing action with many hidden areas and secrets. Can you discover them all?"},{"t":"Ceremony of Innocence","p":["Windows","macOS"],"d":"Real World Multimedia","u":"Real World Multimedia","g":"Adventure","l":"https://en.wikipedia.org/wiki/Ceremony_of_Innocence"},{"t":"Chalvo 55","p":[],"l":"https://en.wikipedia.org/wiki/Chalvo_55"},{"t":"Chameleon Twist","p":["Nintendo 64"],"d":"Japan System Supply","u":"Japan System Supply, Sunsoft","g":"Platform","r":"December 9, 1997","l":"https://en.wikipedia.org/wiki/Chameleon_Twist","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2dq6.jpg","s":"Chameleon Twist is a 3D-Jump & Run, developed by Japan System Supply and released by Sunsoft in 1997.\n\nAfter following a rabbit into a magical hole in the ground, the blue chameleon named Davy realises that he has taken on a humanoid form. In an attempt to find a way back home, Davy is traveling throughout six lands with his friends, Jack, Fred, and Linda; together they discover Jungle Land, Ant Land, Bomb Land, Desert Castle, Kids Land, and Ghost Castle to find the certain magic portal."},{"t":"Championship Manager: Season 97/98","p":["Windows"],"d":"Sports Interactive","u":"Eidos Interactive","g":"Sports","r":"October 31, 1997","l":"https://en.wikipedia.org/wiki/Championship_Manager:_Season_97/98"},{"t":"Chaos Island: The Lost World","p":["Windows"],"d":"DreamWorks Interactive","u":"DreamWorks Interactive","g":"Real-time strategy","r":"October 30, 1997","l":"https://en.wikipedia.org/wiki/Chaos_Island:_The_Lost_World"},{"t":"Chasm: The Rift","p":["MS-DOS"],"d":"Action Forms","u":"Megamedia","g":"First-person shooter","r":"October 21, 1997","l":"https://en.wikipedia.org/wiki/Chasm:_The_Rift","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2l4r.jpg","s":"Humankind, in the process of evolution, has encountered a mysterious phenomenon - the destruction of the normal flow of time. From the past to the future, time rifts are forming in Earth's atmosphere. These rifts lead to different periods of history. Through them the most aggressive creatures from the past, present, and the future, have begun to infiltrate our time. These mutants, known as Timestrikers, have begun a complete and systemic eradication of all human life. You are a specially trained commando who has been volunteered to investigate a recent attack by the Timestrikers.\n\nUtilizing an arsenal of devastating weapons and mysterious items from the past and the future, you have been authorized to terminate any mutant creatures that attempt to obstruct your investigation. Each assignment gets you closer to the heart of your goal. A mission briefing gets you moving in the right direction, but it's up to you to carry out your orders. Grab your weapon and report to the Commander immediately!"},{"t":"Chex Quest","p":["MS-DOS","Windows"],"d":"Digital Café","u":"General Mills","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Chex_Quest","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4xhb.jpg","s":"Set on a distant planet named Bazoik, the game follows the Chex Warrior, a humanoid in an anthropomorphic piece of Chex cereal armor, as he fights to eradicate the Flemoid invasion. These slimy, green creatures have infested the planet and captured many helpless citizens whom the Chex Warrior must save.\n\nHis only weapon is a device called a \"zorcher\", which teleports his enemies instead of killing them. The game starts at the landing pad of the research facility on Bazoik, after which the protagonist is teleported to the storage facility. The other levels include the laboratory, the arboretum, and finally, the underground caverns of Bazoik, where the Flemoids seem to be making a home for themselves."},{"t":"Cho Ren Sha 68K","p":["Sharp X68000"],"d":"Famibe no Yosshin","u":"Famibe no Yosshin","g":"Vertically scrolling shooter","r":"December 1997","l":"https://en.wikipedia.org/wiki/Cho_Ren_Sha_68K"},{"t":"Chocobo's Mysterious Dungeon","p":["PlayStation"],"d":"Square","u":"Square","g":"Roguelike","r":"December 23, 1997","l":"https://en.wikipedia.org/wiki/Chocobo's_Mysterious_Dungeon"},{"t":"Chopper Attack","p":["Nintendo 64"],"d":"SETA Corporation","u":"SETA Corporation, Midway, GT Interactive","g":"Third-person shooter","r":"November 28, 1997","l":"https://en.wikipedia.org/wiki/Chopper_Attack"},{"t":"Chōjin Heiki Zeroigar","p":["PC-FX"],"d":"Fupac, Sugeiya, Winds","u":"NEC","g":"Vertically scrolling shooter","r":"August 8, 1997","l":"https://en.wikipedia.org/wiki/Ch%C5%8Djin_Heiki_Zeroigar"},{"t":"Claw","p":["Windows"],"d":"Monolith Productions","u":"Monolith Productions","g":"Platform","r":"September 9, 1997","l":"https://en.wikipedia.org/wiki/Claw_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2y4u.jpg","s":"Join forces with Captain Claw, the greatest cat pirate ever to challenge the Cocker Spaniard Armada! Embark on an epic quest to recover the lost gems of the Amulet of Nine Lives. Uncover hidden treasure, navigate tricky terrain, and engage in armed combat to defeat the enemies of the courageous and legendary Captain Nathaniel J. Claw."},{"t":"ClayFighter 63 1/3","p":["Nintendo 64"],"d":"Interplay Productions","u":"Interplay Productions","g":"Fighting","r":"October 23, 1997","l":"https://en.wikipedia.org/wiki/ClayFighter_63_1/3","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3bc4.jpg","s":"Get ready to crumble! Once again, the clay fighters prove that when you play a state-of-the-art fighter, you might lose lives, you might lose limbs, but there's no reason to lose your sense of humor! Fight in and out of 3D backgrounds. Get tossed out of a window and resume fighting outside. Choose form 12 eccentric fighters including brand new combatants and old favorites like \"Bad Mister Frosty\" and \"Bonker the Clown.\" Includes bonus \"secret characters\" who are so famous that a legal gag order prohibits us from revealing their identity. Move freely in over 12 highly detailed 3D environments."},{"t":"Close Combat: A Bridge Too Far","p":["Windows","MS-DOS"],"r":"September 30"},{"t":"Colony 28","p":["MS-DOS"],"d":"Napoleon Games","u":"JRC Interactive","g":"Platform","r":"June 1997","l":"https://en.wikipedia.org/wiki/Colony_28"},{"t":"Colony Wars","p":["PlayStation"],"u":"Psygnosis","g":"Simulator","r":"October 31, 1997","l":"https://en.wikipedia.org/wiki/Colony_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co23s8.jpg","s":"Colony Wars is a combat fighter game set in space. You, as the player, join as a recruit in the League's fleet. Missions take place in various fighters, from a 1st person view inside the cockpit, or a 3rd person view from behind your ship. Ships have separate meters for shields and armor, and the player must cycle between weapons designed specifically to damage each. At the most basic, purple lasers must drain a target's shields, followed by switching to red lasers to destroy them. \n \nThe game features advanced lighting and particle effects for the Playstation, as well as a basic simulation of Newtonian physics. Thrusters are only active for as long as the accelerate button is held down. The player can burst fire their thrusters and drift, allowing for some advanced maneuvers. The campaign also features multiple endings and branching missions/storylines, based on your performance in the previous operations."},{"t":"Comanche 3","p":["MS-DOS","Windows"],"d":"NovaLogic","u":"NovaLogic","g":"Combat flight simulator","r":"May 1, 1997","l":"https://en.wikipedia.org/wiki/Comanche_3"},{"t":"Combat Chess","p":["Windows","MS-DOS"],"g":"Strategy","r":"October","l":"https://en.wikipedia.org/wiki/Combat_Chess","i":"images/steam-1557050.jpg","s":"Play with living, battling characters! Combat Chess takes the basic chess game and adds an imaginative element for players. Beautifully done in rendered 3D graphics, Combat Chess adds stunning animation sequences during gameplay."},{"t":"Command & Conquer: Sole Survivor","p":["Windows"],"d":"Westwood Studios","g":"Real-time strategy","r":"December 8, 1997","l":"https://en.wikipedia.org/wiki/Command_&_Conquer:_Sole_Survivor"},{"t":"Conquest Earth","p":["Windows","MS-DOS"],"d":"Data Design Interactive","u":"Eidos Interactive","g":"Real-time strategy","r":"September 18, 1997","l":"https://en.wikipedia.org/wiki/Conquest_Earth"},{"t":"Constructor","p":["MS-DOS"],"d":"System 3","u":"Acclaim Entertainment, System 3","g":"Real-time strategy, Construction and management simulation","r":"October 3, 1997","l":"https://en.wikipedia.org/wiki/Constructor_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2hnr.jpg","s":"In a town where anything goes, you can’t rise to the top without taking a few others down. From dodgy deals to shifty tricks, do what you gotta do to go from small-time slumlord to filthy rich tycoon."},{"t":"Cool Boarders 2","p":["PlayStation"],"d":"UEP Systems","u":"UEP Systems, Sony Computer Entertainment","g":"Snowboarding","r":"August 28, 1997","l":"https://en.wikipedia.org/wiki/Cool_Boarders_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2f23.jpg","s":"Cool Boarders 2 features four stock riders and six stock tracks. Many more are available as you progress through the game or unlock them with codes or secrets.\n\nThis installment of the Cool Boarders series features a split screen \"Vs\" mode, where two human players can race each other. It also features a one person race option, to race against up to six CPU controlled players.\n\nThe tracks all vary in length and challenge level. There is also a half pipe, Boardpark level and a Trick Master Run with continuous jumps and a tutorial to teach you all the moves. The move list in Cool Boarders 2 is quite extensive, including standard board grabs and various flips and spins. The graphic technology is primarily based on 3D polygonal models. The game also features red book audio."},{"t":"Cotton 2: Magical Night Dreams","p":["Arcade","Sega Saturn"],"d":"Success","u":"Tecmo, Success","g":"Scrolling shooter","r":"November 1997","l":"https://en.wikipedia.org/wiki/Cotton_2:_Magical_Night_Dreams"},{"t":"Courier Crisis","p":["PlayStation","Sega Saturn"],"d":"New Level Software","u":"GT Interactive, BMG Interactive","g":"Action","r":"November 14, 1997","l":"https://en.wikipedia.org/wiki/Courier_Crisis"},{"t":"Crash Bandicoot 2: Cortex Strikes Back","p":["PlayStation"],"u":"Sony Computer Entertainment","g":"Platform, Adventure","r":"October 31, 1997","l":"https://www.igdb.com/games/crash-bandicoot-2-cortex-strikes-back","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co82vt.jpg","s":"Crash Bandicoot 2: Cortex Strikes Back is the second game in the Crash Bandicoot series, and the sequel to the original game. The gameplay is largely similar to that of the original, as players make their way through a limited environment whilst breaking crates that contains bonuses. The goal of the game is to gather 25 crystals for Crash's nemesis, Doctor Neo Cortex. The crystals are scattered between 25 different levels accessible via Warp Rooms, which are hub areas of the game. A level is cleared by collecting its respective crystal and reaching the end of its path, which returns Crash to the Warp Room."},{"t":"Cricket 97","p":["MS-DOS","Windows"],"d":"Beam Software","u":"EA Sports","g":"Sports","l":"https://en.wikipedia.org/wiki/Cricket_97"},{"t":"Critical Blow","p":["PlayStation"],"d":"Racdym","u":"Banpresto","g":"Fighting game","r":"December 4, 1997","l":"https://en.wikipedia.org/wiki/Critical_Blow"},{"t":"Critical Depth","p":["PlayStation"],"d":"SingleTrac","u":"GT Interactive","g":"Vehicular combat","r":"November 21, 1997","l":"https://en.wikipedia.org/wiki/Critical_Depth_(video_game)"},{"t":"Croc: Legend of the Gobbos","p":["Windows","MS-DOS","PlayStation","Sega Saturn"],"g":"Action, Adventure","r":"September 29","l":"https://store.steampowered.com/app/3043940","i":"images/steam-3043940.jpg","s":"Join Croc in a charming 3D platforming adventure to rescue the kidnapped Gobbos from the evil sorcerer Baron Dante and his impish Dantini minions! Run, jump, climb, swim, and tail-spin through vibrant worlds in this lovingly remastered and updated version of the beloved 1997 classic."},{"t":"Crusader: Adventure Out of Time","p":["Windows","macOS"],"d":"Index+","u":"Europress","g":"Historical adventure","l":"https://en.wikipedia.org/wiki/Crusader:_Adventure_Out_of_Time"},{"t":"Culdcept","p":["Sega Saturn"],"r":"October 30","l":"https://en.wikipedia.org/wiki/Culdcept_(1997_video_game)"},{"t":"Cyber Citizen Shockman Zero","p":["Satellaview"],"d":"Masaya Games","u":"NCS Corporation, Columbus Circle, Ratalaika Games, Retro-Bit","g":"Action","r":"March 20, 1997","l":"https://en.wikipedia.org/wiki/Cyber_Citizen_Shockman_Zero"},{"t":"D-Xhird","p":["Sega Saturn"],"d":"Nextech","u":"Takara","g":"Fighting","r":"May 30, 1997","l":"https://en.wikipedia.org/wiki/D-Xhird"},{"t":"D.A. Pursuit of Justice","p":["Windows"],"d":"Legacy Software","u":"Legacy Software","g":"Adventure","r":"September 1997","l":"https://en.wikipedia.org/wiki/D.A._Pursuit_of_Justice"},{"t":"Damage Incorporated","p":["macOS","Windows"],"d":"Paranoid Productions","u":"MacSoft, WizardWorks","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Damage_Incorporated"},{"t":"Dark Angael","p":["Windows"],"d":"Vicarious Visions","u":"Vicarious Visions","g":"Run-and-gun, action-adventure","r":"September 29, 1997","l":"https://en.wikipedia.org/wiki/Dark_Angael"},{"t":"Dark Colony","p":["Windows","macOS"],"d":"Alternative Reality Technologies","u":"Strategic Simulations, Take-Two Interactive","g":"Real-time strategy","r":"August 1997","l":"https://en.wikipedia.org/wiki/Dark_Colony","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2mn9.jpg","s":"Dark Colony is a real-time strategy with heavy emphasis on the actual combat. Resource gathering, base construction and unit production have been made as simple and fast as possible, allowing the player to focus on decimating the enemy armies. Ancient artifacts, available in some of the missions, provide unique options for beating the odds, even when they seem to be against you (and they often will)."},{"t":"Dark Earth","p":["Windows"],"d":"Kalisto Entertainment","u":"MicroProse","g":"Adventure, action","r":"October 22, 1997","l":"https://en.wikipedia.org/wiki/Dark_Earth"},{"t":"Dark Reign: The Future of War","p":["Windows"],"d":"Auran","u":"Activision","g":"Real-time strategy","r":"September 17, 1997","l":"https://en.wikipedia.org/wiki/Dark_Reign:_The_Future_of_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1yh5.jpg","s":"Dark Reign narrowly beat Total Annihilation as the first RTS to incorporate 3D movement and positioning. This increases the strategic advantage of hills and mountains.\nEach mission puts you in the role of commander of either the Imperial army or the Freedom fighters in a campaign to undermine and eventually destroy the opposing force.\nThis game has many unusual features for the RTS genre. AI patterns you to simply give a unit the order \"Search and Destroy\" and it would drive off towards the enemy's last known location, in search for something to kill. There is also \"explore\" mode which let your units do all the map exploring for you. A mission/campaign editor is also provided."},{"t":"Dark Rift","p":["Nintendo 64","Windows"],"d":"Kronos Digital Entertainment","u":"Vic Tokai","g":"Fighting","r":"July 8, 1997","l":"https://en.wikipedia.org/wiki/Dark_Rift"},{"t":"Darkeden","p":["Windows"],"d":"SOFTON Entertainment","u":"SOFTON Entertainment","g":"MMORPG","l":"https://en.wikipedia.org/wiki/Darkeden"},{"t":"Darklight Conflict","p":["MS-DOS","PlayStation","Sega Saturn"],"d":"Rage Software","u":"Electronic Arts","g":"Space combat simulator","r":"March 28, 1997","l":"https://en.wikipedia.org/wiki/Darklight_Conflict"},{"t":"Decisive Battles of WWII: The Ardennes Offensive","p":["Windows"],"d":"Strategic Studies Group","u":"Strategic Simulations, Inc.","g":"Computer wargame","r":"June 9, 1997","l":"https://en.wikipedia.org/wiki/Decisive_Battles_of_WWII:_The_Ardennes_Offensive"},{"t":"Deer Hunter","p":["Windows","macOS","Game Boy Color"],"d":"Sunstorm Interactive","u":"WizardWorks","r":"October 1997","l":"https://en.wikipedia.org/wiki/Deer_Hunter_(1997_video_game)"},{"t":"Defiance","p":["Windows"],"d":"Logicware","u":"Visceral Productions","g":"First-person shooter","r":"October 29, 1997","l":"https://en.wikipedia.org/wiki/Defiance_(1997_video_game)"},{"t":"Deus","p":["MS-DOS","Windows"],"d":"Silmarils","u":"ReadySoft, Silmarils","g":"Survival, simulation","r":"January 1997","l":"https://en.wikipedia.org/wiki/Deus_(video_game)"},{"t":"Devil Summoner: Soul Hackers","p":["Sega Saturn"],"d":"Atlus","u":"Atlus, Atlus USA, NIS America","g":"Role-playing","r":"November 13, 1997","l":"https://en.wikipedia.org/wiki/Devil_Summoner:_Soul_Hackers","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co84yg.jpg","s":"Soul Hackers delivers a first-person, dungeon-crawling RPG experience set in a future where technology and otherworldly forces meet in a macabre fusion of cyberpunk futurism and gothic horror. A first-person sci-fi RPG epic, Soul Hackers tells of a city held up as a beacon of humanity's triumph of technology, but with an infernal secret. In this would-be utopia, a group of hackers takes on a centuries-old mystic society, and a battle for control over humanity's fate is about to begin."},{"t":"Diablo","p":["Windows","MS-DOS"],"u":"Blizzard Entertainment","r":"January 3, 1997","l":"https://en.wikipedia.org/wiki/Diablo_(video_game)"},{"t":"Diablo: Hellfire","p":["Windows"],"d":"Synergistic Software","u":"Sierra On-Line","g":"Action role-playing, hack and slash","r":"November 25, 1997","l":"https://en.wikipedia.org/wiki/Diablo:_Hellfire"},{"t":"Diddy Kong Racing","p":["Nintendo 64"],"u":"Rare","g":"Racing","r":"November 21, 1997","l":"https://en.wikipedia.org/wiki/Diddy_Kong_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1wgj.jpg","s":"Diddy Kong Racing is set on Timber's Island and revolves around Diddy Kong and his friends' attempt to defeat the intergalactic antagonist, a wizarding pig named Wizpig, through winning a series of races. The player can take control of any of the featured characters throughout the game. Diddy Kong Racing features five worlds with four racetracks each, and the ability to drive a car, hovercraft, or pilot an aeroplane."},{"t":"Digital Dance Mix Vol. 1 Namie Amuro","p":["Sega Saturn"],"d":"Sega AM2","u":"Sega","g":"Music game","r":"January 10, 1997","l":"https://en.wikipedia.org/wiki/Digital_Dance_Mix_Vol._1_Namie_Amuro"},{"t":"Dilbert's Desktop Games","p":["Windows"],"d":"Cyclops Software","u":"DreamWorks Interactive","g":"Puzzle, action","r":"October 1997","l":"https://en.wikipedia.org/wiki/Dilbert's_Desktop_Games"},{"t":"Disney's Hercules Action Game","p":["Windows","PlayStation"],"d":"Eurocom Entertainment Software","u":"Virgin Interactive Entertainment, Disney Interactive Studios, Sony Computer Entertainment","g":"Platform, Arcade","r":"July 3, 1997","l":"https://www.igdb.com/games/disneys-hercules-action-game","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5l0x.jpg","s":"Disney's Hercules Action Game is a platform game mainly two-dimensional, although in many missions the player can walk to other planes via pathways or stairs. There are ten levels and three difficulty modes: Beginner, Medium, and Herculean. Hercules can jump, grab ledges, swing on poles, and jump while running. He has a variety of attack moves at his disposal."},{"t":"Doctor Who: Destiny of the Doctors","p":["Windows"],"d":"Studio Fish","u":"BBC Multimedia","g":"Action","r":"December 5, 1997","l":"https://en.wikipedia.org/wiki/Doctor_Who:_Destiny_of_the_Doctors"},{"t":"DoDonPachi","p":["Sega Saturn","Arcade"],"g":"Shooter, Arcade","r":"February 5","l":"https://en.wikipedia.org/wiki/DoDonPachi","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1um4.jpg","s":"Compared to DonPachi, DoDonPachi is generally known for introducing new gameplay elements while improving or changing existing ones. The overall background of the game, unlike following sequels, remains more or less centered around a supposed invasion by a mysterious race of mechanized aliens, which the player is called to face throughout its run. However, more sinister and shocking secrets lie beneath the surface, accessible only to those brave and skilled enough to clear the entire game."},{"t":"DogDay","p":["Windows"],"d":"Eyst","u":"Infogrames Entertainment SA","g":"Graphic adventure","l":"https://en.wikipedia.org/wiki/DogDay"},{"t":"Donkey Kong Land III","p":["Game Boy"],"d":"Rare","u":"Nintendo","g":"Platform","r":"October 27, 1997","l":"https://en.wikipedia.org/wiki/Donkey_Kong_Land_III","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2wvc.jpg","s":"Donkey Kong Land III is the last part in the Donkey Kong Land series and was released for the Game Boy by Nintendo in 1997.\n\nFame-and-fortune seekers have flooded Donkey Kong Country in search of the fabled Lost World. Dixie Kong & Kiddy Kong rush through 36 Kong-sized levels of action and adventure. Use your animal friends - Squitter the spider, Squawks the parrot, Ellie the elephant, Enguarde the swordfish and Parry the parallel bird - to help you prove your adventuring skills and find the Lost World before someone else does!"},{"t":"Doom 64","p":["Nintendo 64"],"d":"Midway Studios San Diego","u":"Midway Games, GT Interactive","g":"First-person shooter","r":"April 4, 1997","l":"https://en.wikipedia.org/wiki/Doom_64","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2gro.jpg","s":"You killed the Demons once, they were all dead. Or so you thought... A single Demon Entity escaped detection. Systematically it altered decaying, dead carnage back into grotesque living tissue. The Demons have returned - stronger and more vicious than ever before. You mission is clear, there are no options: kill or be killed!"},{"t":"Dragon Ball GT: Final Bout","p":["PlayStation"],"d":"Tose","u":"Bandai, Atari","g":"Fighting","r":"August 21, 1997","l":"https://en.wikipedia.org/wiki/Dragon_Ball_GT:_Final_Bout","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co54d3.jpg","s":"After achieving cult hit status around the globe, Dragon Ball GT has finally arrived in the U.S. This polygon rendered fighting game features 10 of the best warriors from the animated television series going head-to-head in a no-holds-barred tournament. Each player has devastating finishing moves, including the infamous \"Meteor Smash\", which can be countered by an opponent, resulting in some of the most incredible power struggles you'll ever see! There are also 8 playable hidden characters and a practice mode that lets you build up the skills of each fighter. Now, you can find out what gamers around the world already know -- Dragon Ball GT is the ultimate fighting game!"},{"t":"Dragon Beat: Legend of Pinball","p":["PlayStation"],"d":"Map Japan","u":"Map Japan","g":"Pinball","r":"November 27, 1997","l":"https://en.wikipedia.org/wiki/Dragon_Beat:_Legend_of_Pinball"},{"t":"Dragon Dice","p":["Windows"],"d":"Interplay Entertainment","u":"Interplay Entertainment","g":"Strategy","l":"https://en.wikipedia.org/wiki/Dragon_Dice_(video_game)"},{"t":"Dragon Lore II: The Heart of the Dragon Man","p":["Windows"],"d":"Cryo Interactive","u":"Interplay Entertainment","g":"Action role-playing","l":"https://en.wikipedia.org/wiki/Dragon_Lore_II:_The_Heart_of_the_Dragon_Man"},{"t":"Dreams to Reality","p":["Windows","PlayStation"],"d":"Cryo Interactive Entertainment","u":"Cryo Interactive Entertainment, Interplay Productions","g":"Action-adventure","l":"https://en.wikipedia.org/wiki/Dreams_to_Reality"},{"t":"Dual Heroes","p":["Nintendo 64"],"d":"Produce!","u":"JP Hudson Soft, NA Electro Brain, PAL Gaga Interactive Media","g":"Fighting","r":"December 5, 1997","l":"https://en.wikipedia.org/wiki/Dual_Heroes"},{"t":"Duckman: The Graphic Adventures of a Private Dick","p":["Windows"],"d":"Illusions Gaming Company","u":"Playmates Interactive","g":"Graphic adventure game","r":"May 31, 1997","l":"https://en.wikipedia.org/wiki/Duckman:_The_Graphic_Adventures_of_a_Private_Dick"},{"t":"Dungeon Keeper","p":["Windows","MS-DOS"],"u":"Electronic Arts","g":"Real Time Strategy (RTS), Strategy","r":"June 26, 1997","l":"https://en.wikipedia.org/wiki/Dungeon_Keeper","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3wg6.jpg","s":"Dungeon Keeper is a strategy video game in which the player attempts to build and manage a dungeon or lair while protecting it from invading 'hero' characters intent on stealing the player's accumulated treasures and killing various monsters. This was Peter Molyneux's final project with Bullfrog before he left the company in August 1997 to form Lionhead Studios.\n\nThe player uses a mouse, represented in-game as a hand, to interact with a bar on the left-hand side of the screen, allowing them to select which rooms to build and which spells to cast. The player can also use the hand to pick up creatures and objects in the dungeon and carry them around, allowing for tactics such as gathering an assault force and dropping off the creatures en masse once a foothold has been established. The hand also allows the player to \"slap\" objects and thereby interact with them: creatures will hurry up when slapped, some traps will be triggered and prisoners in the Torture Chamber can be tortured.\n\nThe main game view is in isometric perspective; this view can be zoomed and rotated. The player also has the option of possessing one of their creatures, and seeing the dungeon from that creature's first-person perspective, as well as using their attacks and abilities. The map is divided into a grid of rectangles, most of which are invisible. A smaller part of the map is shown as a minimap in the top left corner of the screen.\n\nA world map is also available, and at the beginning of the game the player is allocated one of the 20 regions of a fictional, idyllic country to destroy. As the player progresses through these regions, each of which represents a level of the game, the areas previously conquered will appear ransacked, twisted, and evil. Before starting a new level, the Mentor will tell the player about the current region and its attributes. After completing a level, the Mentor will talk about the \"improvement\" of the destroyed region: \"The streets run with the blood of the slain. Screams of pain and howls of anguish rip the night air like a vengeful siren's song. This really is somewhere you can take the kids for the weekend.\"\n\nThe Dungeon Heart represents the Dungeon Keeper's own link to the world. If it is destroyed, the player loses the level, and must restart. Along with the heart, the player begins with a small number of imps, the generic work force for all dungeon activities: they can dig tunnels into the surrounding soil, capture enemy rooms and Portals, mine gold and gems, set traps, and even attack when desperate or threatened. Slapping creatures forces them to work faster for a while, but removes some of their health and happiness.\n\nOnce the Imps are busily working, the player must then set up a basic infrastructure: Lairs for monsters, a Hatchery (where chickens, which serve as food for the minions, are bred), and a Treasury for storing gold. After connecting the dungeon to a \"Portal\", monsters will arrive. As the game progresses, the player moves along a technology tree, unlocking further rooms.\n\nThe dungeon has a fleshed-out ecology: some creatures are natural enemies. Flies and Spiders are often found at odds with one another, while a Horned Reaper, if it has gone berserk, will attack all creatures in its path. The goals for each level are fairly straightforward: they generally fall along the lines of eliminating the heroic force or destroying all other Dungeon Keepers on the level."},{"t":"Dynasty Warriors","p":["PlayStation"],"d":"Omega Force","u":"Koei","g":"Fighting","r":"February 28, 1997","l":"https://en.wikipedia.org/wiki/Dynasty_Warriors_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co9blb.jpg","s":"Dynasty Warriors is a 3D fighting game steeped in traditional Chinese history and mythology, its characters being warriors from the Three Kingdoms era, a setting that was used by Koei before in their Romance of the Three Kingdoms series."},{"t":"Dōsei","p":["Windows"],"d":"Tactics","u":"Tactics, Nexton, DMM","g":"Eroge, social simulation game","r":"May 23, 1997","l":"https://en.wikipedia.org/wiki/D%C5%8Dsei"},{"t":"Earth 2140","p":["MS-DOS","Windows"],"d":"Reality Pump Studios","u":"TopWare Interactive, Interplay Productions","g":"Strategy","l":"https://en.wikipedia.org/wiki/Earth_2140"},{"t":"East Front","p":["Windows"],"d":"TalonSoft","u":"TalonSoft","g":"Computer wargame","r":"October 30, 1997","l":"https://en.wikipedia.org/wiki/East_Front_(video_game)"},{"t":"Eberouge","p":["Sega Saturn","PlayStation"],"d":"Japan Media Programming","u":"Takara","g":"Dating sim / Strategy","r":"May 30, 1997","l":"https://en.wikipedia.org/wiki/Eberouge"},{"t":"Ecstatica II","p":["Windows","MS-DOS"],"g":"Action, Adventure","r":"June 10","l":"https://en.wikipedia.org/wiki/Ecstatica_II","i":"images/steam-4834850.jpg","s":"Ecstatica II is a dark fantasy action-adventure built from a one-of-a-kind ellipsoid world. Return as a prince to a kingdom sacked by demons under a blood-red sky. Cast spells and trade blows to restore the shattered Elder Sign and free the sorceress Ecstatica."},{"t":"Egypt 1156 B.C.","p":["Windows"],"d":"Cryo Interactive Entertainment","u":"Cryo Interactive Entertainment, Canal+ Multimedia, Réunion des Musées Nationaux, DreamCatcher Games","g":"Adventure","l":"https://en.wikipedia.org/wiki/Egypt_1156_B.C."},{"t":"Einhänder","p":["PlayStation"],"u":"Square","g":"Shooter","r":"November 20, 1997","l":"https://en.wikipedia.org/wiki/Einh%C3%A4nder","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4pur.jpg","s":"Einhänder is a futuristic side-scrolling shooter featuring explosive visuals, pounding techno music, and simulated 3D gameplay."},{"t":"EJay","p":["Windows"],"d":"Empire Interactive, Unique Development Software, Yelsi AG","u":"Empire Interactive, Crave Entertainment, Ingram Entertainment","g":"Music","l":"https://en.wikipedia.org/wiki/EJay"},{"t":"Elemental Gearbolt","p":["PlayStation"],"d":"Alfa System","u":"Sony Computer Entertainment, Working Designs","g":"Light gun shooter","r":"December 11, 1997","l":"https://en.wikipedia.org/wiki/Elemental_Gearbolt"},{"t":"Emperor of the Fading Suns","p":["Windows"],"d":"Holistic Design","u":"SegaSoft","g":"Turn-based strategy, 4X","r":"January 23, 1997","l":"https://en.wikipedia.org/wiki/Emperor_of_the_Fading_Suns"},{"t":"Enemy Nations","p":["Windows"],"d":"Windward Studios","u":"Head Games Publishing","g":"Real-time strategy","r":"March 18, 1997","l":"https://en.wikipedia.org/wiki/Enemy_Nations"},{"t":"Entrepreneur","p":["Windows"],"d":"Stardock Systems","u":"Stardock Systems","g":"Business simulation","r":"November 10, 1997","l":"https://en.wikipedia.org/wiki/Entrepreneur_(video_game)"},{"t":"Everybody's Golf","p":["PlayStation"],"d":"Camelot Software Planning","u":"Sony Computer Entertainment","g":"Sports","r":"July 17, 1997","l":"https://en.wikipedia.org/wiki/Everybody's_Golf_(1997_video_game)"},{"t":"Evolution: The Game of Intelligent Life","p":["Windows"],"d":"Crossover Technologies","u":"Interplay Entertainment, Discovery Channel Multimedia","g":"Educational, Life simulation, Real-time strategy","r":"December 1, 1997","l":"https://en.wikipedia.org/wiki/Evolution:_The_Game_of_Intelligent_Life"},{"t":"Excalibur 2555 AD","p":["PlayStation","Windows"],"d":"Tempest Software, Fish Ltd.","u":"Telestar Electronic Studios, Sir-Tech","g":"Action-adventure","r":"April 11, 1997","l":"https://en.wikipedia.org/wiki/Excalibur_2555_AD"},{"t":"Extreme Assault","p":["MS-DOS"],"d":"Blue Byte","u":"Blue Byte","g":"Action","r":"July 22, 1997","l":"https://en.wikipedia.org/wiki/Extreme_Assault"},{"t":"Extreme-G","p":["Nintendo 64"],"d":"Probe Entertainment","u":"Acclaim Entertainment","g":"Racing","r":"October 27, 1997","l":"https://en.wikipedia.org/wiki/Extreme-G","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co7myg.jpg","s":"Extreme-G is a futuristic racing game with an emphasis on speed. It also features many weapons and an F-Zero style energy shield and regeneration."},{"t":"F-22 Raptor","p":["Windows"],"d":"Novalogic","u":"Novalogic","g":"Air combat simulation","r":"November 20, 1997","l":"https://en.wikipedia.org/wiki/F-22_Raptor_(video_game)"},{"t":"F-22: Air Dominance Fighter","p":["Windows"],"d":"Digital Image Design","u":"Ocean Software, Ocean of America","g":"Combat flight simulator","r":"December 1997","l":"https://en.wikipedia.org/wiki/F-22:_Air_Dominance_Fighter"},{"t":"F/A-18 Hornet 3.0","p":["Windows","macOS"],"d":"Graphic Simulations","u":"Graphic Simulations","g":"Combat flight simulator","l":"https://en.wikipedia.org/wiki/F/A-18_Hornet_3.0"},{"t":"F1 Pole Position 64","p":["Nintendo 64"],"d":"Human Entertainment","u":"Human Entertainment, Ubi Soft","g":"Racing","r":"March 28, 1997","l":"https://en.wikipedia.org/wiki/F1_Pole_Position_64"},{"t":"F1 Racing Simulation","p":["Windows"],"d":"Ubi Studios","u":"Ubi Soft","g":"Sport, sim racing","l":"https://en.wikipedia.org/wiki/F1_Racing_Simulation"},{"t":"Faery Tale Adventure II: Halls of the Dead","p":["MS-DOS","Windows"],"d":"The Dreamers Guild","u":"Encore Software","g":"Action role-playing","r":"August 1997","l":"https://en.wikipedia.org/wiki/Faery_Tale_Adventure_II:_Halls_of_the_Dead"},{"t":"Fallen Haven","p":["Windows"],"d":"Micomeq","u":"Interactive Magic","g":"Strategy","r":"March 1997","l":"https://en.wikipedia.org/wiki/Fallen_Haven"},{"t":"Fallout","p":["Windows","MS-DOS"],"u":"Interplay Productions","r":"October 10, 1997","l":"https://en.wikipedia.org/wiki/Fallout_(video_game)"},{"t":"Fallout: A Post Nuclear Role Playing Game","p":["macOS","MS-DOS","Windows"],"d":"Interplay Entertainment, Black Isle Studios","u":"Edusoft, MacPlay, Interplay Entertainment, Bethesda Softworks","g":"Role-playing (RPG)","r":"October 10, 1997","l":"https://www.igdb.com/games/fallout-a-post-nuclear-role-playing-game","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1ybn.jpg","s":"The Vault Dweller is tasked with exploring post-nuclear California in order to retrieve a water chip to replace the broken chip of Vault 13, their home, which they are the first person to ever leave. The player will engage in Western RPG character building and turn-based tactical combat while getting to know settlements and factions of people, mutants and ghouls through branching dialogue trees."},{"t":"Famista 64","p":["Nintendo 64"],"d":"Namco","u":"Namco","g":"Sports","r":"November 28, 1997","l":"https://en.wikipedia.org/wiki/Famista_64"},{"t":"Fantastic Four","p":["PlayStation"],"d":"Probe Entertainment","u":"Acclaim Entertainment","g":"Beat 'em up","r":"August 1997","l":"https://en.wikipedia.org/wiki/Fantastic_Four_(1997_video_game)"},{"t":"Felony 11-79","p":["PlayStation"],"d":"Climax Entertainment","u":"Yanoman, ASCII Entertainment","g":"Racing","r":"May 29, 1997","l":"https://en.wikipedia.org/wiki/Felony_11-79"},{"t":"FIFA Soccer 64","p":["Nintendo 64"],"d":"EA Canada","u":"EA Sports","g":"Sports","r":"March 27, 1997","l":"https://en.wikipedia.org/wiki/FIFA_Soccer_64","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co207w.jpg","s":"FIFA Soccer 64 delivers the intensity and drama of international soccer to the Nintendo 64. You can choose from 150 national and club teams and develop your tactics and strategies in a friendly match. And when the time comes, try to win a Tournament. If you like something more substantial than tournament play, try to win a Season and become a league champion, or skip straight to the Playoffs. Should a friend want to join the action, he can with the Two-Player mode. In all of the game modes, you can play with free-and-loose Arcade rules, or strict referees and penalties in Simulation. Thanks to the motion-captured animation, you'll get smooth and realistic player movement, which helps put you in the middle of the action. Try to become an international soccer sensation with FIFA Soccer 64"},{"t":"FIFA: Road to World Cup 98","p":["Windows","MS-DOS","Nintendo 64","PlayStation","Sega Saturn"],"g":"Sport","r":"November 30","l":"https://www.igdb.com/games/fifa-road-to-world-cup-98","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1u3k.jpg","s":"The late-1997 edition of FIFA was heavily tied in with the qualifying procedure for the 1998 World Cup. In the Road to the World Cup mode, you take a team from first qualification through to the main tournament, using the varying systems in different parts of the world. The game features 16 distinct outdoor stadia. The League play features 189 clubs and 11 leagues. Each team has specific crowd chants incorporated into the ambient sound.\n\nThe action is faster than in previous versions, and AI has been expanded. Players have distinct facial feature and hair styles. Each match is introduced by Des Lynam and commentated on by John Motson and former Scotland international Andy Gray."},{"t":"Fight 'N' Jokes","p":["MS-DOS"],"d":"Nasty Brothers Software","u":"Evolution Entertainment, Mental Drink","g":"Fighting","l":"https://en.wikipedia.org/wiki/Fight_'N'_Jokes"},{"t":"Fighters Megamix","p":["Sega Saturn"],"r":"April 30","l":"https://en.wikipedia.org/wiki/Fighters_Megamix"},{"t":"Fighting Bujutsu","p":["Arcade"],"d":"Konami","u":"Konami","g":"Fighting","r":"August 1997","l":"https://en.wikipedia.org/wiki/Fighting_Bujutsu"},{"t":"Fighting Force","p":["PlayStation","Windows"],"d":"Core Design","u":"Eidos Interactive, Crave Entertainment, Electronic Arts Victor","g":"Beat 'em up","r":"October 1997","l":"https://en.wikipedia.org/wiki/Fighting_Force","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co23ib.jpg","s":"Fighting Force players control one of four characters. They move through urban and science fiction environments, battling waves of oncoming enemies with weapons ranging from fists and bottles to knives, chairs and guns. The player can make some choices as to which territory to travel through.\n\nThe four characters have various reasons for taking on Dr. Zeng, a criminal mastermind with an army at his command. The action starts with a police cordon around Zeng's office skyscraper, moving to such locales as a shopping mall, subway and Coast Guard base before finally ending at the top of Zeng's island headquarters."},{"t":"Final Fantasy Tactics","p":["PlayStation"],"g":"Role-playing (RPG), Turn-based strategy (TBS), Tactical","r":"June 20","l":"https://en.wikipedia.org/wiki/Final_Fantasy_Tactics","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2yx4.jpg","s":"Lead epic battles in a new FINAL FANTASY world. Betrayal and darker dealings await in Squaresoft's game of war. Fight hundreds of battles across dangerous 3D terrain as an ancient blood feud awakens a deadlier foe."},{"t":"Final Fantasy VII","p":["PlayStation"],"u":"Square","g":"Role-playing (RPG), Adventure","r":"January 31, 1997","l":"https://en.wikipedia.org/wiki/Final_Fantasy_VII","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2kx2.jpg","s":"The Western release of Final Fantasy VII (released as Final Fantasy VII International in Japan) included additional elements and alterations, such as streamlining of the menu and Materia system, reducing the health of enemies, new visual cues to help with navigation across the world map, and additional cutscenes relating to Cloud's past."},{"t":"Final Furlong","p":["Arcade"],"d":"Namco","u":"Namco","g":"Racing","l":"https://en.wikipedia.org/wiki/Final_Furlong"},{"t":"Final Liberation: Warhammer Epic 40,000","p":["Windows"],"d":"Holistic Design","u":"Strategic Simulations","g":"Turn-based tactics","r":"November 20, 1997","l":"https://en.wikipedia.org/wiki/Final_Liberation:_Warhammer_Epic_40,000","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3h3x.jpg","s":"SSI, the masterminds behind the Five Star General Series’, bring their Midas touch to the Warhammer 40,000 world in the first ever video-game adaption of the Epic table-top game. With over 85 unit types, this addition to the 40k franchise brings the vastness and depth of an Epic-style battle to your PC, allowing you greater selection and customisation over your army. This, along with the multiple scenarios and battlefronts to fight from, will keep your strategic mind on edge for hours on end."},{"t":"Flight Unlimited II","p":["Windows"],"d":"Looking Glass Studios","u":"Eidos Interactive","g":"Amateur flight simulator","r":"November 24, 1997","l":"https://en.wikipedia.org/wiki/Flight_Unlimited_II"},{"t":"FlightGear","p":[],"l":"https://en.wikipedia.org/wiki/FlightGear"},{"t":"Flying Corps","p":["MS-DOS","Windows"],"d":"Rowan Software","u":"Empire Interactive","g":"Combat flight simulation game","r":"January 16, 1997","l":"https://en.wikipedia.org/wiki/Flying_Corps"},{"t":"Flying Dragon","p":["Nintendo 64"],"d":"Culture Brain","u":"Culture Brain, Natsume Inc.","g":"Fighting, role-playing","r":"December 18, 1997","l":"https://en.wikipedia.org/wiki/Flying_Dragon"},{"t":"Forbes Corporate Warrior","p":[],"d":"Brooklyn Multimedia","u":"Byron Preiss Multimedia","g":"First-person shooter","r":"August 15, 1997","l":"https://en.wikipedia.org/wiki/Forbes_Corporate_Warrior"},{"t":"Forced Alliance","p":["Windows"],"d":"Orbital Studios","u":"Ripcord Games","g":"Action, Simulation","r":"September 24, 1997","l":"https://en.wikipedia.org/wiki/Forced_Alliance"},{"t":"Formula 1 97","p":["PlayStation"],"u":"Psygnosis","r":"September 26, 1997","l":"https://en.wikipedia.org/wiki/Formula_1_97"},{"t":"Formula 1: Championship Edition","p":["PlayStation"],"d":"Bizarre Creations","u":"Psygnosis","g":"Racing, Simulator, Sport","r":"September 26, 1997","l":"https://www.igdb.com/games/formula-1-championship-edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co9c63.jpg","s":"An updated version of Psygnosis' first Formula 1 game. It features all tracks, drivers and cars from the 1997 season. Both an arcade mode and a realistic Grand Prix mode are available. New features are higher resolution and split-screen multiplayer."},{"t":"Free Talk Studio","p":["Sega Saturn","PlayStation","Windows"],"d":"Media Entertainment","u":"Media Entertainment","g":"Simulation video game","r":"May 9, 1997","l":"https://en.wikipedia.org/wiki/Free_Talk_Studio"},{"t":"Freestyle Boardin' '99","p":["Sega Saturn","PlayStation"],"d":"Atelier Double","u":"Pony Canyon, Funsoft GmbH, Capcom","g":"Snowboarding","r":"December 18, 1997","l":"https://en.wikipedia.org/wiki/Freestyle_Boardin'_'99"},{"t":"Frogger","p":["PlayStation","Windows"],"d":"Sony Computer Entertainment Europe","u":"Hasbro Interactive","g":"Action","r":"October 31, 1997","l":"https://en.wikipedia.org/wiki/Frogger_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co49gz.jpg","s":"A remake and reimagining of Frogger. However, unlike the original game, most of the maps are more complex and require exploration. In each level, the player must collect five baby frogs within a certain amount of time. There are various obstacles, traps, and enemies which must be avoided and usually are unique to a certain zone. There are a total of 33 levels spread out across nine different zones."},{"t":"Front Mission 2","p":["PlayStation"],"d":"G-Craft","u":"Square","g":"Tactical role-playing game","r":"September 25, 1997","l":"https://en.wikipedia.org/wiki/Front_Mission_2"},{"t":"Front Mission Alternative","p":["PlayStation"],"d":"Square","u":"Square","g":"Real-time strategy","r":"December 18, 1997","l":"https://en.wikipedia.org/wiki/Front_Mission_Alternative"},{"t":"Front Page Sports: Baseball Pro '98","p":["Windows"],"d":"Sierra On-Line","u":"Sierra On-Line","g":"Sports video game","r":"May 29, 1997","l":"https://en.wikipedia.org/wiki/Front_Page_Sports:_Baseball_Pro_'98"},{"t":"Front Page Sports: Football Pro '98","p":["Windows"],"d":"Synergistic Software","u":"Sierra On-Line","r":"November 1997","l":"https://en.wikipedia.org/wiki/Front_Page_Sports:_Football_Pro_'98"},{"t":"Front Page Sports: Golf","p":["Windows"],"d":"Headgate Studios","u":"Sierra On-Line","g":"Sports","r":"May 16, 1997","l":"https://en.wikipedia.org/wiki/Front_Page_Sports:_Golf"},{"t":"Front Page Sports: Ski Racing","p":["Windows"],"d":"Dynamix","u":"Sierra On-Line","r":"October 1997","l":"https://en.wikipedia.org/wiki/Front_Page_Sports:_Ski_Racing"},{"t":"G-Darius","p":["Arcade","Windows"],"d":"Taito","u":"Taito","g":"Scrolling shooter","r":"June 1997","l":"https://en.wikipedia.org/wiki/G-Darius","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coaa5v.jpg","s":"G-Darius is a shoot'em up arcade game, released by Taito in 1997. It is the fourth arcade installment of the Darius series and the first in the entire series to feature three-dimensional polygonal graphics. Much like previous installments in the Darius series, G-Darius is a two-dimensional horizontally scrolling shoot'em up set in a fictional future."},{"t":"G-Nome","p":["Windows"],"d":"7th Level","u":"7th Level, Bomico Entertainment Software","g":"Mech simulation","r":"February 18, 1997","l":"https://en.wikipedia.org/wiki/G-Nome"},{"t":"G-Police","p":["PlayStation","Windows"],"d":"Psygnosis","u":"Psygnosis","g":"Combat flight simulation","r":"October 15, 1997","l":"https://en.wikipedia.org/wiki/G-Police","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coacez.jpg","s":"G-Police is a 1997 combat flight simulator set in a hypothetical future where corporations lead space colonies. The player is Jeff Slater, a futuristic helicopter pilot who joins the G-Police to investigate his sister's death."},{"t":"GAG The Impotent Mystery","p":[],"l":"https://en.wikipedia.org/wiki/GAG_The_Impotent_Mystery"},{"t":"Galapagos","p":["Windows","macOS"],"d":"Anark Game Studios","u":"Electronic Arts","g":"Action, Simulation","r":"October 7, 1997","l":"https://en.wikipedia.org/wiki/Galapagos_(video_game)"},{"t":"Galilei ja kadonneet lelut","p":["Windows"],"d":"Mediayhtiö Sansibar Oy","l":"https://en.wikipedia.org/wiki/Galilei_ja_kadonneet_lelut"},{"t":"Gambys","p":["MS-DOS"],"d":"Viagem Interactive","u":"Portidata","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Gambys"},{"t":"Game & Watch Gallery","p":["Game Boy"],"d":"Nintendo R&D1, Tose","u":"Nintendo","g":"Action","r":"February 1, 1997","l":"https://en.wikipedia.org/wiki/Game_&_Watch_Gallery"},{"t":"Game & Watch Gallery 2","p":["Game Boy"],"d":"Nintendo R&D1, Tose","u":"Nintendo","g":"Action","r":"September 27, 1997","l":"https://en.wikipedia.org/wiki/Game_&_Watch_Gallery_2"},{"t":"Game Dev Story","p":["Windows"],"d":"Kairosoft","u":"Kairosoft","g":"Business simulation game","r":"April 1997","l":"https://en.wikipedia.org/wiki/Game_Dev_Story","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4mcq.jpg","s":"In Game Dev Story starting from a small office and a few thousand dollars in the wallet, you will need to hire the necessary personnel to develop the first game of the newborn company. This is how the list of candidates runs: there is a good programmer, an artist a bit scarce and a designer not bad; each of them, thanks to their skills, can give a more or less relevant hand in the realization of the project. Once everything is ready you must finally choose the kind and type of game to be realized, keeping in mind that some combinations will get married much better than others.\nIn Game Dev Story player can choose the platform on which to develop the project, and here things start to get very interesting. Game Dev Story in fact traces the last twenty years of the history of the video game industry, reproposing it in the form of an exhilarating parody: we start from the first computers, and then see almost all the major portable and home consoles announced. The names of companies, games and platforms have been revised, but are entirely traceable back to the originals; the Game Boy becomes the Game Kid and Microsoft is now Microx. However, in addition to the order in which the consoles are launched, the developers have chosen to keep even the success they have had at market level, which, on the one hand makes it even more pleasant to relive these twenty years from the inside , on the other hand, the player can easily predict big business and flop: nobody will be so crazy to develop a game for Virtual Boy (pardòn, Virtual Kid), while immediately supporting the fees of PlayStation and PlayStation 2 could lead to big boxing.\nThere are also annual awards, in which a jury rewards the best games of the year in the various categories. In the course of developing a project, however, the player will never remain with his hands: he will have to instruct his employees in order to cultivate their skills, buy the development kits of the various consoles, send announcements and look for new staff.\nIt is essential to keep the interest of the fans high, create hype and see the players line up days before the game, while sales can increase thanks to good reviews in specialized magazines. And yet, making a sequel to a successful game means starting the odds with good odds that the game sells, while the player can decide whether to invest everything in an ambitious project or make small titles in a very short time, until a budget has been reached. high enough to be able to make and place your console on the market."},{"t":"Gamera 2000","p":["PlayStation"],"d":"Surveyor Corp.","u":"Daiei Digital Entertainment","g":"Action","r":"April 25, 1997","l":"https://en.wikipedia.org/wiki/Gamera_2000"},{"t":"Gary Gadget","p":["Windows","macOS"],"u":"Levande Böcker","g":"Adventure game","l":"https://en.wikipedia.org/wiki/Gary_Gadget"},{"t":"Geobee Challenge","p":["Windows","macOS"],"d":"Human Code","u":"Mindscape","l":"https://en.wikipedia.org/wiki/Geobee_Challenge"},{"t":"Ghost in the Shell","p":["PlayStation"],"d":"Exact","u":"Sony Computer Entertainment, THQ","g":"Action, third-person shooter","r":"July 17, 1997","l":"https://en.wikipedia.org/wiki/Ghost_in_the_Shell_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coby7t.jpg","s":"This is a cyberpunk-themed third-person shooter video game developed by Exact and Production I.G for the PlayStation.\nThe game plot revolves around a recruit of Public Security Section 9 as he investigates and combats the Human Liberation Front. The player controls a Fuchikoma, a robotic fighting vehicle capable of traversing walls and ceilings."},{"t":"Gloom 3","p":["Amiga"],"d":"Alpha Software","u":"Guildhall","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Gloom_3"},{"t":"Golden Gate","p":["macOS","Windows"],"d":"iX Entertainment","u":"Panasonic Interactive Media","g":"Adventure video game","r":"April 1997","l":"https://en.wikipedia.org/wiki/Golden_Gate_(video_game)"},{"t":"GoldenEye 007","p":["Nintendo 64"],"u":"Nintendo","g":"Shooter","r":"August 25, 1997","l":"https://en.wikipedia.org/wiki/GoldenEye_007_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cocckw.jpg","s":"GoldenEye 007 is a first-person shooter based on the 1995 James Bond film. The game features a single-player campaign with 20 missions across multiple difficulty levels, emphasizing stealth, varied objectives and mission-based progression. Players can use a range of weapons and gadgets while navigating diverse environments inspired by the movie.\n\nThe local split-screen multiplayer mode supports up to four players and offers competitive scenarios such as deathmatch, team modes and character selection from the James Bond universe. The multiplayer component became widely recognized for its influence on console FPS design and is considered a landmark feature of the game."},{"t":"Gooka","p":[],"l":"https://en.wikipedia.org/wiki/Gooka"},{"t":"Gradius Gaiden","p":["PlayStation"],"d":"KCET","u":"Konami","g":"Scrolling shooter","r":"August 28, 1997","l":"https://en.wikipedia.org/wiki/Gradius_Gaiden"},{"t":"Gran Turismo","p":["PlayStation"],"u":"Sony Computer Entertainment","g":"Racing, Simulator","r":"December 23, 1997","l":"https://en.wikipedia.org/wiki/Gran_Turismo_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co6e10.jpg","s":"Gran Turismo is a racing game designed by Kazunori Yamauchi and is the first entry in the critically acclaimed simulator racing series bearing the same name. After five years of development time, it was well-received publicly and critically, shipping a total of 10.85 million copies worldwide as of March 2013, making it the best-selling PlayStation game. The game uses two different modes: Arcade Mode and Gran Turismo Mode. In the arcade mode, the player can freely choose the courses and vehicles they wish to use. Winning races unlocks additional cars and courses. However, Gran Turismo Mode requires the player to earn different levels of driver's licenses in order to qualify for events, and earn credits, trophies and prize cars by winning race championships. Gran Turismo features 140 cars and 11 race tracks (as well as their reversed versions)."},{"t":"Grand Slam","p":["PlayStation","Sega Saturn","Windows"],"d":"Burst Studios","u":"Virgin Interactive Entertainment","g":"Sports video game","r":"May 31, 1997","l":"https://en.wikipedia.org/wiki/Grand_Slam_(video_game)"},{"t":"Grand Theft Auto","p":["Windows","MS-DOS","PlayStation"],"g":"Shooter, Racing, Adventure","r":"November 27","l":"https://en.wikipedia.org/wiki/Grand_Theft_Auto_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2lb0.jpg","s":"Grand Theft Auto is the first game in the Grand Theft Auto series and a sandbox-crime game published by Rockstar Games.\n\nThe original Grand Theft Auto is made up of a series of levels each set in one of the three cities in the game. In each level, the player has a target number of points to achieve, and five lives to attain the score.\n\nThe score counter doubles as a money meter; the player can spend this money on paint jobs and various other things. However, any money spent is of course taken away from the score, making the goal that little bit further away.\n\nOn obtaining the target number of points, the player must then drive to a certain location to complete the level, which allows progress to the next one."},{"t":"Grandia","p":["Sega Saturn"],"g":"Role-playing (RPG)","r":"December 18","l":"https://en.wikipedia.org/wiki/Grandia_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coafk6.jpg","s":"Grandia is a role-playing video game developed by Game Arts and published by Entertainment Software Publishing for the Sega Saturn console as the first game in their Grandia series. Initially released in Japan in 1997, the game was later ported to the PlayStation in 1999, with an English version of the game appearing on the platform in North America in the following September by Sony Computer Entertainment America, and later in Europe in March 2000 by Ubisoft. The game was produced by much of the same staff who worked on the company's previous role-playing endeavor, the Lunar series, including producer Yoichi Miyagi and music composer Noriyuki Iwadare.\n\nSince its release, Grandia has become notable for its combat mechanics, which have been carried over to future games within the franchise, and has spawned two spin-off titles – Grandia: Digital Museum and Grandia: Parallel Trippers – both released exclusively in Japan. In celebration of the announcement of renewing development on Grandia Online, which acts as a prequel to Grandia, the game was re-released on Sony's PlayStation Network platform in Japan as a downloadable title in April 2009 and in North America on February 25, 2010. It was re-released in Europe on November 10, 2010."},{"t":"Grant, Lee, Sherman: Civil War Generals 2","p":["Windows"],"d":"Impressions Games","u":"Sierra On-Line","g":"Computer wargame","l":"https://en.wikipedia.org/wiki/Grant,_Lee,_Sherman:_Civil_War_Generals_2"},{"t":"Gridz","p":["macOS"],"d":"Green Dragon Creations","u":"Green Dragon Creations","g":"Puzzle video game, action game","l":"https://en.wikipedia.org/wiki/Gridz"},{"t":"Grolier's Cornerstone Home","p":[],"l":"https://en.wikipedia.org/wiki/Grolier's_Cornerstone_Home"},{"t":"Groove on Fight","p":["Arcade","Sega Saturn"],"d":"Atlus","u":"Atlus","g":"Fighting","r":"May 16, 1997","l":"https://en.wikipedia.org/wiki/Groove_on_Fight"},{"t":"Gubble","p":["Windows","macOS"],"d":"Actual Entertainment, Goo!","u":"Actual Entertainment, Mud Duck Productions, Midas Interactive Entertainment","g":"Puzzle","r":"May 1997","l":"https://en.wikipedia.org/wiki/Gubble"},{"t":"Gundam 0079: The War for Earth","p":["macOS","Windows","PlayStation","Apple Pippin"],"d":"Presto Studios","u":"Bandai Digital Entertainment Corporation","g":"Interactive film, Mecha, Military Science Fiction","l":"https://en.wikipedia.org/wiki/Gundam_0079:_The_War_for_Earth"},{"t":"Gunple: Gunman's Proof","p":["Super Nintendo Entertainment System"],"d":"Lenar","u":"ASCII","g":"Action-adventure, shooter","r":"January 31, 1997","l":"https://en.wikipedia.org/wiki/Gunple:_Gunman's_Proof"},{"t":"Hacx","p":[],"l":"https://en.wikipedia.org/wiki/Hacx"},{"t":"Harley-Davidson & L.A. Riders","p":["Arcade"],"d":"AM1","u":"Sega","g":"Driving game","r":"December 1997","l":"https://en.wikipedia.org/wiki/Harley-Davidson_&_L.A._Riders"},{"t":"Harmful Park","p":["PlayStation"],"d":"Sky Think System","u":"Sky Think System","g":"Scrolling shooter","r":"February 14, 1997","l":"https://en.wikipedia.org/wiki/Harmful_Park","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4l2x.jpg","s":"Harmful Park was only released on the Playstation in Japan by a small company named Sky Think Systems. It's your standard 2D side-scrolling shooter, except set in a bizarre amusement park. As the (relatively lengthy) introduction tells you, an evil scientist has taken over Heartful Park and is using it for nefarious purposes. One of his colleagues aims to stop him, but she's old to do it herself. So, she commands her two slacker daughters to save the day, equipping them with some kind of flying motorcycle armed to the teeth with strange weapons."},{"t":"Harvest Moon","p":["Super Nintendo Entertainment System"],"r":"June 17","l":"https://en.wikipedia.org/wiki/Harvest_Moon_(video_game)"},{"t":"Harvest Moon GB","p":["Game Boy"],"d":"Victor Interactive Software","u":"Victor Interactive Software, Natsume Inc., Nintendo","g":"Life simulation, role-playing","r":"December 19, 1997","l":"https://en.wikipedia.org/wiki/Harvest_Moon_GB","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2v6o.jpg","s":"Harvest Moon GB is the second game in the Harvest Moon series of video games, and was developed by Victor Interactive Software. Harvest Moon GB is the first portable Harvest Moon game, developed for the Game Boy. A Game Boy Color version was released later under the name Harvest Moon GBC."},{"t":"Hattrick","p":["Browser"],"d":"Hattrick Limited","g":"MMOG","r":"August 30, 1997","l":"https://en.wikipedia.org/wiki/Hattrick_(video_game)"},{"t":"Haunted Junction","p":[],"l":"https://en.wikipedia.org/wiki/Haunted_Junction"},{"t":"Have a N.I.C.E. Day!","p":["Windows"],"d":"Synetic","u":"Magic Bytes","g":"Racing","l":"https://en.wikipedia.org/wiki/Have_a_N.I.C.E._Day!"},{"t":"Heavy Gear","p":["Windows"],"d":"Activision","u":"Activision","g":"First-person shooter, vehicle simulation game","r":"November 26, 1997","l":"https://en.wikipedia.org/wiki/Heavy_Gear_(video_game)"},{"t":"Helicops","p":["Windows"],"d":"Paragon Visual Systems","u":"7th Level","g":"First-person shooter","r":"March 25, 1997","l":"https://en.wikipedia.org/wiki/Helicops_(video_game)"},{"t":"Herc's Adventures","p":["PlayStation","Sega Saturn"],"g":"Adventure","r":"July 31","l":"https://en.wikipedia.org/wiki/Herc%27s_Adventures","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2qbz.jpg","s":"Ahhh...ancient Greece. A fertile land, full of wine, women, and some of the best gyros you'll ever taste. Thanks to Persephone, the Greek goddess of spring and fertility, Greece is a wonderful paradise. But now the lord of the Underworld, Hades, has gone and kidnapped Persephone, causing the land to slowly wither away! Zeus, the King of the Gods, needs help in saving her, so who do you call? None other than three of the greatest warriors in the land! You can choose from the big 'n' buff Herc, the super swift Atlanta, or the young and street-smart Jason, each of whom have their own weapons and strengths. The game's 40 levels include many further variations and pastiches of Greek mythology and legend. It's all up to you to rescue Persephone and give Hades a beatdown he'll never forget!"},{"t":"Hercules","p":["PlayStation","Windows","Game Boy"],"d":"Eurocom Entertainment Software, Tiertex Design Studios","u":"Virgin Interactive, Sony Computer Entertainment, Majesco, Disney Interactive","g":"Action-adventure, Hack and slash, Platform","r":"July 3, 1997","l":"https://en.wikipedia.org/wiki/Hercules_(1997_video_game)"},{"t":"Heroes of Might and Magic II: The Price of Loyalty","p":["MS-DOS","Windows"],"d":"Cyberlore Studios","u":"The 3DO Company","g":"Turn-based strategy","r":"May 1997","l":"https://en.wikipedia.org/wiki/Heroes_of_Might_and_Magic_II:_The_Price_of_Loyalty"},{"t":"Hexen II","p":["Windows","MS-DOS"],"g":"Action","r":"September 11","l":"https://en.wikipedia.org/wiki/Hexen_II","i":"images/steam-9060.jpg","s":"The Four Horsemen of the Apocalypse lurk in the shadows before you. They are Death, Pestilence, Famine, and War. They are the root of all that is evil, but the least of your worries. The last of the three Serpent Riders yet lives."},{"t":"Highly Responsive to Prayers","p":[],"l":"https://en.wikipedia.org/wiki/Highly_Responsive_to_Prayers"},{"t":"History of the World","p":[],"d":"Colorado Computer Creations","u":"Eidos Interactive","l":"https://en.wikipedia.org/wiki/History_of_the_World_(video_game)"},{"t":"Hollywood Monsters","p":["Windows"],"d":"Pendulo Studios","u":"Dinamic Multimedia, FX Interactive","g":"Graphic adventure","r":"December 1997","l":"https://en.wikipedia.org/wiki/Hollywood_Monsters_(video_game)"},{"t":"Hot Shots Golf","p":["PlayStation"],"d":"Camelot Software Planning","u":"Sony Computer Entertainment of America, Sony Computer Entertainment Europe, Sony Computer Entertainment","g":"Simulator, Sport","r":"July 17, 1997","l":"https://www.igdb.com/games/hot-shots-golf--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5p17.jpg","s":"Everybody's Golf, known in Japan as Minna no Golf, is the first game in the Everybody's Golf series. The North American release was renamed Hot Shots Golf. It was the only game in the series to be developed by Camelot Software Planning, which later developed the Mario Golf series."},{"t":"I-0","p":[],"d":"Adam Cadre","g":"Interactive fiction","l":"https://en.wikipedia.org/wiki/I-0_(video_game)"},{"t":"I.Q.: Intelligent Qube","p":["PlayStation"],"d":"G-Artists","u":"Sony Computer Entertainment","g":"Puzzle","r":"January 31, 1997","l":"https://en.wikipedia.org/wiki/I.Q.:_Intelligent_Qube"},{"t":"IF-16","p":["Windows"],"d":"Digital Integration","u":"Interactive Magic","g":"Simulation","r":"September 1997","l":"https://en.wikipedia.org/wiki/IF-16"},{"t":"IF-22","p":["Windows"],"d":"Magic Labs","u":"Interactive Magic","g":"Combat flight simulator","r":"July 18, 1997","l":"https://en.wikipedia.org/wiki/IF-22"},{"t":"IfMUD","p":[],"d":"Liza Daly and project community","g":"Interactive fiction MUD","l":"https://en.wikipedia.org/wiki/IfMUD"},{"t":"IM1A2 Abrams","p":["Windows"],"d":"Charybdis Enterprises","u":"Interactive Magic","g":"Tank simulation","r":"March 23, 1997","l":"https://en.wikipedia.org/wiki/IM1A2_Abrams"},{"t":"Immemory","p":["Windows","macOS"],"d":"Chris Marker","u":"Exact Change","g":"Art game","l":"https://en.wikipedia.org/wiki/Immemory"},{"t":"Imperialism","p":["Windows","MS-DOS"],"g":"Indie, Strategy","r":"August 31","l":"https://en.wikipedia.org/wiki/Imperialism_(video_game)","i":"images/steam-2766160.jpg","s":"It is the 19th century - an age of steam power, revolution, and imperialist expansion. Engage in turn-based gameplay as you strive to ascend to unparalleled power through astute management of trade, industry, research, diplomacy, colonization, and warfare."},{"t":"Imperium Galactica","p":["MS-DOS","Windows"],"d":"Digital Reality","u":"GT Interactive","g":"4X","r":"March 1997","l":"https://en.wikipedia.org/wiki/Imperium_Galactica","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2a4q.jpg","s":"We are in the year 2300. The Galactic Empire, formed by the human species in the known universe, eventually split into numerous factions, seven alien races and two empires of renegade humans. One of the most dangerous, the Darglans threaten the coexistence and peace established between the various species. It is time to face the threat and stop the expansion. You start out as a young lieutenant and are given a series of missions to complete. You then advance to the next rank and are given more ships to control and more available commands, but you have more area of the universe to police and more colonies. This continues until you reach the rank of Grand Admiral, where you are able to view the whole map."},{"t":"Impressionists","p":["Windows","macOS"],"d":"Index+","g":"Educational","l":"https://en.wikipedia.org/wiki/Impressionists_(video_game)"},{"t":"IMSA World Championship Racing","p":[],"d":"Studio 3DO","u":"Studio 3DO","g":"Racing","l":"https://en.wikipedia.org/wiki/IMSA_World_Championship_Racing"},{"t":"Incubation: Time Is Running Out","p":["Windows"],"d":"Blue Byte","u":"Blue Byte","g":"Turn-based tactics","r":"October 17, 1997","l":"https://en.wikipedia.org/wiki/Incubation:_Time_Is_Running_Out","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2aom.jpg","s":"Travel to the colonized planet of Scayra, and enter the dark and terrifying world of Incubation - the latest episode in the Battle Isle saga. Following a power plant accident, the vast energy shield that separates the Chromian colonists from the indigenous life-forms - the Scay'Ger - suffers a total shut down, allowing contact between the two races for the very first time. A human virus has not infected the Scay'Ger, mutating them into violent, blood-thirsty monsters. As commander of a squad of elite space marines, only you can stop the vicious attacks and evacuate the remaining colonists before all is lost.\n\nThe battles in this turn-based tactical game are not waged in open fields, but fought within the dark and complex industrial buildings of the colony city; Scay Hallwa. You'll enjoy the unique challenge of leading your men through various alien scenarios, never knowing what's around the next corner or behind the next door.\n\nIncubation also features a real-time 3D environment and with detail and features never seen before in a game of this genre. The action can be viewed from the eyes of the individual soldiers, from the attacking aliens' perspective, or from any external position thanks to the complete camera freedom offered by the stunning graphics engine. All the events in the game are fully animated, as are the actions and movements of all the characters; giving them an incredibly lifelike apperance and a host of realistic mannerisms. They walk, rest, run and fight - all in glorious 3D."},{"t":"Independence Day","p":["Windows","MS-DOS","PlayStation","Sega Saturn"],"g":"Shooter, Simulator, Adventure","r":"February 28","l":"https://en.wikipedia.org/wiki/Independence_Day_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2f2y.jpg","s":"Independence Day is a combat flight simulator video game based on the 1996 film of the same name. The game was developed by Radical Entertainment, published by Fox Interactive and distributed by Electronic Arts for Microsoft Windows, PlayStation and Sega Saturn."},{"t":"Independence War","p":["Windows","MS-DOS"],"g":"Simulator","r":"November","l":"https://en.wikipedia.org/wiki/I-War_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/pwenkf7sduytxgxkf9ij.jpg","s":"A guerilla war has been raging in space for centuries. Human colonies are breaking away from Earth's control, declaring independence from the Commonwealth. As a Commonwealth Navy commander, your mission is to stop the Indie rebels and their attacks of terror and random piracy. It's a sophisticated, interstellar battle for life, and you must fight your way along the path between duty and justice. With luck and skill you can secure a victory for mankind."},{"t":"Industry Giant","p":["Windows"],"d":"JoWooD Productions","u":"JoWooD Productions, Interactive Magic","g":"Business simulation game","l":"https://en.wikipedia.org/wiki/Industry_Giant"},{"t":"Intelligent Qube","p":["PlayStation"],"d":"G-Artists","u":"Sony Computer Entertainment","g":"Puzzle, Strategy","r":"January 9, 1997","l":"https://www.igdb.com/games/intelligent-qube","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4vzz.jpg","s":"Intelligent Qube is a puzzle game for the PlayStation. In the game, the player controls a character who must run around a platform made of cubes, clearing certain cubes as they approach. Cubes are \"cleared\" by marking a spot on the stage, waiting for the cube to roll on top of it, and then deactivating the marked spot."},{"t":"International Rally Championship","p":["Windows"],"d":"Magnetic Fields, Europress","u":"Europress, Interplay / THQ","g":"Racing","r":"September 22, 1997","l":"https://en.wikipedia.org/wiki/International_Rally_Championship","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cocb2p.jpg","s":"International Rally Championship is a rally computer game which is part of the Rally Championship series. The game was released for Windows in 30 June 1997. It is developed by Magnetic Fields and published by Europress. Several different front covers were released for the game. The game is a sequel to the 1996 version of Network Q RAC Rally Championship. It would in turn be succeeded in 1999 by Mobil 1 Rally Championship."},{"t":"International Superstar Soccer Pro","p":["PlayStation"],"d":"Konami Computer Entertainment Tokyo","u":"Konami","g":"Sports","r":"May 2, 1997","l":"https://en.wikipedia.org/wiki/International_Superstar_Soccer_Pro"},{"t":"International Superstar Soccer Pro 98","p":["PlayStation"],"d":"Konami Computer Entertainment Tokyo","u":"Konami","g":"Sports","r":"December 11, 1997","l":"https://en.wikipedia.org/wiki/International_Superstar_Soccer_Pro_98","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1y4m.jpg","s":"International Superstar Soccer Pro 98, officially abbreviated as ISS Pro 98, is a football simulation game developed and published by Konami for the PlayStation in 1997. It is part of the International Superstar Soccer (ISS) series, known for its focus on realistic gameplay and detailed graphics for the time. ISS Pro 98 features a wide range of national teams, realistic player animations, and improved AI, making it one of the more advanced football games of its era.\n\nThe game offers various modes, including Exhibition, International Cup, World League, and Training. ISS Pro 98 is often remembered as one of the best football games on the original PlayStation.\n\nDespite not having the FIFPro license, the game showcased Italian player Fabrizio Ravanelli on the cover of its PlayStation version. Additionally, the German release featured Andreas Koepke from Germany, and the British release featured Paul Ince."},{"t":"Interstate '76","p":["Windows","MS-DOS"],"g":"Shooter, Racing","r":"February 28","l":"https://en.wikipedia.org/wiki/Interstate_%2776","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2b6s.jpg","s":"It's 1976 - a different '76. Stretched out before you are thousands of miles of desert - the American Southwest. The massive engine roars as you slam down the accelerator. It's time to get funked up. You are Groove Champion, auto-vigilante. Your agenda: Payback for your dead sister. Your weapon: A 425-horsepower '72 Picard Piranha with two 50-caliber M60 machine guns on top and a flame-thrower on the side. You're one mean dude in an even meaner ride. They've messed with the wrong Champion."},{"t":"Into the Void","p":["MS-DOS"],"d":"Adrenalin Entertainment","u":"Playmates Interactive","g":"4X, strategy","r":"April 16, 1997","l":"https://en.wikipedia.org/wiki/Into_the_Void_(video_game)"},{"t":"Iron Soldier 2","p":["Atari Jaguar CD","Atari Jaguar"],"d":"Eclipse Software Design","u":"Telegames","g":"Mech simulation","r":"April 23, 1997","l":"https://en.wikipedia.org/wiki/Iron_Soldier_2"},{"t":"Itoi Shigesato no Bass Tsuri No. 1","p":["Satellaview","Super Nintendo Entertainment System"],"d":"HAL Laboratory","u":"Nintendo","g":"Fishing","r":"February 21, 1997","l":"https://en.wikipedia.org/wiki/Itoi_Shigesato_no_Bass_Tsuri_No._1"},{"t":"J-League Dynamite Soccer 64","p":["Nintendo 64"],"d":"A-Max","u":"Imagineer","g":"Sports","r":"September 1997","l":"https://en.wikipedia.org/wiki/J-League_Dynamite_Soccer_64"},{"t":"J-League Eleven Beat 1997","p":["Nintendo 64"],"d":"Hudson Soft","u":"Hudson Soft","g":"Sports","r":"October 24, 1997","l":"https://en.wikipedia.org/wiki/J-League_Eleven_Beat_1997"},{"t":"Jack Nicklaus 4","p":["Windows","macOS"],"d":"Cinematronics","u":"Accolade, MacSoft","g":"Sports","r":"March 25, 1997","l":"https://en.wikipedia.org/wiki/Jack_Nicklaus_4"},{"t":"Jack Nicklaus 5","p":["Windows"],"d":"Eclipse Entertainment","u":"Accolade","g":"Sports video game","r":"November 24, 1997","l":"https://en.wikipedia.org/wiki/Jack_Nicklaus_5"},{"t":"Jack Orlando","p":["MS-DOS","Windows"],"d":"Toontraxx","u":"TopWare Interactive, JoWooD Productions","g":"Adventure","l":"https://en.wikipedia.org/wiki/Jack_Orlando"},{"t":"Jane's 688(I) Hunter/Killer","p":["Windows","MS-DOS"],"r":"July 4","l":"https://en.wikipedia.org/wiki/688(I)_Hunter/Killer"},{"t":"Jane's Fighters Anthology","p":["Windows"],"d":"Jane's Combat Simulations","u":"Electronic Arts","g":"Combat flight simulator","l":"https://en.wikipedia.org/wiki/Jane's_Fighters_Anthology"},{"t":"Jane's Longbow 2","p":["Windows"],"d":"Origin Systems","u":"Electronic Arts","g":"Combat flight simulator","r":"November 13, 1997","l":"https://en.wikipedia.org/wiki/Jane's_Longbow_2"},{"t":"Jersey Devil","p":["PlayStation"],"d":"Megatoon Studios","u":"Ocean Software, SCEA, Infogrames","g":"3D platformer","r":"December 12, 1997","l":"https://en.wikipedia.org/wiki/Jersey_Devil_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4v8z.jpg","s":"Jersey Devil, as the title implies, is loosely based upon the legendary New Jersey beast of the same name. Instead of the horrific beast the legend describes, the protagonist of the title is cute purple creature with long-ears and small wings. Dr. Knarf -- the villain of the piece -- has created a legion of mutated vegetables to do his evil bidding, and it falls to Jersey Devil to stop the maniacal scientist.\n\nTo do this, the purple protagonist must venture through a series of 3D platform stages spread across themed environments such as a museum, cemetery, forest, and even a haunted house. Endowed with an ample set of abilities, Jersey Devil must jump, glide, and tail whip his way through the hordes of vegetables and undead minions, the latter comprising such mainstays as zombies, bats, and spiders."},{"t":"Jet Moto 2","p":["PlayStation"],"d":"Sony Interactive Studios America, SingleTrac","u":"Sony Computer Entertainment","g":"Racing","r":"November 11, 1997","l":"https://en.wikipedia.org/wiki/Jet_Moto_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2qgd.jpg","s":"Jet Moto 2 is the sequel to the 1996 game Jet Moto.\n\nGameplay in the Jet Moto series differs from traditional racing games, as players instead control hoverbikes which hover close above the ground and can be driven over both land and water. Most of the courses in the games are designed to take advantage of this ability."},{"t":"Joint Strike Fighter","p":["Windows"],"d":"Innerloop Studios","u":"Eidos Interactive","g":"Air combat simulation","r":"December 10, 1997","l":"https://en.wikipedia.org/wiki/Joint_Strike_Fighter_(video_game)"},{"t":"Jonah Lomu Rugby","p":["MS-DOS","PlayStation","Sega Saturn"],"d":"Rage Software","u":"Codemasters","g":"Sports","r":"March 31, 1997","l":"https://en.wikipedia.org/wiki/Jonah_Lomu_Rugby"},{"t":"Judge Dredd","p":["Arcade","PlayStation"],"d":"Gremlin Interactive","u":"Acclaim Entertainment, Gremlin Interactive, Activision","g":"Light gun shooter","r":"October 1997","l":"https://en.wikipedia.org/wiki/Judge_Dredd_(1997_video_game)"},{"t":"JumpStart Adventures 5th Grade: Jo Hammet, Kid Detective","p":["Windows","macOS"],"d":"Knowledge Adventure","u":"Knowledge Adventure","g":"Educational/adventure","l":"https://en.wikipedia.org/wiki/JumpStart_Adventures_5th_Grade:_Jo_Hammet,_Kid_Detective"},{"t":"JumpStart Typing","p":["Windows","macOS"],"d":"Knowledge Adventure, Van Duyne Engineering","u":"Knowledge Adventure","g":"Educational","r":"October 15, 1997","l":"https://en.wikipedia.org/wiki/JumpStart_Typing"},{"t":"K-1 Revenge","p":["PlayStation"],"d":"Daft","u":"Xing Entertainment, Jaleco","g":"Sports, fighting","r":"September 25, 1997","l":"https://en.wikipedia.org/wiki/K-1_Revenge"},{"t":"Kakyūsei","p":[],"l":"https://en.wikipedia.org/wiki/Kaky%C5%ABsei"},{"t":"Katharsis","p":["MS-DOS"],"d":"Metropolis Software House","u":"Metropolis Software House, CD Projekt, TopWare Interactive","g":"Scrolling shooter","r":"March 17, 1997","l":"https://en.wikipedia.org/wiki/Katharsis_(video_game)"},{"t":"Kickoff '97","p":["MS-DOS","Windows"],"d":"Anco Software","u":"Maxis","g":"Sports","r":"June 11, 1997","l":"https://en.wikipedia.org/wiki/Kickoff_'97"},{"t":"Kirby's Dream Land 3","p":["Super Nintendo Entertainment System"],"g":"Platform, Adventure","r":"November 27","l":"https://en.wikipedia.org/wiki/Kirby%27s_Dream_Land_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cocikz.jpg","s":"That mean old King Dedede is at it again! He's causing his mischief and Dreamland's in trouble! Kirby, the resident hero of Dreamland, sets out to teach Dedede a lesson, this time with the help of many of his good friends!\n\nBut wait! Something's wrong! Dedede doesn't seem to be himself...\n\nLooks like Kirby has to stop Dedede and find out what is wrong with him! It almost seems like something's controlling him..."},{"t":"Kirby's Star Stacker","p":["Game Boy"],"d":"HAL Laboratory","u":"Nintendo","g":"Puzzle","r":"January 25, 1997","l":"https://en.wikipedia.org/wiki/Kirby's_Star_Stacker","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1zm8.jpg","s":"Join Kirby as he stacks the falling stars with help from his friends, Rick the Hamster, Kine the Sunfish, and Coo the Owl. Watch out for King Dedede. He is out to stop you! With a few quick moves and some well-timed strategy, you can quickly outwit him and move on to the next challenging level. Kirby's Star Stacker features pure puzzle fun for everyone. From above, blocks rain down constantly. From below, whole lines appear with unrelenting clock-like regularity. Simply sandwich the stars between Kirby's pals and you'll soon be on your way to the high score."},{"t":"KKnD","p":["MS-DOS","Windows"],"d":"Beam Software","u":"Melbourne House, Electronic Arts","g":"Real-time strategy","r":"March 5, 1997","l":"https://en.wikipedia.org/wiki/KKnD_(video_game)"},{"t":"KKND: Krush, Kill 'N' Destroy","p":["Windows"],"d":"Beam Software","u":"Electronic Arts","g":"Real Time Strategy (RTS), Strategy","r":"March 25, 1997","l":"https://www.igdb.com/games/kknd-krush-kill-n-destroy","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co7nkx.jpg","s":"KKnD, or Krush, Kill 'n' Destroy is a real-time strategy games in the KKnD series. The game takes place in a post-apocalyptic setting, where two factions are fighting for control over the few natural resources left. Each faction has its own campaign consisting of 15 missions each, and there is also a multiplayer mode which allows up to 6 people to play."},{"t":"Klonoa: Door to Phantomile","p":["PlayStation"],"g":"Platform","r":"December 11","l":"https://www.igdb.com/games/klonoa-door-to-phantomile","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3c4m.jpg","s":"Klonoa: Door to Phantomile is a side-scrolling platform game viewed from a \"2.5D\" perspective. The player moves the protagonist, Klonoa, along a path in a two-dimensional fashion, but the game is rendered in three dimensions. This allows the path followed to curve and for the player to interact with objects outside of the path."},{"t":"Koala Lumpur: Journey to the Edge","p":["Windows"],"d":"Media Concrete, Colossal Pictures","u":"Broderbund","g":"Adventure","r":"February 7, 1997","l":"https://en.wikipedia.org/wiki/Koala_Lumpur:_Journey_to_the_Edge"},{"t":"Konami Antiques MSX Collection","p":["PlayStation","Sega Saturn"],"d":"Konami Computer Entertainment Tokyo, Konami Computer Entertainment Yokohama","u":"Konami","g":"Various","r":"November 20, 1997","l":"https://en.wikipedia.org/wiki/Konami_Antiques_MSX_Collection"},{"t":"Konami GB Collection","p":[],"l":"https://en.wikipedia.org/wiki/Konami_GB_Collection"},{"t":"Kowloon's Gate","p":["PlayStation"],"d":"Sony Music Entertainment","u":"Sony Music Entertainment","g":"Adventure","r":"February 28, 1997","l":"https://en.wikipedia.org/wiki/Kowloon's_Gate"},{"t":"L.A. Blaster","p":["MS-DOS"],"d":"Cryo Interactive","u":"CDV Software","g":"Shooter","l":"https://en.wikipedia.org/wiki/L.A._Blaster"},{"t":"Lands of Lore: Guardians of Destiny","p":["MS-DOS","Windows"],"d":"Westwood Studios","u":"Virgin Interactive Entertainment","g":"Role-playing","r":"September 29, 1997","l":"https://en.wikipedia.org/wiki/Lands_of_Lore:_Guardians_of_Destiny"},{"t":"Langrisser IV","p":["Sega Saturn"],"d":"Career Soft","u":"Masaya","g":"Tactical role-playing game","r":"August 1, 1997","l":"https://en.wikipedia.org/wiki/Langrisser_IV"},{"t":"Last Rites","p":["MS-DOS"],"d":"Ocean Software","u":"Ocean Software","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Last_Rites_(video_game)"},{"t":"Le Mans 24","p":["Arcade"],"d":"Sega","u":"Sega","g":"Racing","r":"August 1997","l":"https://en.wikipedia.org/wiki/Le_Mans_24_(video_game)"},{"t":"League of Pain","p":["PlayStation","MS-DOS","Windows"],"d":"Beyond Reality","u":"Psygnosis","g":"Sports","r":"February 13, 1997","l":"https://en.wikipedia.org/wiki/League_of_Pain"},{"t":"LearnedLeague","p":[],"l":"https://en.wikipedia.org/wiki/LearnedLeague"},{"t":"Learning Adventures!","p":["Windows","macOS"],"d":"Cloud 9 Interactive","u":"Macmillan Digital Publishing","g":"Educational","l":"https://en.wikipedia.org/wiki/Learning_Adventures!"},{"t":"Legal Crime","p":["Windows"],"d":"Byte Enchanters","u":"Byte Enchanters","l":"https://en.wikipedia.org/wiki/Legal_Crime"},{"t":"Legend of the River King","p":["Game Boy"],"d":"Tose","u":"Natsume","g":"Fishing, role-playing game","r":"September 19, 1997","l":"https://en.wikipedia.org/wiki/Legend_of_the_River_King"},{"t":"Legend of the River King GB","p":["Game Boy"],"d":"Tose","u":"Natsume Inc., Nintendo, Pack-In-Soft, Victor Interactive Software","g":"Role-playing (RPG), Simulator, Sport, Adventure","r":"September 19, 1997","l":"https://www.igdb.com/games/legend-of-the-river-king-gb","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co7cmi.jpg","s":"You'll need all your angling and survival skills to succeed in this unique fishing RPG. On a perilous quest to capture a mysterious and mystical fish, you'll deploy a variety of tackle in both quiet lakes and raging rapids. Along the shores, dangerous animals are a constant threat. To get supplies, you'll sell some of your catch at village markets. You can also try your hand at raising a pet fish from embryo to adult and watch as it grows and even changes species!"},{"t":"LEGO Island","p":["Windows","MS-DOS"],"g":"Adventure","r":"September 26","l":"https://en.wikipedia.org/wiki/LEGO_Island","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3hp5.jpg","s":"Lego Island is a nonlinear game with a first-person perspective. The game features a series of missions including pizza delivery, jet ski racing, and putting the Brickster back in jail. It also features a variety of playable characters that each have unique abilities that can help the player throughout the game."},{"t":"Leonardo da Vinci","p":[],"g":"Interactive CD-ROM","l":"https://en.wikipedia.org/wiki/Leonardo_da_Vinci_(video_game)"},{"t":"LiberoGrande","p":["Arcade"],"d":"Namco","u":"Namco, Sony Computer Entertainment","g":"Sports","l":"https://en.wikipedia.org/wiki/LiberoGrande"},{"t":"Lifeforce Tenka","p":["PlayStation","Windows"],"d":"Psygnosis","u":"Psygnosis","g":"First-person shooter","r":"June 1997","l":"https://en.wikipedia.org/wiki/Lifeforce_Tenka"},{"t":"Links LS 1998","p":["Windows"],"d":"Access Software","u":"Access Software","g":"Sports","r":"July 2, 1997","l":"https://en.wikipedia.org/wiki/Links_LS_1998"},{"t":"Linley's Dungeon Crawl","p":[],"l":"https://en.wikipedia.org/wiki/Linley's_Dungeon_Crawl"},{"t":"Little Big Adventure 2","p":["MS-DOS","Windows"],"d":"Adeline Software","u":"Electronic Arts, Activision","g":"Adventure","r":"July 1, 1997","l":"https://en.wikipedia.org/wiki/Little_Big_Adventure_2"},{"t":"Loki's Minions Capture the Flag","p":["macOS","Linux","Windows"],"d":"LMCTF development team","g":"FPS","r":"November 12, 1997","l":"https://en.wikipedia.org/wiki/Loki's_Minions_Capture_the_Flag"},{"t":"Lords of Magic","p":["Windows"],"d":"Impressions Games","u":"Sierra On-Line","g":"Turn-based strategy","r":"December 2, 1997","l":"https://en.wikipedia.org/wiki/Lords_of_Magic","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2hjt.jpg","s":"In the fantasy world known as Urak, supporters of eight different religions constantly fight each other. One of them is Balkoth, known as the Lord of Death, who worships the dark deity Golgoth. Balkoth has sworn to destroy all other faiths in the name of his own god. The other lords have to expand their ranks and defend themselves against the mad zealot.\n\nLords of Magic is a strategy game that combines turn-based exploration and resource management with real-time combat. The player can choose to control any of the lords who oppose Balkoth. Each nation (faith) commanded by a lord has its own specific units. Before engaging in an offensive, the player must liberate a Great Temple for the faith of his/her choice. It is also necessary to build a stronghold, develop the nation's capital city, and recruit troops.\n\nThe troops are led by a champion, representing the \"hero\" of the game. This hero can be either a warrior, a thief, or a mage, possessing the classical advantages and disadvantages of these classes: the warrior is good in close combat, the thief can sabotage enemy armies, and the physically weak mage can cast devastating spells. The isometric combat proceeds in real-time, with an option to simply calculate the result of a battle immediately, depending on the participants' statistics."},{"t":"Lose Your Marbles","p":["Windows"],"d":"SegaSoft","u":"SegaSoft","g":"Puzzle","r":"August 19, 1997","l":"https://en.wikipedia.org/wiki/Lose_Your_Marbles"},{"t":"Lurid Land","p":["MS-DOS","Windows"],"d":"Illusion Softworks","u":"Abadion Arts","g":"Puzzle-platform","l":"https://en.wikipedia.org/wiki/Lurid_Land"},{"t":"Mace: The Dark Age","p":["Arcade","Nintendo 64"],"d":"Atari Games","u":"Atari Games, Midway Home Entertainment, GT Interactive Software","g":"Fighting","r":"March 1997","l":"https://en.wikipedia.org/wiki/Mace:_The_Dark_Age","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2ey8.jpg","s":"Mace: The Dark Age is a fighting video game released by Atari for arcade machines in 1997 and ported by Midway to the Nintendo 64 in 1997.\n\nThe game is similar to Bio F.R.E.A.K.S. and the Mortal Kombat series. Like in Mortal Kombat, when a character wins both rounds, they can perform an execution move on the enemy. Methods included severing an opponent's limbs and torso (Al Rashid), beheading (The Executioner), repeated stabbing (Koyasha), impaling the opponent with a sword (Lord Deimos), breaking an opponent's back by hoisting them on top of a Viking helmet and throwing them to the ground, causing their body to explode (Ragnar), and some more far-fetched methods including pulling out an opponent's heart (Xiao Long), shrinking (Namira), transforming the opponent into a chicken (Taria), and entering an opponent's body and bursting them from inside (Dregan).\n\nNote: Heavily borrowing from the arcade game Soul Edge (1995)--first of the Souls Series. Which borrowed heavily from the framework WeaponLord (1995) laid out. Visual Concepts (developers of WeaponLord) would send builds of the game to Namco (the publisher of WeaponLord) to playtest."},{"t":"Machine Hunter","p":["Windows","PlayStation"],"d":"Eurocom Entertainment Software","u":"MGM Interactive","g":"Shoot 'em up","r":"July 1997","l":"https://en.wikipedia.org/wiki/Machine_Hunter"},{"t":"Macross: Do You Remember Love?","p":["Sega Saturn"],"d":"Scarab","u":"Bandai Visual","g":"Shoot 'em up","r":"June 6, 1997","l":"https://en.wikipedia.org/wiki/Macross:_Do_You_Remember_Love%3F_(video_game)"},{"t":"Mad Stalker: Full Metal Forth","p":["FM Towns","PC Engine CD","PlayStation","Sharp X68000"],"d":"Fill-in-Cafe","u":"Family Soft","g":"Beat 'em up","l":"https://en.wikipedia.org/wiki/Mad_Stalker:_Full_Metal_Forth"},{"t":"Madden Football 64","p":["Nintendo 64"],"d":"Tiburon Entertainment","u":"EA Sports","g":"Sports","r":"October 1997","l":"https://en.wikipedia.org/wiki/Madden_Football_64"},{"t":"Madden NFL 98","p":["Sega Saturn","Windows","MS-DOS","PlayStation"],"u":"EA Sports","r":"August 26, 1997","l":"https://en.wikipedia.org/wiki/Madden_NFL_98"},{"t":"MadSpace","p":["MS-DOS"],"d":"Maddox Games","u":"Auric Vision, Nightdive Studios","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/MadSpace"},{"t":"MageSlayer","p":["Windows"],"d":"Raven Software","u":"GT Interactive","g":"Third-person shooter","r":"September 24, 1997","l":"https://en.wikipedia.org/wiki/MageSlayer"},{"t":"Magic Fairy Tales: Barbie as Rapunzel","p":["macOS","Windows"],"d":"Media Station","u":"Mattel Media","g":"Educational, adventure","l":"https://en.wikipedia.org/wiki/Magic_Fairy_Tales:_Barbie_as_Rapunzel"},{"t":"Magic The Gathering: Battlemage","p":["Windows","PlayStation"],"d":"Realtime Associates","u":"Acclaim Entertainment","g":"Real time strategy","l":"https://en.wikipedia.org/wiki/Magic_The_Gathering:_Battlemage"},{"t":"Magic: The Gathering","p":["Windows"],"d":"MicroProse","u":"MicroProse","g":"Digital collectible card game","r":"March 6, 1997","l":"https://en.wikipedia.org/wiki/Magic:_The_Gathering_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2err.jpg","s":"Magic: The Gathering is a computer game published by MicroProse in April 1997 based on the collectible card game Magic: The Gathering.\nThe game takes place in the plane of Shandalar, where the player must travel the land and fight random enemies to gain cards, and defeat five wizards representing the five colors. The player must prevent one color from gaining too much power, and defeat the planeswalker Arzakon, who has a deck of all five colors. Adventure game and role-playing game elements are present, including inventory, gold, towns, dungeons, random battles, and character progression in the form of new abilities and a higher life point total. An oversized version of Aswan Jaguar was included in the game box."},{"t":"Magical Drop III","p":["Arcade","Neo Geo AES","Sega Saturn","PlayStation"],"d":"Data East","u":"Data East, SNK, Swing! Entertainment, Conspiracy Entertainment","g":"Puzzle","r":"February 25, 1997","l":"https://en.wikipedia.org/wiki/Magical_Drop_III"},{"t":"Major Damage","p":["PlayStation","Sega Saturn"],"d":"Capcom Digital Studios","u":"Capcom","g":"Run and gun","l":"https://en.wikipedia.org/wiki/Major_Damage"},{"t":"Malice","p":["MS-DOS","Windows","Linux","macOS","Acorn Archimedes"],"d":"Ratloop","u":"Quantum Axcess, R-Comp International","g":"First-person shooter","r":"November 14, 1997","l":"https://en.wikipedia.org/wiki/Malice_(1997_video_game)"},{"t":"Man of War","p":["MS-DOS","Windows"],"d":"Strategy First","u":"Virgin Interactive Entertainment","l":"https://en.wikipedia.org/wiki/Man_of_War_(video_game)"},{"t":"Marble Drop","p":["Windows"],"d":"Maxis South","u":"Maxis","g":"Puzzle","r":"February 28, 1997","l":"https://en.wikipedia.org/wiki/Marble_Drop"},{"t":"Mario Kart 64","p":["Nintendo 64"],"r":"February 10","l":"https://en.wikipedia.org/wiki/Mario_Kart_64"},{"t":"Mario Teaches Typing 2","p":[],"l":"https://en.wikipedia.org/wiki/Mario_Teaches_Typing_2"},{"t":"Marvel Super Heroes vs. Street Fighter","p":["Arcade"],"d":"Capcom","u":"Capcom, Virgin Interactive Entertainment","g":"Fighting","r":"July 1997","l":"https://en.wikipedia.org/wiki/Marvel_Super_Heroes_vs._Street_Fighter","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co8iho.jpg","s":"Now you can choose your favorite heroes from the worlds of Street Fighter and Marvel Super Heroes to face off in a head-to-head battle for supremacy. Dive into the action to perform outrageous moves and link together amazing Chain Combos... then delight in their devastating results! Marvel Super Heroes vs. Street Fighter combines two incredible universes to create an entirely new legend of heroic proportions."},{"t":"Mass Destruction","p":["Sega Saturn","MS-DOS","PlayStation"],"d":"NMS Software","u":"ASC Games, BMG Interactive","g":"Action","r":"March 27, 1997","l":"https://en.wikipedia.org/wiki/Mass_Destruction_(video_game)"},{"t":"Masters '98: Harukanaru Augusta","p":["Nintendo 64"],"d":"T&E Soft","u":"T&E Soft","g":"Sports","r":"December 26, 1997","l":"https://en.wikipedia.org/wiki/Masters_'98:_Harukanaru_Augusta"},{"t":"Masters of the Elements","p":["macOS","Windows"],"d":"IJsfontein Interactive Media","u":"Bombilla, Van In, VNU Interactive, Tivola","g":"Adventure","r":"November 4, 1997","l":"https://en.wikipedia.org/wiki/Masters_of_the_Elements"},{"t":"Math for the Real World","p":["Windows","macOS"],"g":"Educational","r":"May 20, 1997","l":"https://en.wikipedia.org/wiki/Math_for_the_Real_World"},{"t":"Math Rabbit","p":["Apple II","MS-DOS","Windows","macOS"],"d":"The Learning Company","u":"The Learning Company","g":"Educational video game","l":"https://en.wikipedia.org/wiki/Math_Rabbit"},{"t":"Maximum Force","p":["Arcade","PlayStation","Sega Saturn"],"d":"Mesa Logic, Tantalus Interactive, Perfect Entertainment","u":"Atari Games, SNK, Midway Games, GT Interactive","g":"Light gun shooter","r":"February 1997","l":"https://en.wikipedia.org/wiki/Maximum_Force"},{"t":"MDK","p":["Windows","MS-DOS"],"u":"Playmates Interactive","g":"Action","r":"May 5, 1997","l":"https://en.wikipedia.org/wiki/MDK_(video_game)","i":"images/steam-38450.jpg","s":"ON A GOOD DAY, ONLY 2.5 MILLION PEOPLE WILL DIE. As vast alien mining cities suck the power and minerals from every major metropolis on Earth simultaneously, time is of the essence as millions of civilians are expiring by the second."},{"t":"Meat Puppet","p":["Windows"],"d":"Kronos Digital Entertainment","u":"Playmates Interactive","g":"Action game, puzzle, platformer, shooter","r":"June 17, 1997","l":"https://en.wikipedia.org/wiki/Meat_Puppet_(video_game)"},{"t":"Mega Man 8","p":["PlayStation","Sega Saturn"],"r":"February 28","l":"https://en.wikipedia.org/wiki/Mega_Man_8"},{"t":"Mega Man Legends","p":["PlayStation"],"g":"Shooter, Adventure","r":"December 18","l":"https://en.wikipedia.org/wiki/Mega_Man_Legends_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cob1ls.jpg","s":"THE BLUE BOMBER BLASTS INTO A WHOLE NEW DIMENSION\n\nMega Man blasts his way into the third dimension in an amazing new adventure. Mega Man Legends combines the best of classic Mega Man action with enormous bosses, a riveting storyline and all the depth of the hottest RPG.\n\nExplore vast 3-D worlds in your quest to find the treasure of all treasures, the Mother Lode. You'll love the new 3-D graphics, deadly weapons and non-stop action... unless of course, you're a boss.\n\n* Awesome Weapons!\n* Diabolical Bosses!\n* Legendary Gameplay!\n* Non-Stop 3-D Action!"},{"t":"Mega Man X4","p":["PlayStation","Sega Saturn"],"g":"Shooter, Platform","r":"August 1","l":"https://en.wikipedia.org/wiki/Mega_Man_X4","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coar91.jpg","s":"Mega Man X4, known as Rockman X4 in Japan, is the fourth game from the Mega Man X series. It was the second game in the series to be released on the Sega Saturn and Sony PlayStation (although it is the first original game; Mega Man X3 was ported to the systems), released in 1997 (and also re-released onto PlayStation as part of its greatest hits in 2002). It was later ported to the PC in 1998 and then re-released as part of the Mega Man X Collection"},{"t":"Mega Man: Battle & Chase","p":["PlayStation"],"d":"Capcom","u":"Capcom, Infogrames","g":"Racing","r":"March 20, 1997","l":"https://en.wikipedia.org/wiki/Mega_Man:_Battle_&_Chase"},{"t":"Men in Black: The Game","p":["Windows"],"d":"Gigawatt Studios, The Collective","u":"SouthPeak Interactive, Gremlin Interactive","g":"Survival horror","r":"November 18, 1997","l":"https://en.wikipedia.org/wiki/Men_in_Black:_The_Game"},{"t":"Micro Machines V3","p":["PlayStation"],"d":"Codemasters, Novalicious","u":"Codemasters, Midway, THQ","g":"Racing","r":"March 21, 1997","l":"https://en.wikipedia.org/wiki/Micro_Machines_V3","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co6psc.jpg","s":"Micro Machines V3 takes the immensely popular miniature-scale racing series to a new level by adding weapons and power-ups to the fray. Now you can grab turbo charges for bursts of speed or blast away opponents with grenades and force-fields. For the first time on a portable system you can still drive all of your favorite Micro Machines vehicles on all the classic tracks such as the pool tale and sand-box, but now you can do it with an attitude! Features 48 courses - breakfast table, school desk, science lab, beach, restaurant, garden, pool table, etc. Power-ups to blitz the opposition include: hammer, mines, force-field, etc. Collect, test and gamble special prize cars for up to 32 vehicles -- including monster trucks, transmutable cars, futuristic cars which are all faster than before."},{"t":"Microsoft Entertainment Pack: The Puzzle Collection","p":["Windows"],"d":"Mir - Dialogue","u":"Microsoft Games, Swing! Entertainment, Conspiracy Entertainment","g":"Puzzle","r":"July 31, 1997","l":"https://en.wikipedia.org/wiki/Microsoft_Entertainment_Pack:_The_Puzzle_Collection"},{"t":"Microsoft Flight Simulator 98","p":["Windows"],"d":"Microsoft","u":"Microsoft","g":"Flight simulation","r":"September 17, 1997","l":"https://en.wikipedia.org/wiki/Microsoft_Flight_Simulator_98"},{"t":"Mini 4WD GB Let's & Go!","p":[],"l":"https://en.wikipedia.org/wiki/Mini_4WD_GB_Let's_&_Go!"},{"t":"Mischief Makers","p":["Nintendo 64"],"d":"Treasure","u":"Enix, Nintendo","g":"Platform","r":"June 27, 1997","l":"https://en.wikipedia.org/wiki/Mischief_Makers","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cobyes.jpg","s":"Mischief Makers is a Single-Player Video Game for the Nintendo 64 that was released in the United States on October 1st, 1997. The protagonist is the Ultra-Intergalactic-Cybot G, Marina Liteyears. She must protect the clumsy and lighthearted Professor Theo from the evil emperor. While visiting Planet Clancer, the Professor is suddenly kidnapped by the empire, and thus starts our game. The player must travel to different worlds and utilize widely innovative and different modes of gameplay to save the professor. To get 100% completion one must collect a golden gem in each stage and achieve super fast completion ranks."},{"t":"Mission: T.H.I.N.K.","p":["Windows","macOS"],"d":"The Learning Company","u":"The Learning Company","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Mission:_T.H.I.N.K."},{"t":"MLB '98","p":["PlayStation"],"d":"Sony Interactive Studios America","u":"Sony Computer Entertainment","g":"Sports","r":"August 1997","l":"https://en.wikipedia.org/wiki/MLB_'98"},{"t":"Mobile Suit Gundam Side Story III: Sabakareshi Mono","p":["Sega Saturn"],"d":"Bandai","u":"Bandai","g":"Vehicle simulation game","l":"https://en.wikipedia.org/wiki/Mobile_Suit_Gundam_Side_Story_III:_Sabakareshi_Mono"},{"t":"Money Puzzle Exchanger","p":["Arcade","Game Boy"],"d":"Face","u":"Face, Athena, GMF","g":"Puzzle","r":"January 17, 1997","l":"https://en.wikipedia.org/wiki/Money_Puzzle_Exchanger","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cob0q9.jpg","s":"A puzzle game created in 1997 by Japanese game for the Neo Geo MVS arcade system and ported to the Game Boy and the PlayStation that same year."},{"t":"Monopoly","p":["PlayStation"],"d":"Gremlin Interactive","u":"Hasbro Interactive","g":"Strategy, board game","r":"October 31, 1997","l":"https://en.wikipedia.org/wiki/Monopoly_(1997_video_game)"},{"t":"Monopoly Star Wars","p":["Windows"],"d":"Artech Studios","u":"Hasbro Interactive","g":"Strategy, board game","r":"October 21, 1997","l":"https://en.wikipedia.org/wiki/Monopoly_Star_Wars"},{"t":"Monster Rancher","p":["PlayStation"],"d":"Tecmo, Koei Tecmo","u":"Tecmo, Koei Tecmo","g":"Life simulation game","r":"July 24, 1997","l":"https://en.wikipedia.org/wiki/Monster_Rancher_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5xuq.jpg","s":"Monster Rancher is a console game released in 1997 for the PlayStation system. It is the first game in Tecmo's Monster Rancher series, featuring the raising, fighting, and breeding of monsters."},{"t":"Montezuma's Return!","p":["Windows"],"d":"Utopia Technologies, Tarantula Studios","u":"WizardWorks, Take-Two Interactive","g":"Action-adventure","r":"December 1997","l":"https://en.wikipedia.org/wiki/Montezuma's_Return!"},{"t":"Monty Python's The Meaning of Life","p":["Windows"],"d":"7th Level","u":"Take-Two Interactive, Panasonic Interactive Media","g":"Adventure","r":"December 1997","l":"https://en.wikipedia.org/wiki/Monty_Python's_The_Meaning_of_Life_(video_game)"},{"t":"Moon Child","p":["Windows","macOS"],"d":"The Games Department","u":"Valkieser Publishing, Klaar Mobile Entertainment","g":"Side-scrolling, platformer","r":"October 4, 1997","l":"https://en.wikipedia.org/wiki/Moon_Child_(video_game)"},{"t":"Moon: Remix RPG Adventure","p":["PlayStation"],"d":"Love-de-Lic","u":"ASCII Entertainment, Onion Games","g":"Role-playing, adventure","r":"October 16, 1997","l":"https://en.wikipedia.org/wiki/Moon:_Remix_RPG_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5ycb.jpg","s":"In this \"anti-RPG\" adventure game notable for parodying and subverting common JRPG conventions, you level up by loving, not fighting. Revive dead animals and bond with everyone around you to obtain the most important thing in the universe — love."},{"t":"Moonlight Syndrome","p":["PlayStation"],"d":"Human Entertainment","u":"Human Entertainment","g":"Adventure","r":"October 9, 1997","l":"https://en.wikipedia.org/wiki/Moonlight_Syndrome"},{"t":"Mortal Kombat 4","p":["Nintendo 64","Arcade"],"g":"Fighting","r":"October 15","l":"https://en.wikipedia.org/wiki/Mortal_Kombat_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co53gp.jpg","s":"Mortal Kombat 4 is 1 vs 1 fighting game, similar to the other Mortal Kombat games, but this is first game in series with 3D characters models. The player can choose from 15 different fighters at the start (and several unlockables later on). Many fighters from earlier games in the series make a comeback (like Scorpion, Sub Zero, Liu Kang, Sonya Blade, Johnny Cage etc.) while other new fighters join in, like Shinook (who is the main evil character in this game), Fujin, Jarek, and Kai. Goro returns as a boss."},{"t":"Mortal Kombat Mythologies: Sub-Zero","p":["Nintendo 64"],"g":"Fighting, Platform, Hack and slash/Beat 'em up","r":"December 31","l":"https://www.igdb.com/games/mortal-kombat-mythologies-sub-zero","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1y23.jpg","s":"Mortal Kombat Mythologies: Sub-Zero is a story-driven fighting game that casts you in the shoes of Sub-Zero, and chronicles a series of events that occurred prior to Mortal Kombat 1. It is the first Mortal Kombat game to feature side-scrolling gameplay.\n\nGameplay wise the game takes the Mortal Kombat familiar 2D fighting environment and turns it into a hybrid fighter/platformer game, where you must travel trough hazardous levels running and jumping around as well as fighting your way against both digitized and polygonal enemies. Sub-Zero's interface is the same as in every MK game, with the addition of a \"use\" and \"turn around\" buttons and additions such as an inventory, and a slight RPG twist in which you get exp. for defeating opponents, which translates into new techniques and moves to execute in the game."},{"t":"Mortalus: The Quest for Immortality","p":["Windows","macOS"],"d":"Hoffman & Associates Entertainment","u":"Hoffman & Associates Entertainment","g":"Adventure","l":"https://en.wikipedia.org/wiki/Mortalus:_The_Quest_for_Immortality"},{"t":"Moto Racer","p":["Windows","PlayStation"],"d":"Delphine Software International","u":"Electronic Arts","g":"Racing","r":"August 1, 1997","l":"https://en.wikipedia.org/wiki/Moto_Racer","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co8a4j.jpg","s":"Moto Racer is an arcade style motorcycle racing game developed by Delphine Software International and published by Electronic Arts for Microsoft Windows and PlayStation. It features both dirt and street bikes, and a variety of tracks."},{"t":"Motor Mash","p":["PlayStation"],"d":"Eutechnyx","u":"Ocean Software, Infogrames","g":"Racing","r":"November 1997","l":"https://en.wikipedia.org/wiki/Motor_Mash"},{"t":"Motor Raid","p":["Arcade"],"d":"AM1","u":"Sega","g":"Racing","r":"October 1997","l":"https://en.wikipedia.org/wiki/Motor_Raid"},{"t":"MRC: Multi-Racing Championship","p":["Nintendo 64"],"d":"Genki","u":"Imagineer, Ocean","g":"Racing","r":"July 18, 1997","l":"https://en.wikipedia.org/wiki/MRC:_Multi-Racing_Championship"},{"t":"Muppet Kids","p":[],"l":"https://en.wikipedia.org/wiki/Muppet_Kids"},{"t":"Muzzle Velocity","p":["MS-DOS"],"d":"Code Fusion","u":"Digi4fun","g":"Strategy","l":"https://en.wikipedia.org/wiki/Muzzle_Velocity_(video_game)"},{"t":"Mysteriet på Greveholm","p":[],"l":"https://en.wikipedia.org/wiki/Mysteriet_p%C3%A5_Greveholm"},{"t":"Mystical Ninja Starring Goemon","p":["Nintendo 64"],"d":"Konami Computer Entertainment Osaka","u":"Konami","g":"Action-adventure","r":"August 7, 1997","l":"https://en.wikipedia.org/wiki/Mystical_Ninja_Starring_Goemon","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co56g4.jpg","s":"The story follows Goemon's struggles to prevent the Peach Mountain Shoguns gang from turning Japan into a Westernized fine arts theater. The plot calls for three cinematic musical features and battles between giant robots; like other Ganbare Goemon games, it is peppered with surrealist humor and anachronisms.\n\nThe protagonist of Mystical Ninja is Goemon, a hot-blooded, kiseru-wielding ninja with blue, bushy hair based loosely on the legendary thief Ishikawa Goemon. The lord of Oedo asks him to find those who maimed Oedo Castle. Goemon lives in Oedo Town and is friends with Ebisumaru, a strange, gluttonous fat man who wears a blue bandana. Ebisumaru is defined as lazy and perverted. Their kunai-throwing friend Sasuke is a mechanical ninja (made by the Wise Man of Iga) who enjoys hot baths and Japanese tea. Rounding out the heroes is Yae, a fierce sword-wielding kunoichi, who happens upon Goemon's band in Zazen Town. The villains of the game hail from the organization Peach Mountain Shoguns and include a gang of four \"weirdos\" led by Spring Breeze Dancin' (Danshin Harukaze) and Kitty Lily (Margaret Ranko). They intend to transform Japan into a stage for their talents."},{"t":"Mystical Ninja Starring Goemon","p":["Game Boy"],"d":"Konami Computer Entertainment Nagoya","u":"Konami","g":"Action-adventure","r":"December 4, 1997","l":"https://en.wikipedia.org/wiki/Mystical_Ninja_Starring_Goemon_(Game_Boy_video_game)"},{"t":"Myth: The Fallen Lords","p":["Windows","MS-DOS"],"u":"Bungie","g":"Real Time Strategy (RTS), Role-playing (RPG), Strategy","r":"November 7, 1997","l":"https://www.igdb.com/games/myth-the-fallen-lords","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co29oa.jpg","s":"A real-time tactical game from Bungie Studios, Myth: The Fallen Lords is set in a gothic fantasy realm where the nations of men are in danger of being eradicated. With limited numbers and dwindling odds, players must overcome the impossible to defeat Balor and the powerful Fallen Lords."},{"t":"Nagano Winter Olympics '98","p":["PlayStation","Nintendo 64"],"d":"Konami Computer Entertainment Osaka, Konami Computer Entertainment Tokyo","u":"Konami","g":"Sports","r":"December 18, 1997","l":"https://en.wikipedia.org/wiki/Nagano_Winter_Olympics_'98","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co39vf.jpg","s":"The Nagano Winter Olympic Games are here! Experience all of the thrills, spills and \"chills\" as you compete for glory against the rest of the world. It's time to find out what you're made of...Can you bring home a medal? 12 exciting Olympic events! 16 different countries! 1-4 player action. Set new world records and save them to your Controller Pak. Real-time motion captured athletes."},{"t":"Nanatsu Kaze no Shima Monogatari","p":["Sega Saturn"],"d":"Givro Corporation","u":"Enix","g":"Graphic adventure","r":"November 27, 1997","l":"https://en.wikipedia.org/wiki/Nanatsu_Kaze_no_Shima_Monogatari"},{"t":"NanoTek Warrior","p":["PlayStation"],"d":"Tetragon Inc.","u":"Virgin Interactive Entertainment","g":"Tube shooter","r":"February 28, 1997","l":"https://en.wikipedia.org/wiki/NanoTek_Warrior"},{"t":"NASCAR 98","p":["PlayStation","Sega Saturn"],"d":"Stormfront Studios, High Score Entertainment","u":"EA Sports","g":"Sim racing","r":"September 24, 1997","l":"https://en.wikipedia.org/wiki/NASCAR_98"},{"t":"NBA Fastbreak '98","p":["Windows","Sega Saturn","PlayStation"],"d":"Visual Concepts","u":"Midway Games, GT Interactive, Sega","g":"Sports simulation","r":"October 28, 1997","l":"https://en.wikipedia.org/wiki/NBA_Fastbreak_'98"},{"t":"NBA Live 98","p":["Windows","PlayStation","Sega Saturn","Genesis / Mega Drive"],"d":"EA Canada, Tiertex, Realtime Associates","u":"EA Sports, THQ","g":"Sports","r":"October 28, 1997","l":"https://en.wikipedia.org/wiki/NBA_Live_98","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5z3l.jpg","s":"NBA Live 98 is a basketball video game based on the NBA and the fourth installment of the NBA Live series. The cover features Tim Hardaway of the Miami Heat. The game was developed by EA Sports and released on November 30, 1997 for the PlayStation, October 31, 1997 for the PC and December 31, 1997 for the Sega Saturn. It was the final version of NBA Live released for the Super NES, Genesis and Sega Saturn."},{"t":"NBA ShootOut '97","p":["PlayStation"],"d":"Sony Computer Entertainment Europe","u":"Sony Computer Entertainment","g":"Sports","r":"March 11, 1997","l":"https://en.wikipedia.org/wiki/NBA_ShootOut_'97"},{"t":"NCAA Basketball: Final Four 97","p":["Windows","PlayStation"],"d":"High Voltage Software","u":"Mindscape Sports Advantage","g":"Basketball","l":"https://en.wikipedia.org/wiki/NCAA_Basketball:_Final_Four_97"},{"t":"NCAA Football '98","p":["PlayStation","Windows"],"d":"EA Tiburon","u":"Electronic Arts","g":"Sports, American football","r":"August 5, 1997","l":"https://en.wikipedia.org/wiki/NCAA_Football_'98"},{"t":"NCAA Gamebreaker 98","p":["PlayStation"],"d":"Sony Interactive Studios America","u":"Sony Computer Entertainment","g":"Sports video game","r":"November 21, 1997","l":"https://en.wikipedia.org/wiki/NCAA_Gamebreaker_98"},{"t":"Need for Speed II","p":["Windows","MS-DOS","PlayStation"],"g":"Racing, Simulator","r":"March 31","l":"https://en.wikipedia.org/wiki/Need_for_Speed_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coaudb.jpg","s":"There are three main game types. The first two are single race and tournament and the last is a knockout race. Single races allow players to become familiar with the circuits and increase their skill of any one of the six tracks. The six tracks are called Mediterranean, Mystic Peaks, Proving Grounds, Outback, North Country, and Pacific Spirit."},{"t":"Need for Speed: V-Rally","p":["PlayStation"],"d":"Infogrames","u":"Electronic Arts, Infogrames","g":"Racing, Simulator, Sport","r":"September 30, 1997","l":"https://www.igdb.com/games/need-for-speed-v-rally","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2095.jpg","s":"V-Rally is a rally racing game initially developed by Eden Studios for the PlayStation.\n\nV-Rally was first released in Europe as V-Rally: 97 Championship Edition. Although the game has no connection to Electronic Arts' Need for Speed series, it was later published in North America by Electronic Arts under the title Need for Speed: V-Rally. Later ported to PC, N64, Game Boy, and Game Boy Color.\n\nIt features 11 official rally cars and more than 40 courses with dynamic weather, terrain, and time-of-day variations. Players can fine-tune vehicle settings such as suspension, gear ratios, and steering before competing across three main modes: Arcade, Championship, and Time Trial. In Arcade mode, players advance through competitions grouped by difficulty, each consisting of four stages. Championship mode presents an eight-race tournament with points awarded for top-three finishes, while Time Trial mode focuses on racing against the clock or another vehicle for the fastest time."},{"t":"Neo Bomberman","p":["Arcade"],"d":"Produce!","u":"Hudson Soft","g":"Action, maze","r":"May 1, 1997","l":"https://en.wikipedia.org/wiki/Neo_Bomberman","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co6pen.jpg","s":"The gameplay consists of walking through maze-like areas filled with monsters with a goal of opening the gate leading to the next area. Playing as a bomberman, the player can lay bombs to destroy all of the monsters, which will subsequently open the gate. Destroying blocks in the maze may uncover useful items including remote control bombs, accelerators, hearts, and increased firing range. Neo Bomberman includes Bosses that appear after each zone. Each zone is harder than the last, some featuring new traps and level obstacles such as conveyor belts."},{"t":"Neon Genesis Evangelion: Girlfriend of Steel","p":["Windows","macOS"],"d":"Gainax Network Systems","u":"Gainax, Sega, CyberFront","g":"Visual novel","l":"https://en.wikipedia.org/wiki/Neon_Genesis_Evangelion:_Girlfriend_of_Steel"},{"t":"NetStorm: Islands At War","p":["Windows"],"d":"Titanic Entertainment","u":"Activision","g":"Real-time strategy","r":"November 13, 1997","l":"https://en.wikipedia.org/wiki/NetStorm:_Islands_At_War"},{"t":"NetWAR","p":["Windows"],"d":"Semi Logic","u":"Headland Digital Media","g":"Shooter video game","r":"October 1997","l":"https://en.wikipedia.org/wiki/NetWAR"},{"t":"NFL '98","p":["Genesis / Mega Drive"],"d":"Spectacular Games, FarSight Technologies","u":"Sega","g":"Sports","l":"https://en.wikipedia.org/wiki/NFL_'98"},{"t":"NFL GameDay 98","p":["PlayStation"],"u":"Sony Computer Entertainment","r":"September 4, 1997","l":"https://en.wikipedia.org/wiki/NFL_GameDay_98"},{"t":"NFL Quarterback Club 98","p":["Nintendo 64"],"d":"Iguana Entertainment","u":"Acclaim Entertainment","g":"Sports, American football","r":"October 24, 1997","l":"https://en.wikipedia.org/wiki/NFL_Quarterback_Club_98"},{"t":"NHL 98","p":["Super Nintendo Entertainment System","Windows","PlayStation","Genesis / Mega Drive"],"d":"EA Canada, Electronic Arts, MBL Research","u":"EA Sports, THQ","g":"Sports","r":"September 24, 1997","l":"https://en.wikipedia.org/wiki/NHL_98","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2gux.jpg","s":"NHL 98 features much faster and refined gameplay (now using four action keys instead of two, removing the need to double-tap to perform some actions), along other new features such as \"in-the-fly\" tactics developed by Marc Crawford, then manager of the Colorado Avalanche and new commentary lines from Jim Hughson and Darryl Reaugh and a re-worked interface.\nGraphics are improved from the previous version with the players being less angular, and thanks to 3Dfx support, with less pixels showing in the textures. The in-game presentation follows a TV-style script, zooming in players while displaying stats during clock stoppages.\n\nAs far as game modes go, in the year of the first Olympic Tournament with professional players, NHL 98 introduced the first real international competition, with 18 International teams to choose from. Other game modes include Season (option to pick between 25 or 82 games) and Playoff (best of 1, 3, 5 or 7 matches) and a Penalty Shootout mode."},{"t":"NHL Breakaway 98","p":["PlayStation"],"d":"Sculptured Software","u":"Acclaim Entertainment","g":"Sports","r":"September 10, 1997","l":"https://en.wikipedia.org/wiki/NHL_Breakaway_98"},{"t":"NHL FaceOff 98","p":["PlayStation"],"d":"Killer Game","u":"Sony Computer Entertainment","g":"Sports video game","r":"October 31, 1997","l":"https://en.wikipedia.org/wiki/NHL_FaceOff_98"},{"t":"NHL Powerplay 98","p":["Windows","PlayStation","Sega Saturn"],"d":"Radical Entertainment","u":"Virgin Interactive, Sega","g":"Sports","r":"October 9, 1997","l":"https://en.wikipedia.org/wiki/NHL_Powerplay_98"},{"t":"Nightmare Creatures","p":["PlayStation","Windows"],"d":"Kalisto Entertainment","u":"Activision, Sony Computer Entertainment Europe, Gameloft","g":"Survival horror","r":"October 31, 1997","l":"https://en.wikipedia.org/wiki/Nightmare_Creatures","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5j7q.jpg","s":"The story behind Nightmare Creatures draws upon gothic horror elements of the 19th century. The story begins in 1666, when a devil-worshipping cult called the Brotherhood of Hecate were conducting sinister experiments in London so as to take over the city and then the world. The Brotherhood tried to develop an elixir that would endow them with superhuman powers. However, rather than creating their intended superhumans, their experiments created only grotesque monsters. When they decided to use these creatures as an army of conquest, one of their number, Samuel Pepys, set their headquarters on fire, resulting in the First Great Fire of London. The game takes place in 1834 when London falls victim to several evil occurrences. Monster sightings are reported along with news of people mutating into ungodly creatures, and that the dead are waking from their graves and walking amongst the living. All of London is in a panic and vulnerable to the schemes of Adam Crowley, a mad scientist and occultist enlisting the help of the Brotherhood."},{"t":"Nightmare Ned","p":["Windows"],"d":"Creative Capers Entertainment, Window Painters Ltd","u":"Disney Interactive","g":"Action-adventure, Sidescroller","r":"October 7, 1997","l":"https://en.wikipedia.org/wiki/Nightmare_Ned"},{"t":"Nile: An Ancient Egyptian Quest","p":["Windows"],"d":"Stone House Productions","u":"Simon & Schuster Interactive","g":"Point-and-click adventure game, edutainment","l":"https://en.wikipedia.org/wiki/Nile:_An_Ancient_Egyptian_Quest"},{"t":"Nissan Presents: Over Drivin' Skyline Memorial","p":[],"l":"https://en.wikipedia.org/wiki/Nissan_Presents:_Over_Drivin'_Skyline_Memorial"},{"t":"Nitro Racers","p":["MS-DOS"],"d":"Torc Interactive","u":"Studio 3DO","g":"Racing","l":"https://en.wikipedia.org/wiki/Nitro_Racers"},{"t":"Nuclear Strike","p":["PlayStation","Windows"],"d":"Electronic Arts, Tiburon Entertainment, Pacific Coast Power & Light","u":"Electronic Arts, THQ","g":"Shooter","r":"September 24, 1997","l":"https://en.wikipedia.org/wiki/Nuclear_Strike","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2qv5.jpg","s":"Nuclear Strike is a shooter video game developed and published by Electronic Arts for the PlayStation in 1997. The game is the sequel to Soviet Strike and the fifth instalment in the Strike series, which began with Desert Strike on the Sega Genesis. The Soviet Strike development team also created Nuclear Strike. EA released a PC port the same year; THQ developed and in 1999 published a Nintendo 64 version called Nuclear Strike 64.\n\nNuclear Strike is a helicopter-based game, with strategy elements added to the action gameplay. The plot concerns an elite special force - the player's allies - pursuing a nuclear-armed rogue spy through a fictionalised Asian setting. It retained the earlier game's engine but added several modifications to improve graphical performance and make the game more accessible. The game features 15 playable vehicles, a large increase from previous games. In addition to the main fictionalised Apache, there are secondary helicopters, jets, armour and a hovercraft. The player also commands ground troops in occasional real-time strategy sections.\n\nThe game received positive, negative and mixed reviews. Critics noted a weak storyline, though GameSpot dismissed this is as unimportant in an action game. GameSpot called the graphics - which made use of specialised hardware such as 3Dfx Voodoo video cards and the N64 Expansion Pak - \"about as good as it gets\", while Allgame said they are \"decent\" and Daily Radar called them \"horrible\". Critics praised the full motion video as well as the music and sound effects. Reviewers enjoyed the straightforward gameplay but several complained of a close similarity to its predecessor Soviet Strike and questioned the game's value as a result."},{"t":"Obsidian","p":["Windows","macOS"],"d":"Rocket Science Games","u":"SegaSoft","g":"Adventure","r":"January 10, 1997","l":"https://en.wikipedia.org/wiki/Obsidian_(1997_video_game)"},{"t":"Oddworld: Abe's Oddysee","p":["PlayStation","Windows","MS-DOS"],"u":"GT Interactive","g":"Adventure","r":"September 18, 1997","l":"https://store.steampowered.com/app/15700","i":"images/steam-15700.jpg","s":"Selected by the fickle finger of fate, Abe™, floor-waxer first class for RuptureFarms, was catapulted into a life of adventure when he overheard plans by his boss, Molluck the Glukkon™, to turn Abe and his fellow Mudokons into Tasty Treats as part of a last-ditch effort to rescue Molluck's failing meat-packing empire."},{"t":"Off Road Challenge","p":["Arcade"],"d":"Midway Studios San Diego, Avalanche Software","u":"Midway, GT Interactive","g":"Racing","r":"September 1997","l":"https://en.wikipedia.org/wiki/Off_Road_Challenge"},{"t":"One","p":["PlayStation"],"r":"November 30","l":"https://en.wikipedia.org/wiki/One_(video_game)"},{"t":"OnEscapee","p":["Amiga"],"d":"Invictus Games","u":"Sadeness Software, IntuitiveComputers","g":"Action-adventure","l":"https://en.wikipedia.org/wiki/OnEscapee"},{"t":"Orly's Draw-A-Story","p":["Windows","macOS"],"d":"ToeJam & Earl Productions","u":"Broderbund","g":"Activity, Design","l":"https://en.wikipedia.org/wiki/Orly's_Draw-A-Story"},{"t":"Outlaws","p":["Windows","MS-DOS"],"g":"Shooter","r":"April 7","l":"https://en.wikipedia.org/wiki/Outlaws_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4zdx.jpg","s":"Outlaws is a first-person shooter released by LucasArts in 1997. It uses a Wild West setting. It follows retired U.S. Marshal James Anderson, who seeks to bring justice to a gang of criminals who killed his wife and kidnapped his daughter.\nThe game is a first-person shooter. Players control the character as he utilizes several American Old West weapons and items, such as a rifle, shotgun, dynamite and revolver. The player can activate the lantern inventory item to lighten dark areas, and use a shovel in specific areas to dig holes."},{"t":"Outpost 2: Divided Destiny","p":["Windows"],"d":"Dynamix","u":"Sierra On-Line","g":"Real-time strategy","r":"August 18, 1997","l":"https://en.wikipedia.org/wiki/Outpost_2:_Divided_Destiny"},{"t":"Oystron","p":["Atari 2600"],"d":"Piero Cavina","u":"XYPE","g":"Action","l":"https://en.wikipedia.org/wiki/Oystron"},{"t":"Pacific General","p":["MS-DOS","Windows"],"d":"Strategic Simulations","u":"Strategic Simulations","g":"Computer wargame, turn-based strategy","r":"July 16, 1997","l":"https://en.wikipedia.org/wiki/Pacific_General"},{"t":"Pandemonium 2","p":["PlayStation","Windows"],"d":"Crystal Dynamics","u":"Midway Games, Crystal Dynamics, Ubi Soft","g":"Platform","r":"October 23, 1997","l":"https://en.wikipedia.org/wiki/Pandemonium_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1y7e.jpg","s":"When the magic-infused \"Comet of Infinite Possibilities\" is about to pass over Lyr for the first time in 300 years, Sorceress Nikki decides that stealing the source of its magic is a quicker way to reach power than study. But the evil Goon Queen Zorrscha has her sights set on the comet as well. Nikki and Fargus, a pyromaniac court jester with his own special abilities, race the queen for the goal."},{"t":"Panzer Bandit","p":["PlayStation"],"d":"Fill-in-Cafe","u":"Banpresto","g":"Beat 'em up","r":"August 7, 1997","l":"https://en.wikipedia.org/wiki/Panzer_Bandit"},{"t":"Panzer General 2","p":["Windows"],"d":"SSI (Strategic Simulations, Inc.)","u":"SSI (Strategic Simulations, Inc.)","g":"Strategy, Turn-based strategy (TBS)","r":"December 31, 1997","l":"https://www.igdb.com/games/panzer-general-2","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/q5uy57my6cjuowdfgtp3.jpg","s":"Will you fight as a Wehrmacht Officer, or perhaps lead your comrades in the Soviet Army? You may want to hit the beaches at Salerno and Normandy as an American or British General. No matter what path you choose, you will need all your skills to triumph. The successful Panzer General devises sound strategic plans, and carries them out with unswerving commitment. Generals who are indecisive inevitably fail. Can you forge a battle-winning command and conquer your foes? Isn't it time to find out?"},{"t":"Panzer General II","p":["Windows","MS-DOS"],"r":"September 30","l":"https://en.wikipedia.org/wiki/Panzer_General_II"},{"t":"Parkan: The Imperial Chronicles","p":["Windows"],"d":"Nikita","u":"Nikita","r":"September 1, 1997","l":"https://en.wikipedia.org/wiki/Parkan:_The_Imperial_Chronicles"},{"t":"Paro Wars","p":["PlayStation"],"d":"Konami Computer Entertainment Tokyo","u":"Konami","g":"Turn-based strategy","r":"September 25, 1997","l":"https://en.wikipedia.org/wiki/Paro_Wars"},{"t":"Pax Corpus","p":["PlayStation","Windows"],"d":"Cryo Interactive Entertainment","u":"Cryo Interactive Entertainment, Electronic Arts","g":"Action","l":"https://en.wikipedia.org/wiki/Pax_Corpus"},{"t":"Pax Imperia: Eminent Domain","p":["Windows"],"d":"Heliotrope Studios","u":"Atari, THQ","g":"4X, RTS","r":"November 3, 1997","l":"https://en.wikipedia.org/wiki/Pax_Imperia:_Eminent_Domain"},{"t":"PC Fútbol 5.0","p":["Windows","MS-DOS"],"d":"Dinamic Multimedia","g":"Sports manager","r":"January 4, 1997","l":"https://en.wikipedia.org/wiki/PC_F%C3%BAtbol_5.0"},{"t":"Peak Performance","p":["PlayStation"],"d":"Cave","u":"Atlus, JVC Music Europe","g":"Racing","r":"January 24, 1997","l":"https://en.wikipedia.org/wiki/Peak_Performance_(video_game)"},{"t":"Perfect Assassin","p":["MS-DOS","PlayStation"],"d":"Synthetic Dimensions","u":"Grolier Interactive","g":"Point and click adventure","l":"https://en.wikipedia.org/wiki/Perfect_Assassin"},{"t":"Pet in TV","p":["PlayStation"],"d":"MuuMuu","u":"Sony Computer Entertainment","g":"Digital pet","r":"May 23, 1997","l":"https://en.wikipedia.org/wiki/Pet_in_TV"},{"t":"Pete Sampras Tennis '97","p":["Windows","MS-DOS","PlayStation"],"d":"Codemasters","u":"Codemasters","g":"Sports","l":"https://en.wikipedia.org/wiki/Pete_Sampras_Tennis_'97"},{"t":"PGA Tour 98","p":["PlayStation"],"d":"NuFX","u":"EA Sports","g":"Sports","r":"September 29, 1997","l":"https://en.wikipedia.org/wiki/PGA_Tour_98"},{"t":"Phantasmagoria of Dim. Dream","p":[],"l":"https://en.wikipedia.org/wiki/Phantasmagoria_of_Dim._Dream"},{"t":"Pikiinya!","p":["Super Nintendo Entertainment System"],"d":"Crea-Tech","u":"ASCII","g":"Puzzle","r":"January 31, 1997","l":"https://en.wikipedia.org/wiki/Pikiinya!"},{"t":"Pilgrim: Faith as a Weapon","p":["Windows"],"d":"Arxel Tribe","u":"Infogrames Multimedia","g":"Adventure, educational","r":"November 1997","l":"https://en.wikipedia.org/wiki/Pilgrim:_Faith_as_a_Weapon"},{"t":"Pilot Brothers","p":["Windows","Windows Phone"],"d":"Gamos","u":"G5 Entertainment, 1C Company","g":"Adventure","r":"September 22, 1997","l":"https://www.igdb.com/games/pilot-brothers","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3vbd.jpg","s":"The case of the stolen elephant!\nElephant... Rare... Striped.\n...has been kept for many years by an animal trader named Karbophos.\nBeing unable to overcome abuse, it escaped and found a home at the zoo in our city.\nThis is definitely Karbophos's work.\nTo the zoo!"},{"t":"Pirates: Captain's Quest","p":["macOS","Windows"],"d":"ImageBuilder Software","u":"Discovery Channel Multimedia","g":"Educational, adventure","r":"April 1997","l":"https://en.wikipedia.org/wiki/Pirates:_Captain's_Quest"},{"t":"Planet Blupi","p":["Windows"],"d":"Epistec","u":"Epistec, Telegames","g":"Strategy","l":"https://en.wikipedia.org/wiki/Planet_Blupi"},{"t":"Pocket Bomberman","p":["Game Boy"],"d":"Hudson Soft","u":"Hudson Soft, Nintendo","g":"Platform game","r":"December 12, 1997","l":"https://en.wikipedia.org/wiki/Pocket_Bomberman","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co52x7.jpg","s":"Everyone is familiar with explosive hurling hero 'Bomberman' but this time he's back in a side-view platforming adventure on the Game Boy and Game Boy Color. Use your bombs to blast your way through each stage and overcome the boss battles at the end of each zone to reach your ultimate goal."},{"t":"POD","p":["Windows"],"d":"Ubi Soft","u":"Ubi Soft","g":"Racing","r":"March 28, 1997","l":"https://en.wikipedia.org/wiki/POD_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co885m.jpg","s":"POD is a Futuristic Racing by Ubisoft in 1997. It was designed with the Intel MMX processors in mind and was included as a box set on many computers. A retail version called pod 2.0 was also released with support for 3Dfx voodoo, S3 virge and ATI"},{"t":"Pop'n Bounce","p":["Arcade"],"d":"Video System","u":"Visco","g":"Block breaker","l":"https://en.wikipedia.org/wiki/Pop'n_Bounce"},{"t":"Porsche Challenge","p":["PlayStation"],"d":"Sony Computer Entertainment Europe","u":"Sony Computer Entertainment","g":"Racing","r":"April 11, 1997","l":"https://en.wikipedia.org/wiki/Porsche_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2f7a.jpg","s":"Open-road racing in its purest form. Designed exclusively with Porsche, and modeled to their exact specifications. Everything you need to test your instincts for the open road. 4 racing environments (USA, Japan, Stuttgart, Alpine) with over 20 track combinations. Even race at Stuttgart -Porsche's official test track."},{"t":"Postal","p":["Windows","MS-DOS"],"g":"Shooter, Indie","r":"September 24","l":"https://en.wikipedia.org/wiki/Postal_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co7yfg.jpg","s":"Welcome to Paradise… Arizona. They’re out to get you. Or are they? It doesn’t matter. You don’t have time to think, only time to kill.\n\nBlast, maim and fire-bomb your way through 17 unsuspecting locales, from a small town to a heavily guarded military complex. Don’t get too crazy – this killing spree is anything but senseless. Out here, strategy is key and the locals are packin’ - so take advantage of the third-person \"premeditated\" perspective that lets you see exactly who's cold and who's still able to pull a trigger."},{"t":"Power League 64","p":["Nintendo 64"],"d":"Hudson Soft","u":"Hudson Soft","g":"Sports","r":"August 8, 1997","l":"https://en.wikipedia.org/wiki/Power_League_64"},{"t":"Poy Poy","p":["PlayStation"],"g":"Card & Board Game","r":"September 30","l":"https://en.wikipedia.org/wiki/Poy_Poy","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coa3ic.jpg","s":"Poy Poy is a multiplayer party game at heart. Grab a multi-tap and four friends and take part in an ultimate battle of skill and wit. The idea is to be the last man standing in this arena based combat game. But don't worry if you can't find a multi-tap or four friends. There's plenty of AI characters to battle in various tournament modes and you can also play a 2 player deathmatch (with or without computer opponents). If it sounds fun now, wait 'till you play it...\n\nSet in seven different 3D environments strewn with throwable objects, the game challenges you to a match against three other opponents armed with logs, rocks, ice blocks, and atomic bombs. If you run out of stuff to throw, you can toss your opponents around too. Each hit drops your life meter, so be careful who you pick a fight with."},{"t":"Premier Manager 98","p":["Windows"],"d":"Dinamic Multimedia","u":"Gremlin Interactive","g":"Sports","r":"November 8, 1997","l":"https://en.wikipedia.org/wiki/Premier_Manager_98"},{"t":"Princess Crown","p":["Sega Saturn"],"d":"Atlus","u":"Atlus","g":"Action role-playing","r":"December 11, 1997","l":"https://en.wikipedia.org/wiki/Princess_Crown"},{"t":"Princess Maker: Faery Tales Come True","p":["PlayStation"],"d":"Gainax","g":"Life simulation game","r":"January 24, 1997","l":"https://en.wikipedia.org/wiki/Princess_Maker:_Faery_Tales_Come_True"},{"t":"Prisoners of the Sun","p":["Windows","MS-DOS","Super Nintendo Entertainment System","Game Boy"],"d":"Infogrames Multimedia, Bit Managers, East Point Software","u":"Infogrames Multimedia","g":"Third-person adventure","r":"February 9, 1997","l":"https://en.wikipedia.org/wiki/Prisoners_of_the_Sun_(video_game)"},{"t":"Pro Pinball: Timeshock!","p":["MS-DOS","Windows","macOS"],"d":"Cunning Developments","u":"Empire Interactive","g":"Pinball","r":"October 1997","l":"https://en.wikipedia.org/wiki/Pro_Pinball:_Timeshock!","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co262a.jpg","s":"Timeshock! is a 1997 pinball computer game developed by Cunning Developments and published by Empire Interactive. It is the second game in the Pro Pinball series, and is themed around the concept of time travel. \n \nThe inclusion of a time machine fixture on the table facilitates the game's time travel theme. At any one time the player is in one of a handful of time zones, the main ones being: The Present Day, The Distant Future, Ancient Rome and The Prehistoric Age. Completion of certain objectives allows the player to travel between time zones (although some must be unlocked first, by means of completing secondary objectives). \n \nAlthough the basic method of playing is persistent across time zones, the details of particular awards and objectives are themed towards the current time, for example, you might be awarded with a ray gun in the future, whilst in the present day you might be awarded with a magnet. This provides variety, and helps facilitate a wider set of goals."},{"t":"Prokletí Eridenu","p":["MS-DOS"],"d":"Napalm Soft, Zima Software","u":"Zima Software","g":"Dungeon crawl","l":"https://en.wikipedia.org/wiki/Proklet%C3%AD_Eridenu"},{"t":"Puchi Carat","p":["Arcade","PlayStation","Game Boy Color","Windows"],"d":"Taito","u":"Taito","g":"Breakout clone","r":"October 1997","l":"https://en.wikipedia.org/wiki/Puchi_Carat"},{"t":"Putt-Putt Travels Through Time","p":["macOS","Windows"],"d":"Humongous Entertainment","u":"Humongous Entertainment","g":"Adventure","r":"June 1, 1997","l":"https://en.wikipedia.org/wiki/Putt-Putt_Travels_Through_Time","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3y4k.jpg","s":"In this Junior Adventure, Putt-Putt must travel through time to rescue his dog Pep and retrieve his lunchbox, calculator, and history report. This was the first Putt-Putt game to have multiple paths — the missing objects could be in one of four locations, meaning there could be different puzzles on different playthroughs."},{"t":"Puzzle Bobble 4","p":["Arcade"],"r":"December","l":"https://en.wikipedia.org/wiki/Puzzle_Bobble_4"},{"t":"Quake II","p":["Windows","MS-DOS","PlayStation"],"g":"Action","r":"December 6","l":"https://en.wikipedia.org/wiki/Quake_II","i":"images/steam-2320.jpg","s":"You are humanity’s last hope to stop the Strogg, a hostile alien race waging war against Earth. Play this military sci-fi FPS, now upgraded for modern platforms with improved visuals, new campaign content, online multiplayer/co-op, and more."},{"t":"Queen: The Eye","p":["MS-DOS","Windows"],"d":"Destination Design","u":"Electronic Arts","g":"Action-adventure","l":"https://en.wikipedia.org/wiki/Queen:_The_Eye"},{"t":"Quiver","p":["MS-DOS"],"d":"ESD Games","u":"ESD Games","g":"First-person shooter","r":"March 1997","l":"https://en.wikipedia.org/wiki/Quiver_(video_game)"},{"t":"Quo Vadis 2","p":["Sega Saturn"],"d":"Glams","u":"Glams","g":"Real-time tactics, real-time strategy","r":"April 4, 1997","l":"https://en.wikipedia.org/wiki/Quo_Vadis_2"},{"t":"Raiden Fighters 2","p":["Arcade"],"d":"Seibu Kaihatsu","u":"Fabtek, The Metrotainment Network, Tuning Electronic, DotEmu","g":"Vertical scrolling shooter","l":"https://en.wikipedia.org/wiki/Raiden_Fighters_2"},{"t":"Rally Cross","p":["PlayStation"],"d":"Sony Interactive Studios America","u":"Sony Computer Entertainment","g":"Racing","r":"February 28, 1997","l":"https://en.wikipedia.org/wiki/Rally_Cross_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2ivu.jpg","s":"Rally style racing lets you perform power slides, end-over-end crashes, rolling your car, crashing into others and forcing cars off the road -- everything damages your vehicle! Compete in a season or tournament mode with three difficulty levels and four perspectives. So what are you waiting for? Rally on!"},{"t":"Rampage World Tour","p":["Arcade","PlayStation","Sega Saturn","Windows"],"d":"Game Refuge","u":"Midway, GT Interactive","g":"Action","r":"March 1997","l":"https://en.wikipedia.org/wiki/Rampage_World_Tour","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co25gh.jpg","s":"Rampage World Tour is a updated version of the classic Rampage. Rampage World Tour starts off at Scumlabs International where three lab technicians, George, Lizzy, and Ralph have mutated in an accident involving toxic waste. George has turned into a gigantic ape, Lizzy a gigantic lizard or dinosaur, and Ralph some sort of gigantic wolf. The three destroy the lab they previously worked at and then embark on a path of destruction encompassing the entire globe."},{"t":"Rapid Racer","p":["PlayStation"],"d":"Sony Computer Entertainment Europe","u":"Sony Computer Entertainment","g":"Racing","r":"October 1, 1997","l":"https://en.wikipedia.org/wiki/Rapid_Racer"},{"t":"Rapid River","p":["Arcade"],"d":"Namco","u":"Namco","g":"Boating","r":"November 1997","l":"https://en.wikipedia.org/wiki/Rapid_River_(video_game)"},{"t":"Ray Tracers","p":["PlayStation"],"d":"Taito","u":"Taito, Sony Computer Entertainment, THQ","g":"Racing, vehicular combat","r":"January 17, 1997","l":"https://en.wikipedia.org/wiki/Ray_Tracers"},{"t":"Reader Rabbit","p":["Apple II","Apple IIGS","Atari 8-bit","Commodore 64","MS-DOS","macOS","Windows"],"d":"The Learning Company, The Connelley Group","u":"The Learning Company","g":"Educational","l":"https://en.wikipedia.org/wiki/Reader_Rabbit_(video_game)"},{"t":"Reader Rabbit 2","p":["MS-DOS","Windows","macOS"],"d":"The Learning Company","u":"The Learning Company","g":"Educational video game","l":"https://en.wikipedia.org/wiki/Reader_Rabbit_2"},{"t":"Reader Rabbit Kindergarten","p":["Windows","macOS"],"d":"The Learning Company","u":"The Learning Company","g":"Edutainment","r":"July 9, 1997","l":"https://en.wikipedia.org/wiki/Reader_Rabbit_Kindergarten"},{"t":"Reader Rabbit Toddler","p":["Windows","macOS"],"d":"KnowWare","u":"The Learning Company","g":"Edutainment","r":"June 1997","l":"https://en.wikipedia.org/wiki/Reader_Rabbit_Toddler"},{"t":"Ready to Read with Pooh","p":["macOS","Windows"],"d":"Disney Interactive Victoria","u":"Disney Interactive","l":"https://en.wikipedia.org/wiki/Ready_to_Read_with_Pooh"},{"t":"Real Bout Fatal Fury Special","p":["Arcade","Neo Geo AES","Neo Geo CD","Sega Saturn"],"d":"SNK, Gaibrain, Yumekobo","u":"SNK, Takara","g":"Fighting","r":"January 28, 1997","l":"https://en.wikipedia.org/wiki/Real_Bout_Fatal_Fury_Special","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1w2o.jpg","s":"The supreme trial of strength awaits! 19 of Fatal Fury's hottest heroes collide! One year since the fearsome conclusion to \"Real Bout\", the hungry wolves ready themselves for a new battle, \"Real Bout Special\" - the paramount pugilistic proving ground!\n\nThe game retains the cast of the original Real Bout, with the addition of Tung Fu Rue, Cheng Sinzan, Laurence Blood and Wolfgang Krauser from Fatal Fury Special, with Krauser serving as the new final boss. Geese Howard, who was killed off in the end of the original Real Bout, appears in this game as a hidden final boss in a special \"Nightmare Match\" and as an unlockable playable character in the home versions. The game also features hidden \"extra\" versions of Tung Fu Rue, Billy Kane, Blue Mary, and Andy Bogard, for a total of 23 (24 if counting Geese) characters."},{"t":"Real Sound: Kaze no Regret","p":["Sega Saturn"],"d":"Warp","u":"Warp","g":"Audio game, adventure","r":"July 18, 1997","l":"https://en.wikipedia.org/wiki/Real_Sound:_Kaze_no_Regret"},{"t":"Realms of the Haunting","p":["Windows","MS-DOS"],"r":"March 24","l":"https://en.wikipedia.org/wiki/Realms_of_the_Haunting"},{"t":"Rebel Moon Rising","p":["Windows"],"d":"Fenris Wolf","u":"GT Interactive","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Rebel_Moon_Rising"},{"t":"Red Baron II","p":["Windows"],"d":"Dynamix","u":"Sierra On-Line","g":"Combat flight simulator","r":"December 16, 1997","l":"https://en.wikipedia.org/wiki/Red_Baron_II"},{"t":"Redneck Rampage","p":["Windows","MS-DOS"],"g":"Action","r":"April 7","l":"https://en.wikipedia.org/wiki/Redneck_Rampage","i":"images/steam-565550.jpg","s":"Well, we crash-landed that UFO in the desert and Bubba says he wants to go home. Heck, I don't blame him 'cause there ain't no place like Hickston. But according to my map, we're gonna have to blast our way through jack o' lope farms and a riverboat as well as a brothel 'fore we get home again."},{"t":"Resident Evil","p":["Windows","MS-DOS"],"r":"September 17","l":"https://en.wikipedia.org/wiki/Resident_Evil_(1996_video_game)"},{"t":"Resident Evil: Director's Cut","p":["PlayStation"],"d":"Capcom Planning Room 2","u":"Virgin Interactive Entertainment, Capcom","g":"Shooter, Puzzle, Adventure","r":"September 25, 1997","l":"https://www.igdb.com/games/resident-evil-directors-cut","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2w3m.jpg","s":"Resident Evil: Director's Cut is an arranged version of the original game produced to compensate for the highly publicized delay of the sequel Resident Evil 2. The game contains a new arranged mode with various changes made to the game. The original release of the Director's Cut advertised an uncut version of the opening cinema in full colour and never-before-seen. Notable aspects of this video include shots of a corpse with bites taken out of the face, close-ups of zombie dogs bleeding when shot, and graphic quick-cuts of Joseph being bitten by these dogs."},{"t":"Riana Rouge","p":["Windows","macOS"],"d":"Black Dragon Productions","u":"Black Dragon Productions","g":"Adult, action-adventure","l":"https://en.wikipedia.org/wiki/Riana_Rouge"},{"t":"Rising Lands","p":["Windows"],"d":"Microïds","u":"R&P Electronic Media","g":"Real Time Strategy","l":"https://en.wikipedia.org/wiki/Rising_Lands"},{"t":"Rival Schools: United by Fate","p":["Arcade"],"d":"Capcom","u":"Capcom, Virgin Interactive","g":"Fighting","r":"November 1997","l":"https://en.wikipedia.org/wiki/Rival_Schools:_United_by_Fate","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cocjgw.jpg","s":"The main fighting game is best described as a polygonal Marvel vs. Capcom game, with some notable differences. Control wise, the game varies from other Capcom fighting games by only having four buttons (two punches and two kicks, which is closer to the SNK game format) rather than the standard six. A player chooses a team of two characters, and fights against another two character team. The actual fights, however, are one-on-one fights, with the partner only participating by being called in when a player has enough 'vigor' for a Team Up attack, done by pressing a punch and kick button of the same pressure. The Team Ups would be some kind of double team attack by the character and partner, or (for most female characters' Team Ups) would heal the main character or give them more vigor. After the end of a round, a player (win or lose) has a choice to fight the next round with the partner from the previous round, or to keep their main character in play. The 'vigor' meter (essentially a super meter) could go up to 9 levels, with Team Ups costing two levels and super moves from a single person all costing one level of vigor. Much like the Marvel vs. Capcom games, launchers can be done that allow air combos to be performed, with all characters having universal low and high launchers.\n\nThe game also had a few defensive techniques.\n\nTardy Counters acted much like Alpha Counters from Street Fighter Alpha, allowing a player to immediately counter-attack from a blocking position. However, the restrictions on Tardy Counters are very lax; any hard normal, special or super attack can be used to Tardy counter (Alpha counters are only limited to certain special moves for each character), and Tardy Counters do not cost any extra vigor to perform (Alpha Counters required at least a level of Super Combo gauge to do).\n\nAttack Cancels allowed a player to cancel an incoming hit simply by timing their own hit with the attack, which would cancel out both attacks (though it does not nullify the remaining hits of a multi-hit move). Also, one additional level of vigor is awarded."},{"t":"Riven","p":["Windows","MS-DOS","Sega Saturn","PlayStation"],"g":"Adventure, Casual, Indie","r":"October 29","l":"https://en.wikipedia.org/wiki/Riven","i":"images/steam-1712350.jpg","s":"Uncover a story of intrigue, betrayal, and a civilization teetering on the brink of collapse as you solve intricate puzzles to unlock the secrets of Riven. Built from the ground-up and expanded from the award-winning original game released in 1997."},{"t":"Riven: The Sequel to Myst","p":["macOS","Windows","PlayStation"],"d":"Cyan Worlds","u":"Acclaim Entertainment, Enix, Tec Toy, Red Orb Entertainment, SUNSOFT, Mean Hamster Software, Sega Enterprises, Inc., Cyan Worlds, Ubi Soft Entertainment","g":"Point-and-click, Puzzle, Adventure","r":"October 31, 1997","l":"https://www.igdb.com/games/riven-the-sequel-to-myst","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2jlf.jpg","s":"Riven: The Sequel to Myst is a graphic adventure puzzle game developed by Cyan and released in 1997. It continues the story of Myst, following the player’s journey to rescue Atrus’s wife, Catherine, from a decaying world. The game features pre-rendered environments with complex, interconnected puzzles and minimal direct guidance.\nIts visuals, sound design, and world-building were praised for their depth and realism.\nRiven expanded on Myst’s narrative and gameplay scale, becoming one of the most acclaimed adventure games of its time."},{"t":"Robotfindskitten","p":[],"l":"https://en.wikipedia.org/wiki/Robotfindskitten"},{"t":"Rock & Roll Racing 2: Red Asphalt","p":["PlayStation"],"d":"Interplay","u":"Interplay","g":"Racing, vehicular combat","r":"December 26, 1997","l":"https://en.wikipedia.org/wiki/Rock_&_Roll_Racing_2:_Red_Asphalt"},{"t":"Rockett's New School","p":["macOS","Windows"],"d":"Purple Moon, Presage Software","l":"https://en.wikipedia.org/wiki/Rockett's_New_School"},{"t":"Rosco McQueen Firefighter Extreme","p":["PlayStation"],"d":"Slippery Snake Studios","u":"Sony Computer Entertainment Europe, Psygnosis","g":"Action","r":"September 1997","l":"https://en.wikipedia.org/wiki/Rosco_McQueen_Firefighter_Extreme"},{"t":"RPG Maker","p":["PlayStation"],"d":"Kuusou Kagaku","u":"Enterbrain, Agetec","g":"Role-playing","r":"November 27, 1997","l":"https://en.wikipedia.org/wiki/RPG_Maker_(video_game)"},{"t":"Rush Hour","p":["PlayStation","Windows"],"d":"Clockwork Entertainment","u":"Psygnosis","g":"Racing video game","r":"April 30, 1997","l":"https://en.wikipedia.org/wiki/Rush_Hour_(video_game)"},{"t":"S40 Racing","p":["Windows"],"d":"Digital Illusions CE","g":"Racing","r":"October 1997","l":"https://en.wikipedia.org/wiki/S40_Racing"},{"t":"Sabre Ace: Conflict Over Korea","p":["Windows"],"d":"Eagle Interactive","u":"Virgin Interactive","g":"Combat flight simulator","r":"October 17, 1997","l":"https://en.wikipedia.org/wiki/Sabre_Ace:_Conflict_Over_Korea"},{"t":"Safecracker","p":["macOS","Windows"],"d":"Daydream Software","u":"Warner Interactive Entertainment, GT Interactive, Dreamcatcher Interactive","g":"Puzzle adventure","r":"May 1997","l":"https://en.wikipedia.org/wiki/Safecracker_(video_game)"},{"t":"SaGa Frontier","p":["PlayStation"],"d":"Square Product Development Division 2","u":"Square, Sony Computer Entertainment, Square Enix","g":"Role-playing","r":"July 11, 1997","l":"https://en.wikipedia.org/wiki/SaGa_Frontier","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2x4z.jpg","s":"Enter a vast frontier where seven quests are taken one hero at a time.\n\nA wizard's dark destiny, a woman's revenge, even a robot's search for his soul, Seven amazing adventures that weave into one - yours."},{"t":"Samurai Shodown 64","p":["Arcade"],"d":"SNK","u":"SNK","g":"Fighting","r":"December 19, 1997","l":"https://en.wikipedia.org/wiki/Samurai_Shodown_64"},{"t":"Sandwarriors","p":["MS-DOS"],"d":"Astros Productions, Gremlin Interactive","u":"Interplay Entertainment","g":"Action","r":"May 1997","l":"https://en.wikipedia.org/wiki/Sandwarriors"},{"t":"Santa Fe Mysteries: Sacred Ground","p":["MS-DOS","macOS","Windows"],"d":"Activision","u":"Activision","g":"Adventure","l":"https://en.wikipedia.org/wiki/Santa_Fe_Mysteries:_Sacred_Ground"},{"t":"Satellaview games from The Legend of Zelda series","p":[],"l":"https://en.wikipedia.org/wiki/Satellaview_games_from_The_Legend_of_Zelda_series"},{"t":"Saturn Bomberman Fight","p":["Sega Saturn"],"d":"Eleven","u":"Hudson Soft","g":"Action, maze","r":"December 11, 1997","l":"https://en.wikipedia.org/wiki/Saturn_Bomberman_Fight"},{"t":"Scarab","p":["Windows"],"d":"Electronic Arts","u":"Electronic Arts","g":"First-person shooter","r":"March 20, 1997","l":"https://en.wikipedia.org/wiki/Scarab_(video_game)"},{"t":"Screamer Rally","p":["MS-DOS"],"d":"Milestone","u":"Virgin Interactive","g":"Racing","l":"https://en.wikipedia.org/wiki/Screamer_Rally"},{"t":"Scud: The Disposable Assassin","p":["Sega Saturn"],"d":"Syrox Developments","u":"SegaSoft","g":"Run and gun, light gun shooter","r":"March 20, 1997","l":"https://en.wikipedia.org/wiki/Scud:_The_Disposable_Assassin_(video_game)"},{"t":"Secret Paths","p":[],"d":"Purple Moon","g":"Interactive novel","l":"https://en.wikipedia.org/wiki/Secret_Paths_(video_game)"},{"t":"Sega Bass Fishing","p":["Arcade"],"d":"AM1, Sims, Cavia, Sega","u":"Sega","g":"Fishing","r":"December 1997","l":"https://en.wikipedia.org/wiki/Sega_Bass_Fishing","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co40xx.jpg","s":"Explore the exciting sport of Bass fishing! Based on the Dreamcast hit, motor out to eight different fishing locations to catch the biggest and baddest Bass possible! Choose between fourteen different lures, and compete in four tournaments. Start off as an amateur, and work your way up to the pros in the Masters Classic tournament. Get hooked!"},{"t":"Sega Water Ski","p":["Arcade"],"d":"Sega AM1","u":"Sega","r":"December 1997","l":"https://en.wikipedia.org/wiki/Sega_Water_Ski"},{"t":"Sega Worldwide Soccer '98","p":["Sega Saturn","Windows"],"d":"Sega","u":"Sega","g":"Sports video game","r":"October 16, 1997","l":"https://en.wikipedia.org/wiki/Sega_Worldwide_Soccer_'98"},{"t":"Sentient","p":["PlayStation","MS-DOS","Windows"],"d":"Psygnosis","u":"Psygnosis","g":"Adventure","r":"April 10, 1997","l":"https://en.wikipedia.org/wiki/Sentient_(video_game)"},{"t":"Seven Kingdoms","p":["Windows","Linux"],"d":"Enlight","u":"Interactive Magic","g":"Real-time strategy","r":"November 30, 1997","l":"https://en.wikipedia.org/wiki/Seven_Kingdoms_(video_game)"},{"t":"Shadow Master","p":["PlayStation"],"d":"HammerHead","u":"Psygnosis","g":"First-person shooter","r":"December 15, 1997","l":"https://en.wikipedia.org/wiki/Shadow_Master"},{"t":"Shadow Warrior","p":["Windows","MS-DOS"],"g":"Action, Adventure","r":"August 25","l":"https://en.wikipedia.org/wiki/Shadow_Warrior_(1997_video_game)","i":"images/steam-233130.jpg","s":"Shadow Warrior is a bold reimagining of the classic 3D Realms’ shooter from independent developer Flying Wild Hog (Hard Reset) starring the legendary and quick-witted warrior Lo Wang."},{"t":"Shanghai: Dynasty","p":["Windows","macOS"],"d":"Quicksilver Software, Presage Software","u":"Activision","l":"https://en.wikipedia.org/wiki/Shanghai:_Dynasty"},{"t":"Shienryu","p":["Arcade","Sega Saturn"],"d":"Warashi","u":"Sega, Warashi, Natsume Inc.","g":"Scrolling shooter","r":"February 1997","l":"https://en.wikipedia.org/wiki/Shienryu"},{"t":"Shining Force III","p":["Sega Saturn"],"d":"Sonic! Software Planning, Camelot Software Planning","u":"Sega","g":"Tactical role-playing","r":"December 11, 1997","l":"https://en.wikipedia.org/wiki/Shining_Force_III","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co300x.jpg","s":"Shining Force III is a fantasy turn-based tactics role-playing video game designed for the Sega Saturn by Camelot Software Planning. It is a continuation of the Shining series. Comprising three separate but overlapping storylines, the Japanese version of Shining Force III was released in three volumes, known as: \"Scenario 1 - God Warrior of the Kingdom\", \"Scenario 2 - Target: Child of God\", and \"Scenario 3 - \"Bulzome Rising\".\nIn America and Europe, only Scenario 1 was released. The real ending to the game can only be viewed by completing all the games in the series."},{"t":"Shinrei Jusatsushi Tarōmaru","p":["Sega Saturn"],"d":"Time Warner Interactive Japan","u":"Time Warner Interactive Japan","g":"Action","r":"January 17, 1997","l":"https://en.wikipedia.org/wiki/Shinrei_Jusatsushi_Tar%C5%8Dmaru"},{"t":"Shinseiki Evangelion: Koutetsu no Girlfriend","p":["Windows"],"d":"Gainax, Gainax Network Systems","u":"Sega Enterprises, Ltd., Bandai","g":"Adventure, Visual Novel","r":"February 13, 1997","l":"https://www.igdb.com/games/shinseiki-evangelion-koutetsu-no-girlfriend","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co25ua.jpg","s":"Neon Genesis Evangelion: Girlfriend of Steel, also known as Neon Genesis Evangelion: Iron Maiden, is a video game based on the Gainax anime/manga series Neon Genesis Evangelion, released officially only in Japan for the PlayStation, Sega Saturn, PlayStation 2, PSP, Windows (PC), and Macintosh. On January 20, 2005 a sequel was released titled \"Neon Genesis Evangelion: Girlfriend of Steel 2nd\" for the Playstation 2, and while it does feature much of the cast of the original game, the story is unrelated to the original's."},{"t":"Shinsetsu Samurai Spirits Bushidō Retsuden","p":["Neo Geo CD","PlayStation","Sega Saturn"],"d":"SNK","u":"SNK","g":"Role-playing","r":"June 26, 1997","l":"https://en.wikipedia.org/wiki/Shinsetsu_Samurai_Spirits_Bushid%C5%8D_Retsuden"},{"t":"Shipwreckers","p":["Windows","MS-DOS","PlayStation"],"g":"Strategy, Adventure","r":"October 28","l":"https://en.wikipedia.org/wiki/Overboard!_(1997_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5x5q.jpg","s":"Shipwreckers is a third-person arcade-style shooter where you sail around in a pirate ship battling other pirate vessels and destroying the gun turrets and flamethrowers that are defending ports in an attempt to spread your swashbuckling reign of terror. Reward treasures and increasingly more potent weapons keep the pacing alive in this near top-down 3D action game. Shipwreckers supports solo play, head to head, and multi-person battles."},{"t":"Shivers II: Harvest of Souls","p":["Windows"],"d":"Sierra On-Line","u":"Sierra On-Line","g":"Adventure","r":"April 14, 1997","l":"https://en.wikipedia.org/wiki/Shivers_II:_Harvest_of_Souls"},{"t":"Shock Troopers","p":["Neo Geo AES","Arcade"],"g":"Shooter, Arcade","r":"November 1","l":"https://en.wikipedia.org/wiki/Shock_Troopers","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3z3g.jpg","s":"Shock Troopers is a 1-2 player game where players select one of eight characters to play as. Each character has their own attack. Players also have to choose one of three routes to take. The object of the game is to go toward the end of the level and defeat the end-of-level boss, which is usually a huge vehicle. Crates that are scattered throughout the levels can be broken into to reveal new weapons and power-ups.\n\nThere is a team mode where players have to select three characters. The characters can be switched on-the-fly during gameplay, which is useful if one of them is badly injured. Players can use the other teammates until life-ups can be found."},{"t":"Sid Meier's Gettysburg!","p":["Windows","MS-DOS"],"u":"Electronic Arts","r":"October 14, 1997","l":"https://en.wikipedia.org/wiki/Sid_Meier%27s_Gettysburg!"},{"t":"Side Pocket 3","p":["Sega Saturn"],"d":"Data East","u":"Data East","g":"Cue sports","r":"July 18, 1997","l":"https://en.wikipedia.org/wiki/Side_Pocket_3"},{"t":"Sierra Pro Pilot","p":["Windows"],"d":"Dynamix","u":"Sierra On Line","g":"Flight simulation","r":"December 5, 1997","l":"https://en.wikipedia.org/wiki/Sierra_Pro_Pilot"},{"t":"Sign of the Sun","p":["MS-DOS"],"d":"International Computer Entertainment","u":"Project Two Interactive","g":"Adventure","l":"https://en.wikipedia.org/wiki/Sign_of_the_Sun"},{"t":"Silhouette Mirage","p":["Sega Saturn"],"g":"Shooter, Platform","r":"September 10","l":"https://en.wikipedia.org/wiki/Silhouette_Mirage","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3dgl.jpg","s":"Silhouette Mirage is a side-scrolling action game. The basic gameplay is somewhat similar to that of Gunstar Heroes. The game's standout feature is the concept of the two attributes. Depending on the enemy's attributes and the type of attack used by Shyna, damage can be increased, and spirit (equivalent to magic power) can be absorbed from enemies. Shyna can dash, jump, crouch, slide, and grab enemies, executing combo attacks. It is also possible to master moves, acquire money, and purchase special creatures called \"parasites\", which teach Shyna various types of attacks."},{"t":"Slayers Royal","p":["Sega Saturn","PlayStation"],"d":"Onion Egg","u":"Entertainment Software Publishing, Kadokawa Shoten","g":"Tactical role-playing","r":"July 25, 1997","l":"https://en.wikipedia.org/wiki/Slayers_Royal"},{"t":"Snowboard Kids","p":["Nintendo 64"],"d":"Racdym","u":"Atlus, Nintendo","g":"Snowboarding","r":"December 12, 1997","l":"https://en.wikipedia.org/wiki/Snowboard_Kids","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co28cg.jpg","s":"The kids are arguing about their snowboarding skills. The debate escalates to the point where they decide to hold a snowboarding tournament to determine who is the best. One character, Shinobin, has no involvement whatsoever until he is unlocked by the player.\n\nIn addition to the usual gameplay of a snowboarding game, Snowboard Kids adds \"Shots\" (special weapons used to attack players) and items which can help the player, hinder other players, or both.\n\nThe game has nine main courses. Although some of the courses are snowy mountains, many are courses that would be unorthodox for snowboarding in the real world. Such courses include an amusement park, a desert, a vast valley, a dark highway, and a Japanese village during the cherry blossom festival.\n\nThere were several game mechanics that were unique to Snowboard Kids from other snowboard games and racing games at the time. One was the addition of the second item slot, allowing each player to carry a shooting item and support item (such as a rock, or invisibility) at the same time. Also, players needed to pay 100 gold in order to grab an item during the race, which could be obtained either through performing tricks or collecting coins scattered across the course. All courses also required players to race down the hill for multiple laps. Once a player had reached the bottom of the hill, he or she would need to pass through the lift gate to be transported back to the top of the hill, and could not be attacked by other players in this transition."},{"t":"SODA Off-Road Racing","p":["Windows"],"d":"Software Allies","u":"Sierra Entertainment","g":"Racing","r":"October 29, 1997","l":"https://en.wikipedia.org/wiki/SODA_Off-Road_Racing"},{"t":"Sol Divide","p":["Arcade"],"d":"Psikyo, Boom, Zerodiv","u":"Psikyo, Atlus, XS Games, Taito","g":"Scrolling shooter","r":"May 1997","l":"https://en.wikipedia.org/wiki/Sol_Divide","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2d66.jpg","s":"Sol Divide delivers players with the action they are looking for and a story that places them right in the heat of the battle in this fantasy-based shooter. With 3 characters to choose from, players will battle their way through various levels in order to beat the evil Iftar who holds the magical sword Sol Divide. With a combination of magic and hand to hand combat, you will be able to defeat Iftar and recover the sacred Spirit Stone."},{"t":"Solar Assault","p":["Arcade"],"d":"Konami","u":"Konami","g":"Rail shooter","r":"July 1997","l":"https://en.wikipedia.org/wiki/Solar_Assault"},{"t":"Soldier Boyz","p":["MS-DOS","Windows"],"d":"Hypnotix","u":"DreamCatcher Interactive; MCPA Interactive; Olympic ROM World","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/Soldier_Boyz_(video_game)"},{"t":"Solid Runner","p":["Super Nintendo Entertainment System"],"d":"Sting Entertainment","u":"ASCII Corporation","g":"Role-playing video game","r":"March 28, 1997","l":"https://en.wikipedia.org/wiki/Solid_Runner"},{"t":"Sonic & Knuckles Collection","p":[],"l":"https://en.wikipedia.org/wiki/Sonic_&_Knuckles_Collection"},{"t":"Sonic Jam","p":["Sega Saturn"],"r":"June 20","l":"https://en.wikipedia.org/wiki/Sonic_Jam"},{"t":"Sonic R","p":["Sega Saturn"],"g":"Platform, Racing","r":"November 17","l":"https://en.wikipedia.org/wiki/Sonic_R","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4sfd.jpg","s":"Originally released for the Sega Saturn, Sonic R is a racing game featuring characters from the Sonic the Hedgehog series.\n\nSonic and Tails came across an announcement one day about a competition called the \"World Grand Prix\" to determine the fastest in the world. Sonic initially showed no interest, but upon seeing Dr. Eggman's name among the participants, he decided to join. Knuckles wanted to settle the score with Sonic, Amy had unwavering belief that Sonic would definitely show up, and Eggman secretly prepared a few secret weapons.\n\nWho will claim the glory of the World Grand Prix?"},{"t":"Sophie's World","p":["macOS","Windows"],"d":"The Multimedia Corporation","u":"Voyager","g":"Adventure","l":"https://en.wikipedia.org/wiki/Sophie's_World_(video_game)"},{"t":"Spawn: The Eternal","p":["PlayStation"],"d":"Sony Interactive Studios America","u":"Sony Computer Entertainment","g":"Beat 'em up, adventure, fighting","r":"December 9, 1997","l":"https://en.wikipedia.org/wiki/Spawn:_The_Eternal","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co7cr0.jpg","s":"Spawn: The Eternal is based on Todd McFarlane's Spawn comics. The game switches back and forth between two styles of play. There's an exploration mode, which is along the lines of Tomb Raider. Spawn must climb and jump his way through a variety of environmental obstacles while smashing crates and furniture to find power-ups.\n\nWhen you approach an enemy, however, the engine switches into something between a 3D fighting game and an old-fashioned side-scrolling beat-em-up. Spawn must defeat one or more enemies, who may be surrounding him before he can continue."},{"t":"Speedboat Attack","p":["Windows"],"d":"Criterion Studios","u":"Telstar Electronic Studios","g":"Racing","l":"https://en.wikipedia.org/wiki/Speedboat_Attack"},{"t":"Spellcross","p":["MS-DOS"],"d":"Cauldron HQ","u":"Sales Curve Interactive","g":"Turn-based strategy","l":"https://en.wikipedia.org/wiki/Spellcross"},{"t":"Spider: The Video Game","p":["PlayStation"],"d":"Boss Game Studios","u":"BMG Interactive","g":"Platform","r":"February 25, 1997","l":"https://en.wikipedia.org/wiki/Spider:_The_Video_Game"},{"t":"Spy Fox in \"Dry Cereal\"","p":["macOS","Windows"],"d":"Humongous Entertainment","u":"Humongous Entertainment","g":"Adventure","r":"October 17, 1997","l":"https://en.wikipedia.org/wiki/Spy_Fox_in_%22Dry_Cereal%22","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co41zx.jpg","s":"The super-suave agent, SPY Fox, must find Mr. Udderly, rescue all the cows, and stop William the Kid from depleting the worlds supply of milk. Using ingenious SPY gadgets, keen wits, and daring moves, SPY Fox, jumps out on an udderly exhilarating adventure!"},{"t":"Star Command: Revolution","p":["MS-DOS","Windows"],"d":"Metropolis Digital","u":"GT Interactive","g":"Real-time strategy","r":"March 1997","l":"https://en.wikipedia.org/wiki/Star_Command:_Revolution"},{"t":"Star Fox 64","p":["Nintendo 64"],"u":"Nintendo","g":"Shooter","r":"April 27, 1997","l":"https://en.wikipedia.org/wiki/Star_Fox_64","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cob8pu.jpg","s":"The update to the 16-bit Super NES title continues the original's on-rails 3D shooting action on the Nintendo 64. Starring Fox McCloud, Peppy Hare, Falco Lombardi, and Slippy Toad, this new 64-bit version contains 15 plus levels, easy, medium, and difficult paths, forward-scrolling levels as well as full 3D realms, and a three-part multiplayer mode using a four-player split screen. In addition to plenty of Arwing action, the game introduces a new hover tank and even features a submarine level. The 8-megabyte cartridge also boasts voice samples from 23 different characters instead of the original's animal noises. Star Fox 64 was the first game to feature Rumble Pak support. A Rumble Pak bundle and standalone version of the game were sold. Released in Europe under the name Lylat Wars."},{"t":"Star Trek Generations","p":["Windows"],"d":"MicroProse Alameda","u":"MicroProse","g":"First-person shooter","r":"May 21, 1997","l":"https://en.wikipedia.org/wiki/Star_Trek_Generations_(video_game)"},{"t":"Star Trek: Starfleet Academy","p":["Windows","macOS"],"d":"Interplay Productions","u":"Interplay Productions, MacPlay","g":"Space flight simulator","r":"September 12, 1997","l":"https://en.wikipedia.org/wiki/Star_Trek:_Starfleet_Academy_(1997_video_game)"},{"t":"Star Warped","p":["Windows","macOS"],"d":"Parroty Interactive","u":"Palladium Interactive","g":"Adventure","r":"June 1997","l":"https://en.wikipedia.org/wiki/Star_Warped"},{"t":"Star Wars Jedi Knight: Dark Forces II","p":["Windows","MS-DOS"],"u":"LucasArts","g":"Action","r":"October 10, 1997","l":"https://store.steampowered.com/app/32380","i":"images/steam-32380.jpg","s":"Jedi Knight: Dark Forces II picks up where the award-winning Dark Forces™ game left off...with even more features and firepower in dazzling 3D graphics. As Kyle Katarn, you must acquire a lightsaber and learn the ways of the Force to become a Jedi Knight."},{"t":"Star Wars: Masters of Teräs Käsi","p":["PlayStation"],"d":"LucasArts","u":"LucasArts","g":"Fighting","r":"November 25, 1997","l":"https://en.wikipedia.org/wiki/Star_Wars:_Masters_of_Ter%C3%A4s_K%C3%A4si","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2rey.jpg","s":"Star Wars: Masters of Teräs Käsi is a fighting game released for PlayStation.\n\nThe 3D fighting genre fulfills its ultimate destiny with Star Wars Masters of Teräs Käsi, an intense one-on-one combat experience for the Sony PlayStation. The story revolves around the mysterious Arden Lyn, a master of the ancient art of Teräs Käsi, as she leads a group of the most feared champions of the Galactic Empire to eliminate the leaders of the Rebel Alliance. Join Luke Skywalker, Han Solo, Boba Fett, Princess Leia, Chewbacca, plus a few surprise characters in a Star Wars environment like you've never experienced."},{"t":"Star Wars: Shadows of the Empire","p":["Windows","MS-DOS"],"g":"Action, Adventure","r":"September 9","l":"https://store.steampowered.com/app/560170","i":"images/steam-560170.jpg","s":"As Luke Skywalker and the Rebel Alliance struggle to defeat Darth Vader and the Empire, a new threat arises. Dark Prince Xizor aspires to take Darth Vader's place at the Emperor's side. As Dash Rendar, it's up to you to protect Luke and help the Alliance. May the Force be with you!"},{"t":"Star Wars: X-Wing vs. TIE Fighter","p":["Windows","MS-DOS"],"g":"Simulator","r":"April 30","l":"https://www.igdb.com/games/star-wars-x-wing-vs-tie-fighter","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2jp4.jpg","s":"Star Wars: X-Wing vs. TIE Fighter is the third release of the X-Wing computer game series.\n\nThe player has the ability to choose for each mission which squadron he or she wants to fly in (e.g. either the Y-wings that disable a ship for capture or the X-wings that support them), his or her specific ship type, and the ship's armaments."},{"t":"Star Wars: Yoda Stories","p":["Windows"],"d":"LucasArts, Torus Games","u":"LucasArts, THQ","g":"Adventure","r":"March 12, 1997","l":"https://en.wikipedia.org/wiki/Star_Wars:_Yoda_Stories","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co74jd.jpg","s":"Grab your lightsaber and get ready for terrific Star Wars adventuring in Yoda Stories, the newest in a series of easy-to-play Desktop Adventures from LucasArts. Join Luke Skywalker as he trains to become a Jedi with Yoda, then harness the Force and cross the galaxy to meet exotic aliens, collect stange devices and weapons and deal the Galactic Empire one crippling blow after another - all within an hour!"},{"t":"Starsweep","p":["Arcade","PlayStation","Game Boy"],"d":"Axela","u":"Namco/Axela, Agetec, Midas Interactive Entertainment","g":"Puzzle","r":"October 30, 1997","l":"https://en.wikipedia.org/wiki/Starsweep"},{"t":"Steel Panthers III: Brigade Command 1939–1999","p":["MS-DOS","Windows"],"d":"Strategic Simulations","u":"Strategic Simulations","g":"Tactical wargame","r":"November 26, 1997","l":"https://en.wikipedia.org/wiki/Steel_Panthers_III:_Brigade_Command_1939%E2%80%931999"},{"t":"Steel Reign","p":["PlayStation"],"d":"Chantemar Creations, Sony Interactive Studios America","u":"Sony Computer Entertainment","g":"Vehicular combat","r":"October 9, 1997","l":"https://en.wikipedia.org/wiki/Steel_Reign"},{"t":"Steep Slope Sliders","p":["Sega Saturn"],"r":"October 23","l":"https://en.wikipedia.org/wiki/Steep_Slope_Sliders"},{"t":"Story of Eastern Wonderland","p":[],"l":"https://en.wikipedia.org/wiki/Story_of_Eastern_Wonderland"},{"t":"Strategy Challenges Collection","p":["Windows","macOS"],"d":"Edmark","u":"Edmark, The Learning Company","g":"Educational","l":"https://en.wikipedia.org/wiki/Strategy_Challenges_Collection"},{"t":"Street Fighter Collection","p":["Sega Saturn","PlayStation"],"r":"September 18","l":"https://en.wikipedia.org/wiki/Street_Fighter_Collection"},{"t":"Street Fighter III","p":["Arcade"],"d":"Capcom","u":"Capcom, Virgin Interactive","g":"Fighting","r":"February 28, 1997","l":"https://en.wikipedia.org/wiki/Street_Fighter_III"},{"t":"Street Fighter III 2nd Impact: Giant Attack","p":["Arcade"],"d":"Capcom","u":"Capcom","g":"Fighting, Arcade","r":"October 18, 1997","l":"https://www.igdb.com/games/street-fighter-iii-2nd-impact-giant-attack","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co55ev.jpg","s":"2nd Impact brought back all the characters from the first game and introduced two new ones: Hugo and Urien. Yang, who was an alternate version of Yun in the first game, became his own character with his own set of special moves and super arts. Akuma also returned as a secret computer-controlled challenger and selectable character. Thus the playable character roster increased to 14. In addition to the regular Akuma, a non-playable computer-controlled version named \"Shin Akuma\" also appears in the single-player mode."},{"t":"Street Fighter III: 2nd Impact","p":["Arcade"],"d":"Capcom","u":"Capcom, Virgin Interactive","g":"Fighting","r":"September 30, 1997","l":"https://en.wikipedia.org/wiki/Street_Fighter_III:_2nd_Impact"},{"t":"Street Fighter III: New Generation","p":["Arcade"],"d":"Capcom","u":"Capcom","g":"Fighting, Arcade","r":"February 28, 1997","l":"https://www.igdb.com/games/street-fighter-iii-new-generation","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1w4q.jpg","s":"Street Fighter III: New Generation is a fighting game in Capcom's Street Fighter series, originally released as coin-operated arcade game in 1997. Street Fighter III was produced for the CD-ROM-based CP System III hardware, which allowed for more elaborate 2D graphics than the CPS II-based Street Fighter Alpha games (the previous incarnation of the Street Fighter series), while revamping many of the play mechanics. The game, which was designed as a direct sequel to Street Fighter II, initially discarded every previous character except for Ryu and Ken (hence the \"New Generation\" subtitle), introducing an all-new roster led by Alex."},{"t":"Streets of SimCity","p":["Windows"],"d":"Maxis","u":"Maxis, Electronic Arts","g":"Racing, vehicular combat","r":"November 4, 1997","l":"https://en.wikipedia.org/wiki/Streets_of_SimCity"},{"t":"Strikers 1945 II","p":["Arcade","Sega Saturn","PlayStation","Windows"],"d":"Psikyo, Kuusou Kagaku, WindySoft","u":"Psikyo, Success, Agetec, Midas Games","g":"Scrolling shooter","l":"https://en.wikipedia.org/wiki/Strikers_1945_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co276b.jpg","s":"Continuing where the last game ended, the forces of CANY had been demolished by the previous Strikers' line-up. However, a small group known as the FGR stole the sources and technology responsible for the last events and planned to continue CANYs work by initiating world-warfare with massive mech technology. Once again, the Strikers are called into action."},{"t":"Sub Culture","p":["Windows"],"d":"Criterion Games","u":"Ubi Soft","g":"Submarine simulator","r":"November 11, 1997","l":"https://en.wikipedia.org/wiki/Sub_Culture"},{"t":"SubSpace","p":["Windows"],"d":"Burst Studios","u":"Virgin Interactive","g":"Action","r":"December 1997","l":"https://en.wikipedia.org/wiki/SubSpace_(video_game)"},{"t":"Super Bomberman 5","p":["Super Nintendo Entertainment System"],"d":"Hudson Soft","u":"Hudson Soft","g":"Action, maze, party","r":"February 28, 1997","l":"https://en.wikipedia.org/wiki/Super_Bomberman_5","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2w8i.jpg","s":"An evil Bomber named Emperor Terrorin who has the power of Time itself has freed various criminal Bombers from their prison cells in orbit around Planet Bomber. Setting them up in a warped time and space, Shirobon, Kurobon, and their Louie (Rui) companions must travel through stages and defeat them before going up against Emperor Terrorin himself. Super Bomberman 5, released by Hudson Soft in early 1997, was the final Bomberman game released on the Super Family Computer - the Japanese version of the SNES. The game was released in two variations: a standard cartridge and a gold cartridge, which was sold exclusively through CoroCoro Comic. The gold cartridge included extra maps in battle mode."},{"t":"Super Gem Fighter Mini Mix","p":["Arcade"],"d":"Capcom","u":"Capcom, Virgin Interactive Entertainment","g":"Fighting","r":"September 1997","l":"https://en.wikipedia.org/wiki/Super_Gem_Fighter_Mini_Mix","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/cobihk.jpg","s":"It's the most outrageous fighting game ever! Innocent but deadly, these pint-sized champions from Street Fighter and DarkStalkers pack one heck of a punch. Battle to collect power-up gems and duke it out with the most insane attacks and hilarious fighting combos of all time."},{"t":"Sutte Hakkun","p":["Super Nintendo Entertainment System"],"d":"Nintendo R&D2, Indieszero","u":"Nintendo","g":"Platform, puzzle","r":"November 2, 1997","l":"https://en.wikipedia.org/wiki/Sutte_Hakkun"},{"t":"Svea Rike","p":["Windows","macOS"],"d":"Target Games, Korkeken Interactive Studio AB","u":"Levande Böcker","g":"TBS","l":"https://en.wikipedia.org/wiki/Svea_Rike"},{"t":"Swagman","p":["PlayStation","Sega Saturn"],"d":"Core Design","u":"Eidos Interactive","g":"Action-adventure","r":"April 1997","l":"https://en.wikipedia.org/wiki/Swagman_(video_game)"},{"t":"Swing","p":["MS-DOS","Windows","PlayStation","Game Boy Color"],"d":"Software 2000","u":"Software 2000","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Swing_(video_game)"},{"t":"Symbiocom","p":["Windows","macOS"],"d":"Istvan Pely Productions","u":"Bethesda Softworks","g":"Adventure, Sci-Fi/Cyberpunk","r":"February 13, 1997","l":"https://en.wikipedia.org/wiki/Symbiocom"},{"t":"Syyrah: The Warp Hunter","p":["Windows"],"d":"Pixelstorm","u":"Sun Corporation","l":"https://en.wikipedia.org/wiki/Syyrah:_The_Warp_Hunter"},{"t":"Sítio do Picapau Amarelo","p":["Sega Master System"],"d":"Tec Toy","u":"Tec Toy","g":"Platform","l":"https://en.wikipedia.org/wiki/S%C3%ADtio_do_Picapau_Amarelo_(video_game)"},{"t":"Take No Prisoners","p":["Windows"],"d":"Raven Software","u":"Red Orb Entertainment","g":"Third-person shooter","r":"October 14, 1997","l":"https://en.wikipedia.org/wiki/Take_No_Prisoners_(video_game)"},{"t":"Tales of Destiny","p":["PlayStation"],"d":"Wolf Team, Namco Tales Studio","u":"Namco, Namco Hometek, Bandai Namco Games","g":"Action role-playing game","r":"December 23, 1997","l":"https://en.wikipedia.org/wiki/Tales_of_Destiny","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coa12s.jpg","s":"Tales of Destiny is a follow-up to Tales of Phantasia. Like its predecessor, it has the structure of traditional Japanese role-playing games, but substitutes turn-based combat for action-oriented one. Battles take place on separate side-scrolling screens and resemble those of a fighting game. The player controls the main hero, navigating him on the battle screen and performing various attacks and combos. Other party members are controlled by the game's AI, but it is possible to pause the battle at any time and assign new combat style to any one of them."},{"t":"Tamagotchi","p":["Game Boy"],"g":"Simulator","r":"June 27","l":"https://en.wikipedia.org/wiki/Tamagotchi_(Game_Boy_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2dou.jpg","s":"Tamagotchi is the name of a Game Boy game released in October 1997, also known as Game de Hakken!! Tamagotchi in Japan. It is very much like the original Tamagotchi, but with additional features such as music, contests, and more games."},{"t":"Tanarus","p":["Windows"],"d":"Verant Interactive","u":"Sony Interactive Studios America","g":"First-person shooter","r":"December 12, 1997","l":"https://en.wikipedia.org/wiki/Tanarus_(video_game)"},{"t":"Team 47 GoMan","p":["Windows"],"d":"47-TEK","u":"47-TEK","l":"https://en.wikipedia.org/wiki/Team_47_GoMan"},{"t":"Tekken 3","p":["Arcade"],"g":"Fighting, Arcade","r":"March 20","l":"https://en.wikipedia.org/wiki/Tekken_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co8d7q.jpg","s":"Tekken 3 is the third installment in the Tekken series. It maintains the same core fighting system as its predecessors but brings many improvements, such as significantly more detailed graphics and animations, fifteen new characters added to the game's roster, more modern music and faster gameplay."},{"t":"Temüjin","p":["Windows"],"d":"SouthPeak Interactive","u":"SouthPeak Interactive","g":"Adventure","r":"October 2, 1997","l":"https://en.wikipedia.org/wiki/Tem%C3%BCjin_(video_game)"},{"t":"Tengai Makyō: Daiyon no Mokushiroku","p":["Sega Saturn"],"r":"January 14"},{"t":"Tennis Arena","p":["PlayStation","Sega Saturn"],"d":"Smart Dog","u":"Ubi Soft","g":"Sports game","r":"November 1997","l":"https://en.wikipedia.org/wiki/Tennis_Arena"},{"t":"Terra Cresta 3D","p":["Sega Saturn"],"d":"Nichibutsu","u":"Nichibutsu","g":"Scrolling shooter","r":"August 8, 1997","l":"https://en.wikipedia.org/wiki/Terra_Cresta_3D"},{"t":"Terracide","p":["Windows"],"d":"Simis","u":"Eidos Interactive","g":"Action","r":"August 27, 1997","l":"https://en.wikipedia.org/wiki/Terracide"},{"t":"TerraFire","p":["MS-DOS"],"d":"ORT Software","u":"ORT Software","g":"Multidirectional shooter","r":"October 1, 1997","l":"https://en.wikipedia.org/wiki/TerraFire"},{"t":"Test Drive 4","p":["PlayStation","Windows"],"d":"Pitbull Syndicate","u":"Accolade","g":"Racing","r":"November 3, 1997","l":"https://en.wikipedia.org/wiki/Test_Drive_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5ywy.jpg","s":"Test Drive 4 is a racing game featuring ten different cars - five modern supercars such as the Jaguar XJ220 and TVR Cerbera, and five vintage muscle cars including three Chevrolet models. Each car has its own realistic physics, with challenging handling.\n\nThere are five full circuits, plus a drag strip. You can contest a full world championship, plus single races and ghost-car time trials. The ability to find shortcuts which is featured in the third game in the series is not included here; you must stick to the pre-defined track layout."},{"t":"Test Drive: Off-Road","p":["Windows","PlayStation"],"d":"Elite Systems","u":"Accolade, Eidos Interactive","g":"Racing","r":"March 27, 1997","l":"https://en.wikipedia.org/wiki/Test_Drive:_Off-Road"},{"t":"TetriNET","p":["Windows","macOS"],"d":"Various","g":"Puzzle","l":"https://en.wikipedia.org/wiki/TetriNET"},{"t":"Tetrisphere","p":["Nintendo 64"],"g":"Puzzle","r":"August 11","l":"https://en.wikipedia.org/wiki/Tetrisphere","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3bag.jpg","s":"Tetrisphere is a variant on Tetris in which various shapes are shifted across a wrapped three-dimensional grid resembling a sphere, and then destroyed. The objective of the game changes depending on the mode, but generally consists of removing layers of shapes to reach the playing field's core. Despite very little domestic advertising, Tetrisphere enjoyed moderately good sales and a mostly favorable critical reception. Reviewers praised the game's originality and the musical score composed by Neil D. Voss."},{"t":"The 3rd Millennium","p":[],"d":"Cryo Interactive","u":"Cryo Interactive","g":"Simulation, Strategy","l":"https://en.wikipedia.org/wiki/The_3rd_Millennium"},{"t":"The American Girls Premiere","p":["Windows","macOS"],"d":"The Learning Company","u":"The Learning Company","g":"Educational","r":"September 16, 1997","l":"https://en.wikipedia.org/wiki/The_American_Girls_Premiere"},{"t":"The Arrival","p":["macOS","Windows"],"d":"Enteraktion, Inc.","u":"Live Interactive","g":"Adventure game","r":"July 15, 1997","l":"https://en.wikipedia.org/wiki/The_Arrival_(video_game)"},{"t":"The Bombing Islands","p":["PlayStation"],"d":"Kemco, Realtime Associates","u":"Kemco","g":"Puzzle","r":"July 18, 1997","l":"https://en.wikipedia.org/wiki/The_Bombing_Islands"},{"t":"The Cassandra Galleries","p":["Windows","macOS"],"d":"Kutoka Interactive","u":"Corel","g":"Puzzle adventure","l":"https://en.wikipedia.org/wiki/The_Cassandra_Galleries"},{"t":"The City of Lost Children","p":["MS-DOS","PlayStation"],"d":"Psygnosis","u":"Psygnosis","g":"Adventure","r":"April 2, 1997","l":"https://en.wikipedia.org/wiki/The_City_of_Lost_Children_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2y6r.jpg","s":"The City of Lost Children is a third-person adventure game based on the film of the same name. Players control Miette, a young orphan navigating a bleak seaside city where children are being abducted. She explores streets, docks, and criminal hideouts, speaks with other characters, collects and uses items, and solves environmental puzzles while completing missions that overlap with the film’s story."},{"t":"The Conveni 2","p":["PlayStation","Sega Saturn"],"d":"Masterpiece","u":"Human Entertainment","g":"Business simulation","l":"https://en.wikipedia.org/wiki/The_Conveni_2"},{"t":"The Crow: City of Angels","p":["PlayStation","Sega Saturn","Windows"],"d":"Gray Matter","u":"Acclaim Entertainment","g":"Beat 'em up","r":"February 26, 1997","l":"https://en.wikipedia.org/wiki/The_Crow:_City_of_Angels_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5xdp.jpg","s":"The Crow: City of Angels is a 3D fighting game in which the player wanders from screen to screen, fighting everybody they come across with a wide variety of kicks and punches that vary based on your proximity to your foe. There is also a large range of weapons including pistols, shotguns, knives, pool cues, pipes and steel drums."},{"t":"The Curse of Monkey Island","p":["Windows","MS-DOS"],"u":"LucasArts","g":"Adventure","r":"November 1, 1997","l":"https://en.wikipedia.org/wiki/The_Curse_of_Monkey_Island","i":"images/steam-730820.jpg","s":"The only pirate adventure that asks the question: What's sharper, your sword or your wit?"},{"t":"The Day the World Broke","p":["Windows"],"u":"Houghton Mifflin Interactive","g":"Graphic adventure, puzzle","l":"https://en.wikipedia.org/wiki/The_Day_the_World_Broke"},{"t":"The Divide: Enemies Within","p":["PlayStation","Windows"],"d":"Radical Entertainment","u":"Viacom New Media","g":"Action-adventure, Metroidvania","l":"https://en.wikipedia.org/wiki/The_Divide:_Enemies_Within"},{"t":"The Feeble Files","p":["Windows","macOS","Amiga"],"d":"Adventure Soft","u":"Adventure Soft, MacPlay","g":"Adventure","r":"June 1997","l":"https://en.wikipedia.org/wiki/The_Feeble_Files"},{"t":"The Forgotten Realms Archives","p":["MS-DOS"],"d":"Strategic Simulations","u":"Interplay Productions","g":"Role-playing","r":"April 1997","l":"https://en.wikipedia.org/wiki/The_Forgotten_Realms_Archives"},{"t":"The Granstream Saga","p":["PlayStation"],"d":"Shade","u":"Sony Computer Entertainment, THQ","g":"Action role-playing","r":"November 6, 1997","l":"https://en.wikipedia.org/wiki/The_Granstream_Saga","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co66ib.jpg","s":"The Granstream Saga is an action game with strong RPG elements, and a spiritual successor to Gaia games. The player controls Eon as he explores overworld and dungeon locations, which are presented in overhead-viewed 3D. Battles are one-on-one; whenever an enemy is encountered, the view is zoomed on the combat participants who must fight each other until one of them emerges victorious. Eon can use swords, daggers, or axes against his enemies. He has a variety of attack moves at his disposal, including combos, shield-breaking abilities, etc.; he can also actively guard and cast magic spells. Leveling up, which increases Eon's attributes, occurs at set intervals throughout the game rather than from accumulating experience points."},{"t":"The Great Battles of Alexander","p":["Windows"],"d":"Erudite Software","u":"Interactive Magic","g":"Turn-based computer wargame","r":"June 22, 1997","l":"https://en.wikipedia.org/wiki/The_Great_Battles_of_Alexander"},{"t":"The Great Battles of Hannibal","p":[],"d":"Erudite Software","u":"Interactive Magic","g":"Computer wargame","r":"November 7, 1997","l":"https://en.wikipedia.org/wiki/The_Great_Battles_of_Hannibal"},{"t":"The House of the Dead","p":["Arcade"],"d":"Sega AM1","u":"Sega","g":"Light gun shooter","r":"March 1997","l":"https://en.wikipedia.org/wiki/The_House_of_the_Dead_(video_game)"},{"t":"The Incredible Hulk: The Pantheon Saga","p":["PlayStation","Sega Saturn"],"d":"Attention to Detail","u":"Eidos Interactive","g":"Platform","r":"April 10, 1997","l":"https://en.wikipedia.org/wiki/The_Incredible_Hulk:_The_Pantheon_Saga","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co52sl.jpg","s":"True to the comic books, the Hulk relies on no other weapons than his massive muscles to punch, kick and crush his enemies. When he has accumulated enough gamma energy, he may use powerful special moves like a Vortex Spin or the Floor Hammer. Rare bonus items also allow the Hulk to summon one of the four Pantheon team members Atalanta, Ulysses, Ajax and Hector to assist in the thick of battle."},{"t":"The Journeyman Project: Pegasus Prime","p":["macOS","Apple Pippin","PlayStation","Windows","Linux"],"d":"Presto Studios","u":"Bandai, Acclaim","g":"Adventure game","r":"June 1997","l":"https://en.wikipedia.org/wiki/The_Journeyman_Project:_Pegasus_Prime"},{"t":"The King of Fighters '97","p":["Neo Geo AES","Neo Geo CD","Arcade"],"g":"Fighting, Arcade","r":"July 28","l":"https://en.wikipedia.org/wiki/The_King_of_Fighters_%2797","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coc5fo.jpg","s":"The King of Fighters '97 is a 1997 fighting game produced by SNK for the Neo Geo arcade and home console. It is the fourth game in The King of Fighters series. It was ported to the Neo-Geo CD, as well as the PlayStation and the Sega Saturn in Japan only."},{"t":"The L.E.D. Wars","p":["Windows"],"d":"Larian Studios","u":"Ionos","g":"Science fiction, Real-time strategy","l":"https://en.wikipedia.org/wiki/The_L.E.D._Wars"},{"t":"The Land Before Time Activity Center","p":[],"l":"https://en.wikipedia.org/wiki/The_Land_Before_Time_Activity_Center"},{"t":"The Last Blade","p":["Arcade"],"d":"SNK","u":"SNK","g":"Fighting","r":"December 5, 1997","l":"https://en.wikipedia.org/wiki/The_Last_Blade","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co26fj.jpg","s":"The Last Blade is a fighting game developed and published by SNK and released in arcades in 1997. It is set in a fictional version of late 19th-century Japan and features a roster of sword-wielding characters. The game uses a weapon-based combat system with selectable fighting styles that emphasize speed or power. Its presentation draws heavily on historical themes and traditional Japanese aesthetics."},{"t":"The Last Express","p":["Windows","MS-DOS"],"g":"Point-and-click, Puzzle, Adventure","r":"March 30","l":"https://en.wikipedia.org/wiki/The_Last_Express","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2thd.jpg","s":"A point-and-click adventure game that takes place on a European train shortly before the outbreak of World War I. The game attempts to simulate real time with a non-linear story and dozens of fully voiced characters."},{"t":"The Lost Vikings 2","p":["Windows","MS-DOS","Super Nintendo Entertainment System","PlayStation","Sega Saturn"],"g":"Platform, Puzzle","r":"February 27","l":"https://en.wikipedia.org/wiki/The_Lost_Vikings_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1u32.jpg","s":"Will the Vikings find their way home across time and space? Will Erik lead his brothers to safety without bonking himself back into thinking he's an iguana? Will Olaf be reunited with his wife and daughters? Will Baleog ever to get a date with Freya, that Valkyrie babe on the \"Resume Game\" screen? Stay tuned..."},{"t":"The Lost World: Jurassic Park","p":["Arcade"],"d":"Sega AM3","u":"Sega","g":"Rail shooter","r":"September 1997","l":"https://en.wikipedia.org/wiki/The_Lost_World:_Jurassic_Park_(arcade_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2zbc.jpg","s":"The Lost World: Jurassic Park is an action-adventure video game developed by DreamWorks Interactive and Appaloosa Interactive, and published by Electronic Arts and Sega for the Sony PlayStation and Sega Saturn, respectively, in 1997. The Lost World: Jurassic Park is based on the film of the same name, which in turn is based on the novel by Michael Crichton. In 1998 a special edition of the game was released for the Sony PlayStation as a Greatest Hits title and featured several modifications to the gameplay."},{"t":"The Lost World: Jurassic Park","p":["Game Boy","Game Gear","Game.com","R-Zone"],"d":"Aspect, Tiger, Torus","u":"Sega, Tiger, THQ","g":"Action","r":"August 26, 1997","l":"https://en.wikipedia.org/wiki/The_Lost_World:_Jurassic_Park_(handheld_game)"},{"t":"The Lost World: Jurassic Park","p":["PlayStation","Sega Saturn"],"d":"DreamWorks Interactive, Appaloosa Interactive","u":"Electronic Arts, Sega","g":"Action-adventure","r":"August 26, 1997","l":"https://en.wikipedia.org/wiki/The_Lost_World:_Jurassic_Park_(console_game)"},{"t":"The Lost World: Jurassic Park","p":["Genesis / Mega Drive"],"d":"Appaloosa Interactive","u":"Sega","g":"Action-adventure","r":"September 16, 1997","l":"https://en.wikipedia.org/wiki/The_Lost_World:_Jurassic_Park_(Sega_Genesis_video_game)"},{"t":"The Note","p":["PlayStation"],"d":"NK System Co., Ltd.","u":"Team Bughouse, SunSoft","g":"First-person Adventure, Survival horror","r":"January 17, 1997","l":"https://en.wikipedia.org/wiki/The_Note_(video_game)"},{"t":"The Oregon Trail 3rd Edition","p":["Windows","macOS"],"d":"MECC","u":"The Learning Company","g":"Edutainment","r":"November 1997","l":"https://en.wikipedia.org/wiki/The_Oregon_Trail_3rd_Edition"},{"t":"The Pink Panther: Hokus Pokus Pink","p":["Windows"],"d":"Wanderlust Interactive","u":"Simon & Schuster, Anglia Multimedia, Ravensburger Interactive","g":"Adventure, educational, Point-and-click","r":"October 18, 1997","l":"https://en.wikipedia.org/wiki/The_Pink_Panther:_Hokus_Pokus_Pink","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2k0g.jpg","s":"A point and click adventure game on PC starring the Pink Panther."},{"t":"The Quivering","p":["MS-DOS","Windows"],"d":"Charybdis","u":"Alternative Software","g":"Point-and-click","l":"https://en.wikipedia.org/wiki/The_Quivering"},{"t":"The Reap","p":["Windows"],"d":"Housemarque","u":"Take-Two Interactive","g":"Shoot 'em up","r":"November 1997","l":"https://en.wikipedia.org/wiki/The_Reap"},{"t":"The Simpsons: Virtual Springfield","p":["Windows","macOS"],"d":"Digital Evolution","u":"Fox Interactive","g":"Adventure","r":"September 1997","l":"https://en.wikipedia.org/wiki/The_Simpsons:_Virtual_Springfield"},{"t":"The Space Bar","p":["Windows","macOS"],"d":"Boffo Games","u":"Rocket Science Games, SegaSoft","g":"Graphic adventure","r":"July 8, 1997","l":"https://en.wikipedia.org/wiki/The_Space_Bar"},{"t":"The Space Under the Window","p":[],"l":"https://en.wikipedia.org/wiki/The_Space_Under_the_Window"},{"t":"The Stone","p":[],"d":"Abject Modernity Internet Creations Inc.","u":"Abject Modernity Internet Creations Inc.","l":"https://en.wikipedia.org/wiki/The_Stone_(video_game)"},{"t":"The Tone Rebellion","p":["Windows"],"d":"The Logic Factory","u":"Virgin Interactive Entertainment","g":"Real-time strategy","r":"November 7, 1997","l":"https://en.wikipedia.org/wiki/The_Tone_Rebellion"},{"t":"The Totally Techie World of Young Dilbert","p":["Windows","macOS"],"u":"KnowWonder","l":"https://en.wikipedia.org/wiki/The_Totally_Techie_World_of_Young_Dilbert"},{"t":"The Unsolved","p":["Sega Saturn","PlayStation"],"g":"Adventure","r":"May 2, 1997","l":"https://en.wikipedia.org/wiki/The_Unsolved"},{"t":"The X-Fools","p":["Windows","macOS"],"d":"Parroty Interactive","u":"Palladium Interactive","g":"Action","r":"October 1, 1997","l":"https://en.wikipedia.org/wiki/The_X-Fools"},{"t":"Theme Hospital","p":["MS-DOS","Windows"],"d":"Bullfrog Productions, Krisalis Software","u":"Electronic Arts","g":"Business simulation","r":"March 28, 1997","l":"https://en.wikipedia.org/wiki/Theme_Hospital","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3wfx.jpg","s":"Theme Hospital is a business simulation game developed by Bullfrog Productions and published by Electronic Arts in 1997, in which the player designs and operates a hospital. Like most of Bullfrog's games, Theme Hospital is permeated by an eccentric sense of humour. The game is the thematic successor to Theme Park, a game also produced by Bullfrog. The game was a massive commercial success, selling over 4 million copies worldwide."},{"t":"Thunder Force V","p":["Sega Saturn"],"d":"Technosoft","u":"Technosoft, Working Designs","g":"Horizontal-scrolling shooter","r":"July 11, 1997","l":"https://en.wikipedia.org/wiki/Thunder_Force_V"},{"t":"Thunder Truck Rally","p":["PlayStation","Windows"],"d":"Reflections","u":"Psygnosis","g":"Racing","r":"March 1997","l":"https://en.wikipedia.org/wiki/Thunder_Truck_Rally"},{"t":"Tibia","p":["Windows","macOS","Linux"],"d":"CipSoft","u":"CipSoft","g":"MMORPG","r":"January 7, 1997","l":"https://en.wikipedia.org/wiki/Tibia_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co255g.jpg","s":"One of the earliest and most successful massively multiplayer online role-playing games (MMORPGs) in history, Tibia is a two-dimensional tile-based game set in a fantasy world with pixel art graphics and a top-down perspective. There are currently 68 game servers online, of which 24 in Europe, 25 in North America, and 19 in South America."},{"t":"TigerShark","p":["PlayStation","Windows"],"d":"n-Space","u":"GT Interactive","g":"Combat flight simulator","r":"March 25, 1997","l":"https://en.wikipedia.org/wiki/TigerShark"},{"t":"Time Crisis II","p":["Arcade"],"d":"Namco","u":"Namco, Namco Hometek, Sony Computer Entertainment","g":"Rail shooter","r":"December 13, 1997","l":"https://en.wikipedia.org/wiki/Time_Crisis_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1p35.jpg","s":"Time Crisis II is a light gun arcade game and the second installment in the Time Crisis series. It introduces co-operative multiplayer to the franchise. The game was first released in arcades in April 1998, with an enhanced port released on the PlayStation 2 in October 2001, bundled with the GunCon 2 controller."},{"t":"Timon & Pumbaa's Jungle Games","p":["Windows","macOS","Super Nintendo Entertainment System"],"d":"7th Level, Tiertex Design Studios","u":"Disney Interactive, THQ","g":"Party","r":"November 1997","l":"https://en.wikipedia.org/wiki/Timon_&_Pumbaa's_Jungle_Games"},{"t":"To Heart","p":[],"l":"https://en.wikipedia.org/wiki/To_Heart"},{"t":"Tobal 2","p":["PlayStation"],"d":"DreamFactory","u":"Square","g":"Fighting","r":"April 25, 1997","l":"https://en.wikipedia.org/wiki/Tobal_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2u6p.jpg","s":"The fighting system in Tobal 2 is the same as in the previous game. The player can freely navigate 3D fighting arenas under the condition that he or she faces the opponent. High, medium, and low attacks can be executed using assigned buttons. As in Tobal No. 1, the grappling and blocking system offers the player a variety of offensive and defensive maneuvers. A new unblockable fireball attack has been added for each character. Tobal 2 was released on the same day as Sony's Dual Analog Controller in Japan, noted as the first game compatible with the peripheral. Graphically, the game features Gouraud shaded and higher-resolution character models compared to Tobal No. 1, but still runs at 60 frames per second."},{"t":"Tobe! Polystars","p":["Arcade"],"d":"Konami","u":"Konami","g":"Scrolling shooter","r":"March 1997","l":"https://en.wikipedia.org/wiki/Tobe!_Polystars"},{"t":"TOCA Championship Racing","p":["Windows","PlayStation"],"d":"Codemasters Southam","u":"Codemasters, The 3DO Company, Imagineer, Lay-Up, Sold Out Sales & Marketing","g":"Racing, Sport","r":"November 1, 1997","l":"https://www.igdb.com/games/toca-championship-racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co9gcr.jpg","s":"Fight the pack to gain position without losing control of your car as you race on nine different original tracks of the British Touring Car Championships.\nThis game features eight different game modes, such as single race, championship, time trial, and party play.\n\nMore commonly known as TOCA Touring Car Championship, the first game of the series was released for the PC and PlayStation platforms in late 1997 in Europe, and in summer 1998 in the United States. Featuring all the licensed cars (not including privateers) and tracks from the 1997 British Touring Car Championship, the game was critically acclaimed by the European games press - especially on console where it was widely considered the best in its genre until the release of Gran Turismo several months later."},{"t":"TOCA Touring Car Championship","p":["PlayStation","Windows"],"d":"Codemasters","u":"Codemasters, 3DO, THQ","g":"Racing","r":"November 1, 1997","l":"https://en.wikipedia.org/wiki/TOCA_Touring_Car_Championship"},{"t":"Tom Clancy's Politika","p":["Windows","macOS"],"d":"Red Storm Entertainment","u":"Red Storm Entertainment","g":"Strategy","r":"November 5, 1997","l":"https://en.wikipedia.org/wiki/Tom_Clancy's_Politika"},{"t":"Tomb Raider II","p":["Windows","MS-DOS","PlayStation"],"g":"Shooter, Platform, Puzzle, Adventure","r":"November 18","l":"https://en.wikipedia.org/wiki/Tomb_Raider_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co3whn.jpg","s":"Tomb Raider II is the second game of the Tomb Raider games series. It is an action game with platforming and puzzle-solving elements, similar in concept and gameplay to its predecessor. Most of the gameplay consists of traversing hazardous 3D levels utilizing Lara's athletic skills and solving environmental puzzles. The sequel puts more emphasis on fighting enemies, adding many human foes to the mix. Additional weapons include a harpoon gun, a grenade launcher, and an M16 rifle. Automatic pistols replace the magnums from the first game."},{"t":"Tomba!","p":["PlayStation"],"d":"Whoopee Camp","u":"Whoopee Camp, Sony Computer Entertainment","g":"Platform-adventure","r":"December 25, 1997","l":"https://en.wikipedia.org/wiki/Tomba!","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co55st.jpg","s":"Tomba! is a side-scrolling platformer in which players control Tomba, a wild boy on the search for his grandfather's bangle that was stolen by some evil pigs. Although Tomba is normally restricted to a two-dimensional plane, there are certain points where he can jump or climb onto a new plane. Tomba's main method of attack is to jump on top of enemies to grab them, allowing him to hop around on them before throwing them away. This can also be used to open other objects such as eggs or treasure chests. Tomba is also able to use various projectile weapons such as maces and boomerangs and can swing on branches and poles.\n\nThe game is based around a mission system, where the main character's (Tomba's) skills are employed to complete various tasks. Completion of a mission gives a certain amount of adventure points (AP) which are required for AP boxes which contain food (which gives you AP and restores 1 space of vitality) or items, and you may for example need 50,000 AP to open one. AP is also used to gain access to special places or information later in the game. Not all missions are necessary to progress in the game, however, they are required to achieve full completion. There are 130 events (missions) in the game, many of them rely on other events to be completed."},{"t":"Tonka Search & Rescue","p":["Windows","macOS"],"d":"Media Station","u":"Hasbro Interactive","g":"Action Adventure","r":"October 1997","l":"https://en.wikipedia.org/wiki/Tonka_Search_&_Rescue"},{"t":"Tony La Russa Baseball 4","p":["Windows"],"d":"Stormfront Studios","u":"Maxis","r":"June 11, 1997","l":"https://en.wikipedia.org/wiki/Tony_La_Russa_Baseball_4"},{"t":"Top Gear Rally","p":["Nintendo 64"],"d":"Boss Game Studios","u":"Midway, Kemco","g":"Racing","r":"September 30, 1997","l":"https://en.wikipedia.org/wiki/Top_Gear_Rally","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co47wz.jpg","s":"Top Gear Rally is a 1997 racing video game developed by Boss Game Studios and released for the Nintendo 64. A follow-up to Kemco's original Top Gear game, it features a championship mode where a single player must complete six seasons of two to four races, as well as a multiplayer mode where two players may compete against each other via a split-screen display."},{"t":"Top Skater","p":["Arcade"],"d":"Sega AM3","u":"Sega","g":"Sports, racing","r":"March 15, 1997","l":"https://en.wikipedia.org/wiki/Top_Skater"},{"t":"TORCS","p":[],"l":"https://en.wikipedia.org/wiki/TORCS"},{"t":"Total Annihilation","p":["Windows","MS-DOS"],"u":"GT Interactive","g":"Strategy","r":"September 26, 1997","l":"https://en.wikipedia.org/wiki/Total_Annihilation","i":"images/steam-298030.jpg","s":"What began as a conflict over the transfer of consciousness from flesh to machines escalated into a war which has decimated a million worlds. The Core and the Arm have all but exhausted the resources of a galaxy in their struggle for domination."},{"t":"Total Drivin","p":["PlayStation"],"d":"Eutechnyx","u":"Activision, Ocean Software, Atlus","g":"Racing","r":"October 6, 1997","l":"https://en.wikipedia.org/wiki/Total_Drivin"},{"t":"Touhou Fuumaroku: The Story of Eastern Wonderland","p":["PC-9800 series"],"d":"Team Shanghai Alice","u":"Team Shanghai Alice","g":"Shooter, Indie, Arcade","r":"August 15, 1997","l":"https://www.igdb.com/games/touhou-fuumaroku-the-story-of-eastern-wonderland","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5ace.jpg","s":"The Story of Eastern Wonderland casts the player as the Shrine Maiden Reimu Hakurei and offers three distinct attack types to choose from: a wide-range type with weak attack power, a mid-range type with moderate attack power and auto-targeting capabilities, and a narrow-range type with high attack power but lowered movement speed. The bombs also exhibit unique behavior depending on the type chosen.\n\nAs the first danmaku shooting game in the Touhou Project, the Story of Eastern Wonderland introduces many features that are now hallmarks of the series as a whole: relatively small hit boxes, boss characters who are not much larger than the player character however are highly mobile, a power-up system, variable-worth point items, an unlockable Extra Stage, and a semi-complex scoring system. The game also marks the first appearance of Marisa Kirisame, who would become a major character in the series, appearing as often as Reimu Hakurei herself."},{"t":"Touhou Yumejikuu: Phantasmagoria of Dim. Dream","p":["PC-9800 series"],"d":"Team Shanghai Alice","u":"Team Shanghai Alice","g":"Shooter, Indie, Arcade","r":"December 29, 1997","l":"https://www.igdb.com/games/touhou-yumejikuu-phantasmagoria-of-dim-dream","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co7kkl.jpg","s":"This game is a vertical danmaku shooting game, where two characters engage in danmaku gameplay within individual and separate play areas (aka. split-screen). Upon meeting certain conditions, players are able to unleash a variety of character-specific Spell Attacks upon their opponents in an attempt to whittle down their remaining health points.\n\nIn Story Mode, the player will face nine opponents, each more capable than the previous. Phantasmagoria of Dim.Dream also features a Match Play Mode where the player may face off against AI opponents or compete against other players, as well as watch AI vs. AI matches."},{"t":"Trash It","p":["MS-DOS","PlayStation","Sega Saturn"],"d":"Rage Software","u":"GT Interactive","g":"Puzzle-platform","r":"July 10, 1997","l":"https://en.wikipedia.org/wiki/Trash_It"},{"t":"Treasure Hunter","p":["Windows"],"d":"Cryo Interactive Entertainment","u":"Philips Média France, Microfolie's","g":"Adventure, Educational","l":"https://en.wikipedia.org/wiki/Treasure_Hunter_(video_game)"},{"t":"Treasures of the Deep","p":["PlayStation"],"d":"Black Ops Entertainment","u":"Namco Hometek, Sony Computer Entertainment","g":"Action-adventure","r":"September 24, 1997","l":"https://en.wikipedia.org/wiki/Treasures_of_the_Deep"},{"t":"Triple Play 98","p":["PlayStation","Windows"],"d":"EA Sports","u":"EA Sports","g":"Sports video game","r":"May 13, 1997","l":"https://en.wikipedia.org/wiki/Triple_Play_98"},{"t":"Turok: Battle of the Bionosaurs","p":["Game Boy"],"d":"Bit Managers","u":"Acclaim Entertainment, Starfish Inc.","g":"Platform","r":"December 18, 1997","l":"https://en.wikipedia.org/wiki/Turok:_Battle_of_the_Bionosaurs"},{"t":"Turok: Dinosaur Hunter","p":["Windows","MS-DOS","Nintendo 64"],"g":"Shooter, Adventure","r":"February 28","l":"https://www.igdb.com/games/turok-dinosaur-hunter","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co8yzh.jpg","s":"A world where time has no meaning - and evil knows no bounds. Torn from a world long gone, the time traveling warrior Turok has found himself thrust into a savage land torn by conflict."},{"t":"Twinsen's Little Big Adventure 2 Classic","p":["MS-DOS","Windows"],"d":"Adeline Software International","u":"Electronic Arts, Activision","g":"Platform, Puzzle, Adventure","r":"May 31, 1997","l":"https://www.igdb.com/games/twinsens-little-big-adventure-2-classic","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co4qbh.jpg","s":"Here comes the sequel of Twinsen's Little Big Adventure Classic. After saving the world from the evilish Doctor Funfrock, Twinsen is now ready to face a new threat coming from outer space.\n\nOriginally released in 1997 as Little Big Adventure 2 and Twinsen's Odyssey, Twinsen's Little Big Adventure 2 Classic is an action-adventure game that became an instant classic on PC. This game contains cartoon violence."},{"t":"U.F.O.s","p":["macOS","Windows"],"d":"Artech Digital Entertainment","u":"Corel Corporation, Hoffmann + Associates","g":"Adventure","l":"https://en.wikipedia.org/wiki/U.F.O.s_(video_game)"},{"t":"Ucchannanchan no Honō no Challenger: Denryū Iraira Bō","p":["Nintendo 64"],"d":"Yuke's","u":"Hudson","g":"Puzzle","r":"December 19, 1997","l":"https://en.wikipedia.org/wiki/Ucchannanchan_no_Hon%C5%8D_no_Challenger:_Denry%C5%AB_Iraira_B%C5%8D"},{"t":"Ultima Online","p":["Windows","MS-DOS"],"g":"Adventure, Casual, Massively Multiplayer, Simulation, Sports, Free To Play","r":"September 24","l":"https://en.wikipedia.org/wiki/Ultima_Online","i":"images/steam-2068100.jpg","s":"Ultimate Fishing® Online is a free-to-play multiplayer fishing game set in ecosystems with various fish, reactive shoals, dynamic weather &amp; day-night cycles. Explore diverse fishing spots, customize gear &amp; use various techniques! Cast, Catch &amp; Compete!"},{"t":"Umihara Kawase Shun","p":["PlayStation"],"d":"Jackpot, Rocket Studios, Suzak, Studio Saizensen","u":"XING, Marvelous Entertainment, Genterprise","g":"Platformer","r":"February 28, 1997","l":"https://en.wikipedia.org/wiki/Umihara_Kawase_Shun"},{"t":"Uprising: Join or Die","p":["Windows"],"d":"Cyclone Studios","u":"The 3DO Company","g":"Action, real-time strategy","r":"October 14, 1997","l":"https://en.wikipedia.org/wiki/Uprising:_Join_or_Die"},{"t":"V-Rally","p":["PlayStation","Mobile phone"],"d":"Infogrames Multimedia","u":"Infogrames Multimedia, Electronic Arts, Ocean, Infogrames","g":"Racing","r":"July 4, 1997","l":"https://en.wikipedia.org/wiki/V-Rally_(video_game)"},{"t":"Vampire Savior","p":["Arcade"],"d":"Capcom","u":"Capcom, Virgin Interactive Entertainment","g":"Fighting","r":"May 1997","l":"https://en.wikipedia.org/wiki/Vampire_Savior"},{"t":"Vampire Savior 2: The Lord of Vampire","p":["Arcade"],"d":"Capcom","u":"Capcom","g":"Fighting, Arcade","r":"September 1, 1997","l":"https://www.igdb.com/games/vampire-savior-2-the-lord-of-vampire","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5xrk.jpg","s":"Released in Japan in 1997, Vampire Savior 2 was released along side Vampire Hunter 2 and uses the same gameplay mechanics as Vampire Savior. The game adds Night Warriors: Darkstalkers' Revenge characters Donovan Baine, Huitzil and Pyron to the Vampire Savior cast while omitting Jon Talbain, Rikuo (Aulbath), and Sasquatch.\n\nAlthough the game was never officially released in arcades outside of Japan, the game was incorporated into Darkstalkers 3 and later as its own standard game in the Japanese only release of Vampire: Darkstalkers Collection."},{"t":"Vampire Savior: The Lord of Vampire","p":["Arcade"],"d":"Capcom","u":"Capcom","g":"Fighting, Arcade","r":"May 1, 1997","l":"https://www.igdb.com/games/vampire-savior-the-lord-of-vampire","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/coc9ds.jpg","s":"This is the 3rd in the Darkstalkers series. It plays much the same as the first, but features better animation, more playable characters, and a deeper storyline."},{"t":"Vandal Hearts","p":["PlayStation","Sega Saturn"],"r":"March 26","l":"https://en.wikipedia.org/wiki/Vandal_Hearts"},{"t":"Vantage Master","p":["Windows"],"d":"Nihon Falcom","u":"Nihon Falcom","g":"Tactical RPG","r":"December 12, 1997","l":"https://en.wikipedia.org/wiki/Vantage_Master"},{"t":"Versailles 1685","p":["Windows","PlayStation"],"d":"Cryo Interactive Entertainment","u":"Cryo Interactive Entertainment, Canal+ Multimedia, Réunion des Musées Nationaux","g":"Adventure","l":"https://en.wikipedia.org/wiki/Versailles_1685"},{"t":"Virtua Striker 2","p":["Arcade"],"d":"Sega AM2","u":"Sega","g":"Sports","r":"June 1997","l":"https://en.wikipedia.org/wiki/Virtua_Striker_2"},{"t":"Virtual Hiryū no Ken","p":["PlayStation"],"u":"Culture Brain","g":"Fighting action","r":"July 17, 1997","l":"https://en.wikipedia.org/wiki/Virtual_Hiry%C5%AB_no_Ken"},{"t":"Virtual Pool 2","p":["Windows"],"d":"Celeris","u":"VR Sports","g":"Sports simulation – pool","r":"November 20, 1997","l":"https://en.wikipedia.org/wiki/Virtual_Pool_2"},{"t":"Virtual Pro Wrestling 64","p":["Nintendo 64"],"d":"Asmik Ace Entertainment, AKI Corporation","u":"Asmik Ace Entertainment","g":"Wrestling","r":"December 19, 1997","l":"https://en.wikipedia.org/wiki/Virtual_Pro_Wrestling_64"},{"t":"Virtual Safari","p":["Windows"],"d":"Anglia Multimedia","u":"Fujitsu Interactive","g":"Edutainment","r":"March 31, 1997","l":"https://en.wikipedia.org/wiki/Virtual_Safari"},{"t":"Virus","p":["Sega Saturn"],"d":"Hudson Soft","u":"Hudson Soft","g":"Action-adventure","r":"August 22, 1997","l":"https://en.wikipedia.org/wiki/Virus_(1997_video_game)"},{"t":"Virus: The Game","p":["Windows"],"d":"Kidum Multimedia Ltd.","u":"Sir-Tech Software Inc., Telstar","g":"Action/Strategy, Shooter","r":"November 13, 1997","l":"https://en.wikipedia.org/wiki/Virus:_The_Game"},{"t":"Vlad Tepes Dracula","p":["Windows"],"d":"ComputerHouse GBG AB","u":"The Learning Company / SoftKey Multimedia","g":"Turn-Based Strategy, Real-time tactics","l":"https://en.wikipedia.org/wiki/Vlad_Tepes_Dracula"},{"t":"VMX Racing","p":["PlayStation"],"d":"Studio e","u":"Funsoft, Playmates Interactive Entertainment","g":"Racing","r":"July 1997","l":"https://en.wikipedia.org/wiki/VMX_Racing"},{"t":"Voice Fantasia","p":["Sega Saturn","PlayStation"],"d":"Pre-Stage, Japan Media Programming","u":"ASK Kodansha","g":"Role-playing","r":"July 25, 1997","l":"https://en.wikipedia.org/wiki/Voice_Fantasia"},{"t":"Voodoo Kid","p":["Windows"],"u":"Infogrames","g":"Adventure","l":"https://en.wikipedia.org/wiki/Voodoo_Kid"},{"t":"VR Baseball '97","p":["PlayStation","Windows"],"d":"VR Sports","u":"Interplay Productions","g":"Sports","r":"April 1, 1997","l":"https://en.wikipedia.org/wiki/VR_Baseball_'97"},{"t":"Vs.","p":["PlayStation"],"d":"Polygon Magic","u":"THQ","g":"Fighting game","r":"December 2, 1997","l":"https://en.wikipedia.org/wiki/Vs._(video_game)"},{"t":"War Inc.","p":["MS-DOS"],"d":"Optik Software","u":"Interactive Magic","g":"Real-time strategy","r":"September 5, 1997","l":"https://en.wikipedia.org/wiki/War_Inc."},{"t":"War Wind II: Human Onslaught","p":["Windows"],"d":"DreamForge Intertainment","u":"Strategic Simulations","g":"Real-time strategy","r":"November 26, 1997","l":"https://en.wikipedia.org/wiki/War_Wind_II:_Human_Onslaught"},{"t":"Warlords III","p":["Windows"],"d":"Strategic Studies Group","u":"Red Orb Entertainment","g":"Computer wargame, 4x","r":"August 12, 1997","l":"https://en.wikipedia.org/wiki/Warlords_III"},{"t":"Warlords III: Reign of Heroes","p":["Windows","MS-DOS"],"g":"Strategy, Turn-based strategy (TBS)","r":"July 31","l":"https://www.igdb.com/games/warlords-iii-reign-of-heroes","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co7a61.jpg","s":"Warlords III: Reign of Heroes is a turn-based strategy game set in a fantasy universe.\n\nThe Selentine Empire has been overrun by undead and a number of warlords are fighting to determine who will control what remains of the world. Players must build armies to conquer cities and overwhelm their opponents. The game features 84 different unit types, each of which has different combat strengths, and movement points.\n\nPlayers can use the random map generator to play single games, there are 12 stand-alone game scenarios, plus a campaign mode. Diplomacy is possible and the user can choose from a range of different victory conditions: Last Warlord Standing, Most Cities, Most Victory Points, Most Money."},{"t":"Wayne Gretzky's 3D Hockey '98","p":["Nintendo 64","PlayStation"],"d":"Software Creations","u":"Midway","g":"Sports","r":"December 3, 1997","l":"https://en.wikipedia.org/wiki/Wayne_Gretzky's_3D_Hockey_'98"},{"t":"WCW vs. nWo: World Tour","p":["Nintendo 64"],"g":"Sport","r":"November 30","l":"https://www.igdb.com/games/wcw-vs-nwo-world-tour","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co5xsp.jpg","s":"Over 40 wrestlers in all, including over 20 WCW and NWO superstars like Hollywood Hogan, Sting, The Giant, Lex Luger, Ric Flair, The Outsiders and many more! Each wrestler is capable of performing 30 to 40 moves, including his own signature moves! Featuring five different gameplay modes, Tag Team and simultaneous four-player action!"},{"t":"William Shakespeare's Hamlet: A Murder Mystery","p":["Windows","macOS"],"d":"Pantheon Productions","u":"EMME Interactive","l":"https://en.wikipedia.org/wiki/William_Shakespeare's_Hamlet:_A_Murder_Mystery"},{"t":"Wing Commander: Prophecy","p":["Windows","MS-DOS"],"g":"Shooter, Simulator","r":"November 30","l":"https://www.igdb.com/games/wing-commander-prophecy","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2kkb.jpg","s":"Wing Commander: Prophecy, the fifth installment in the acclaimed space combat series, introduces a new generation of pilots in a post-war galaxy. Players assume the role of rookie Lance Casey aboard the TCS Midway, facing an unexpected alien threat foretold by ancient Kilrathi prophecy. Set against the backdrop of a fragile peace following the Border Worlds conflict, the game combines intense space combat with late 90s FMV storytelling. Pilots engage in dangerous missions, wielding an arsenal of advanced weaponry to defend the Confederation against a mysterious force that threatens the universe's existence."},{"t":"Winter Heat","p":["Arcade"],"d":"Sega AM3, Data East","u":"Sega","g":"Sports","l":"https://en.wikipedia.org/wiki/Winter_Heat"},{"t":"Wishbone Activity Zone","p":[],"l":"https://en.wikipedia.org/wiki/Wishbone_Activity_Zone"},{"t":"World Series Baseball '98","p":["Sega Saturn","Genesis / Mega Drive"],"d":"Sega","u":"Sega","g":"Sports","r":"March 28, 1997","l":"https://en.wikipedia.org/wiki/World_Series_Baseball_'98"},{"t":"World Tour Racing","p":["Atari Jaguar CD"],"d":"Teque London","u":"Telegames","g":"Racing","r":"June 4, 1997","l":"https://en.wikipedia.org/wiki/World_Tour_Racing"},{"t":"Worms 2","p":["Windows","MS-DOS"],"g":"Shooter, Platform, Strategy","r":"November 21","l":"https://en.wikipedia.org/wiki/Worms_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co1xjb.jpg","s":"Worms 2 is a turn-based strategy game, with each team moving in a randomly determined sequence across two-dimensional terrain. During a single turn, a team can only move one of its worms. Worms can crawl and jump, as well as swing by ninja-rope, parachute, teleport, and bungee when the appropriate items are available. The objective of a traditional match or campaign mission is to defeat all opposing teams by killing their worms. When hit with a weapon, the worm will lose health depending on the power of the weapon and the directness of the hit. A worm can be killed either by having its health reduced to zero or being knocked into the water around and below the level."},{"t":"Worms: The Director's Cut","p":["Amiga"],"d":"Team17","u":"Ocean Software","g":"Artillery, strategy","l":"https://en.wikipedia.org/wiki/Worms:_The_Director's_Cut"},{"t":"X-COM: Apocalypse","p":["MS-DOS"],"d":"Mythos Games","u":"MicroProse","g":"Turn-based/real-time tactics","r":"July 15, 1997","l":"https://en.wikipedia.org/wiki/X-COM:_Apocalypse","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co2g7i.jpg","s":"Your mission, as X-COM Commander, is to combat alien aggression and uncover their deadly intentions. But Beware! Alien infiltration into the city and its politics could see you under fire from criminal gangs, religious sects, and even the police! Alien fleets fill the skies, creatures terrorise the city, chaos reigns... Welcome to the war, welcome to the Apocalypse."},{"t":"X-Men: The Ravages of Apocalypse","p":["MS-DOS","Windows","Linux","macOS"],"d":"Zero Gravity Entertainment","u":"WizardWorks, MacSoft","g":"First-person shooter","r":"December 5, 1997","l":"https://en.wikipedia.org/wiki/X-Men:_The_Ravages_of_Apocalypse"},{"t":"XCar: Experimental Racing","p":["MS-DOS"],"d":"MediaTech West","u":"Bethesda Softworks","g":"Racing","r":"August 22, 1997","l":"https://en.wikipedia.org/wiki/XCar:_Experimental_Racing"},{"t":"Yaku Tsuu: Noroi no Game","p":["PlayStation"],"d":"Idea Factory","g":"Adventure","r":"February 7, 1997","l":"https://en.wikipedia.org/wiki/Yaku_Tsuu:_Noroi_no_Game"},{"t":"Yoshi's Story","p":["Nintendo 64"],"g":"Platform, Adventure","r":"December 21","l":"https://en.wikipedia.org/wiki/Yoshi%27s_Story","i":"https://images.igdb.com/igdb/image/upload/t_cover_big/co260t.jpg","s":"Baby Bowser has taken the Super Happy Tree and cast a spell on Yoshi's world, turning it into the pages of a picture book. The only Yoshis not affected by the spell were six hatchlings that were still protected by their shells. It's up to them to reclaim the Super Happy Tree and restore happiness to the world. That is the only thing that can break Baby Bowser's Spell!"},{"t":"You Don't Know Jack Movies","p":[],"l":"https://en.wikipedia.org/wiki/You_Don't_Know_Jack_Movies"},{"t":"You Don't Know Jack Sports: The Netshow","p":[],"l":"https://en.wikipedia.org/wiki/You_Don't_Know_Jack_Sports:_The_Netshow"},{"t":"You Don't Know Jack Television","p":[],"l":"https://en.wikipedia.org/wiki/You_Don't_Know_Jack_Television"},{"t":"You Don't Know Jack Vol. 3","p":[],"l":"https://en.wikipedia.org/wiki/You_Don't_Know_Jack_Vol._3"},{"t":"Zap! Snowboarding Trix","p":["Sega Saturn"],"d":"Atelier Double","u":"Pony Canyon","g":"Snowboarding video game","r":"February 21, 1997","l":"https://en.wikipedia.org/wiki/Zap!_Snowboarding_Trix"},{"t":"Zero 5","p":["Atari Jaguar"],"d":"Caspian Software","u":"Telegames, Terre du Milieu","g":"Shooter","r":"September 29, 1997","l":"https://en.wikipedia.org/wiki/Zero_5_(Atari_Jaguar_video_game)"},{"t":"Zero Divide 2","p":["PlayStation"],"d":"Zoom","u":"Zoom, Sony Computer Entertainment","g":"Fighting","r":"June 27, 1997","l":"https://en.wikipedia.org/wiki/Zero_Divide_2"},{"t":"Zero Gunner","p":["Arcade"],"d":"Psikyo","u":"Psikyo","g":"Shoot 'em up","r":"December 1997","l":"https://en.wikipedia.org/wiki/Zero_Gunner"},{"t":"Zero Zero","p":["Windows","macOS"],"d":"Nicholson New York","u":"Magnet Interactive Studios","g":"Adventure","l":"https://en.wikipedia.org/wiki/Zero_Zero_(video_game)"},{"t":"Zero4 Champ","p":["PC Engine"],"d":"Media Rings","u":"Media Rings","g":"Racing video game","l":"https://en.wikipedia.org/wiki/Zero4_Champ"},{"t":"Zero4 Champ DooZy-J Type-R","p":["Sega Saturn","PlayStation"],"d":"Media Rings","u":"Media Rings","g":"Racing","r":"June 20, 1997","l":"https://en.wikipedia.org/wiki/Zero4_Champ_DooZy-J_Type-R"},{"t":"Zone Warrior","p":["macOS"],"d":"Julian James","u":"Casady & Greene","g":"Space combat simulator","l":"https://en.wikipedia.org/wiki/Zone_Warrior"},{"t":"Zork: Grand Inquisitor","p":["Windows","MS-DOS"],"g":"Adventure","r":"October 31","l":"https://store.steampowered.com/app/570680","i":"images/steam-570680.jpg","s":"Join forces with Dungeon Master Dalboz and travel throughout the Underground Empire's many locations, such as Hades, Flood Control Dam #3 and The Dungeon Master's Lair."},{"t":"Zork: The Undiscovered Underground","p":["Commodore 64"],"d":"Implementors","u":"Activision","g":"Interactive fiction","r":"August 28, 1997","l":"https://en.wikipedia.org/wiki/Zork:_The_Undiscovered_Underground"}];
